{"version":3,"file":"sdk-editor.js","sources":["../src/experiences/runtime/BuilderContentContract.ts","../src/experiences/runtime/BuilderContent.ts","../src/experiences/runtime/layering/StackingContextResolver.ts","../src/experiences/runtime/layering/LayerManager.ts","../src/experiences/runtime/ChecklistRenderer.ts","../src/experiences/editor/ChecklistEditor.ts","../src/experiences/types.ts","../src/experiences/checklist/ChecklistMarkup.ts","../src/experiences/survey/SurveyMarkup.ts","../src/experiences/onsite/OnsiteDocument.ts","../src/experiences/survey/SurveyLogic.ts","../src/experiences/editor/SurveyEditing.ts","../src/experiences/editor/SurveyEditor.ts","../src/experiences/editorContinuation.ts","../src/dom/RouteObserver.ts","../src/experiences/runtime/WidgetSizing.ts","../src/experiences/runtime/AnchoredTargetBackdrop.ts","../src/experiences/runtime/AnchoredCardRenderer.ts","../src/experiences/runtime/ToastRenderer.ts","../src/experiences/runtime/CursorFollowRenderer.ts","../src/experiences/runtime/ModalRenderer.ts","../src/experiences/runtime/SlideoutRenderer.ts","../src/experiences/runtime/HotspotRenderer.ts","../src/experiences/runtime/BannerRenderer.ts","../src/experiences/runtime/SurveyRenderer.ts","../src/experiences/runtime/GuideStepLogic.ts","../src/experiences/runtime/ExperienceRenderer.ts","../src/experiences/editor/EditorBridge.ts","../src/experiences/editor/HighlightOverlay.ts","../src/privacy/SensitiveElementDetector.ts","../src/dom/ElementLabeler.ts","../src/experiences/editor/TargetSelectorGenerator.ts","../src/experiences/editor/ElementPicker.ts","../src/experiences/editor/EditorSelection.ts","../src/experiences/editor/OnsiteContentEditor.ts","../src/experiences/editor/ImageFile.ts","../src/experiences/editor/AiEditing.ts","../src/experiences/editor/OnsiteCompositionEditor.ts","../src/themes/ExperienceTheme.ts","../src/experiences/editor/SurveyAiEditing.ts","../src/experiences/editor/ChecklistAiEditing.ts","../src/experiences/editor/EditorModeController.ts","../src/experiences/editorBundleEntry.ts"],"sourcesContent":["/** Runtime mirror of the backend-authoritative builder security contract. */\nexport const BUILDER_ALLOWED_TAGS = new Set([\"DIV\", \"SECTION\", \"HEADER\", \"H1\", \"H2\", \"H3\", \"H4\", \"P\", \"SPAN\", \"BR\", \"BUTTON\", \"IMG\", \"HR\", \"LABEL\", \"STRONG\", \"EM\", \"U\", \"A\", \"UL\", \"OL\", \"LI\"]);\nexport const BUILDER_SURVEY_INPUT_TAGS = new Set([\"INPUT\", \"TEXTAREA\"]);\nexport const BUILDER_ALLOWED_ATTRIBUTES = new Set([\"class\", \"id\", \"title\", \"role\", \"aria-label\", \"aria-live\", \"aria-hidden\", \"aria-pressed\", \"aria-required\", \"alt\", \"src\", \"href\", \"target\", \"rel\", \"width\", \"height\", \"type\", \"placeholder\", \"maxlength\", \"data-movcues-action-id\", \"data-movcues-content\", \"data-movcues-widget-type\", \"data-movcues-document-version\", \"data-movcues-node-id\", \"data-movcues-block-id\", \"data-movcues-sizing\", \"data-movcues-responsive-stack\", \"data-movcues-question-id\", \"data-movcues-question-type\", \"data-movcues-question-input\", \"data-movcues-option-id\", \"data-movcues-survey-action\", \"data-movcues-survey-controls\", \"data-movcues-survey-progress\", \"data-movcues-survey-progress-bar\", \"data-movcues-survey-step-id\", \"data-movcues-checklist-role\", \"data-movcues-checklist-item-id\", \"data-movcues-checklist-item-role\", \"data-movcues-checklist-view\"]);\nexport const BUILDER_BLOCKED_TAGS = /^(SCRIPT|STYLE|IFRAME|OBJECT|EMBED|FORM|INPUT|TEXTAREA|SELECT|VIDEO|AUDIO|SOURCE)$/i;\nexport const BUILDER_UNSAFE_CSS = /@import|expression\\s*\\(|javascript\\s*:|behavior\\s*:|-moz-binding/i;\n\nexport function builderImageUrlIsSafe(value: string): boolean { return !value || (!/[\\u0000-\\u0020\\u007f]/.test(value) && /^(https?:\\/\\/|data:image\\/(?:png|gif|jpeg|webp);base64,|\\/)/i.test(value)); }\nexport function builderLinkUrlIsSafe(value: string): boolean { return !/[\\u0000-\\u001f\\u007f]/.test(value) && /^(https?:\\/\\/|mailto:|tel:|\\/|#|\\?|\\.\\.?\\/)/i.test(value.trim()); }\nexport function builderInputTypeIsSafe(value: string): boolean { return [\"text\", \"radio\", \"checkbox\", \"number\"].includes(value.toLowerCase()); }\nexport function safeScopedBuilderCss(input: string): string | null {\n  const css = input.replace(/\\/\\*[\\s\\S]*?\\*\\//g, \"\").trim();\n  if (BUILDER_UNSAFE_CSS.test(css)) return null;\n  const rule = /([^{}]+)\\{/g; let match: RegExpExecArray | null;\n  while ((match = rule.exec(css)) !== null) {\n    const prelude = match[1].trim();\n    if (!prelude || prelude.startsWith(\"@\")) continue;\n    if (prelude.split(\",\").some((selector: string) => !selector.trim().includes(\".movcues-widget\"))) return null;\n  }\n  return css;\n}\n","import type { WidgetBuilderState } from \"../types\";\nimport type { RenderCallbacks } from \"./AnchoredCardRenderer\";\nimport { BUILDER_ALLOWED_ATTRIBUTES, BUILDER_ALLOWED_TAGS, BUILDER_BLOCKED_TAGS, BUILDER_SURVEY_INPUT_TAGS, builderImageUrlIsSafe, builderInputTypeIsSafe, builderLinkUrlIsSafe, safeScopedBuilderCss } from \"./BuilderContentContract\";\nexport type BuilderAction = { id: string; type: \"next_step\" | \"previous_step\" | \"dismiss\" } | { id: string; type: \"open_url\"; url: string } | { id: string; type: \"track_event\"; eventName: string };\nexport type BuilderRenderCallbacks = RenderCallbacks & { onActionId?: (action: BuilderAction, label: string) => void };\n\nexport function mountBuilderContent(root: ShadowRoot, card: HTMLElement, builder: WidgetBuilderState, callbacks: BuilderRenderCallbacks, allowSurveyInputs = false): boolean {\n  const html = sanitizeBuilderHtml(builder.html, allowSurveyInputs);\n  const css = safeBuilderCss(builder.css);\n  if (!html || css === null) return false;\n  let style = root.querySelector<HTMLStyleElement>(\"style[data-movcues-builder-style]\");\n  if (!style) { style = document.createElement(\"style\"); style.dataset.movcuesBuilderStyle = \"\"; root.appendChild(style); }\n  style.textContent = `${css}\\n${ISOLATION_CSS}`;\n  const content = document.createElement(\"div\");\n  content.className = \"builder-content\";\n  content.dataset.movcuesBuilderSurface = \"\";\n  content.append(...html);\n  card.appendChild(content);\n  card.classList.add(\"builder-card\");\n  card.addEventListener(\"click\", event => {\n    const target = event.target instanceof Element ? event.target.closest<HTMLElement>(\"[data-movcues-action-id]\") : null;\n    if (!target || !card.contains(target)) return;\n    const actionId = target.dataset.movcuesActionId;\n    if (actionId === \"primary\") callbacks.onPrimary();\n    else if (actionId === \"secondary\") callbacks.onSecondary();\n    else {\n      const action = findOnsiteAction(builder, actionId ?? \"\");\n      if (action) callbacks.onActionId?.(action, target.textContent?.trim() ?? \"\");\n    }\n  });\n  return true;\n}\n\n// Keep the builder surface scoped, but do not clip its visual overflow. The\n// authored widget owns internal scrolling (`.movcues-widget { overflow: â€¦ }`)\n// while shadows, outlines, and corner decorations must be able to paint beyond\n// its layout box just as they do in the GrapesJS canvas.\nconst ISOLATION_CSS = `[data-movcues-builder-surface]{position:relative;overflow:visible;contain:layout style}[data-movcues-builder-surface]>.movcues-widget{position:relative!important;inset:auto!important}`;\n\nexport function sanitizeBuilderHtml(input: string, allowSurveyInputs = false): ChildNode[] | null {\n  const template = document.createElement(\"template\");\n  template.innerHTML = input;\n  for (const element of Array.from(template.content.querySelectorAll(\"*\"))) {\n    const allowedTag = BUILDER_ALLOWED_TAGS.has(element.tagName) || (allowSurveyInputs && BUILDER_SURVEY_INPUT_TAGS.has(element.tagName));\n    if (!allowedTag) {\n      if (BUILDER_BLOCKED_TAGS.test(element.tagName)) element.remove();\n      else element.replaceWith(...Array.from(element.childNodes));\n      continue;\n    }\n    for (const attribute of Array.from(element.attributes)) {\n      const name = attribute.name.toLowerCase();\n      if (!BUILDER_ALLOWED_ATTRIBUTES.has(name) || name.startsWith(\"on\") || /javascript\\s*:/i.test(attribute.value)) element.removeAttribute(attribute.name);\n    }\n    const action = element.getAttribute(\"data-movcues-action-id\");\n    if (action && action !== \"primary\" && action !== \"secondary\" && !/^[A-Za-z][A-Za-z0-9_-]{2,63}$/.test(action)) element.removeAttribute(\"data-movcues-action-id\");\n    const surveyAction = element.getAttribute(\"data-movcues-survey-action\");\n    if (surveyAction && surveyAction !== \"back\" && surveyAction !== \"next\" && surveyAction !== \"submit\") element.removeAttribute(\"data-movcues-survey-action\");\n    if (element.tagName === \"IMG\") {\n      const source = element.getAttribute(\"src\") ?? \"\";\n      if (!builderImageUrlIsSafe(source)) element.removeAttribute(\"src\");\n    }\n    if (element.hasAttribute(\"src\") && element.tagName !== \"IMG\") element.removeAttribute(\"src\");\n    if (element.tagName === \"A\") {\n      const href = element.getAttribute(\"href\") ?? \"\";\n      if (!builderLinkUrlIsSafe(href)) element.removeAttribute(\"href\");\n      const target = element.getAttribute(\"target\");\n      if (target && target !== \"_blank\" && target !== \"_self\") element.removeAttribute(\"target\");\n      if (target === \"_blank\") element.setAttribute(\"rel\", \"noopener noreferrer\");\n    } else {\n      element.removeAttribute(\"href\"); element.removeAttribute(\"target\"); element.removeAttribute(\"rel\");\n    }\n    if (element.tagName === \"INPUT\") {\n      const type = (element.getAttribute(\"type\") ?? \"text\").toLowerCase();\n      if (!builderInputTypeIsSafe(type)) element.setAttribute(\"type\", \"text\");\n    }\n  }\n  const root = template.content.querySelector(\".movcues-widget\");\n  if (!root) return null;\n  for (const slot of [\"primary\", \"secondary\"]) {\n    const actions = Array.from(template.content.querySelectorAll(`[data-movcues-action-id=\"${slot}\"]`));\n    actions.slice(1).forEach(action => action.remove());\n  }\n  return Array.from(template.content.childNodes);\n}\n\nfunction findOnsiteAction(builder: WidgetBuilderState, id: string): BuilderAction | null {\n  const movcues = builder.projectData.movcues; const bindings = movcues && typeof movcues === \"object\" ? (movcues as Record<string, unknown>).actionBindings : null;\n  const candidate = bindings && typeof bindings === \"object\" ? (bindings as Record<string, unknown>)[id] : null;\n  if (!candidate || typeof candidate !== \"object\") return null;\n  const action = candidate as Record<string, unknown>;\n  if (action.id !== id || ![\"next_step\", \"previous_step\", \"dismiss\", \"open_url\", \"track_event\"].includes(String(action.type))) return null;\n  if (action.type === \"open_url\" && (typeof action.url !== \"string\" || !/^https?:\\/\\//i.test(action.url) || !builderLinkUrlIsSafe(action.url))) return null;\n  if (action.type === \"track_event\" && (typeof action.eventName !== \"string\" || !action.eventName.trim() || action.eventName.length > 200)) return null;\n  return action as BuilderAction;\n}\n\nexport function safeBuilderCss(input: string): string | null {\n  return safeScopedBuilderCss(input);\n}\n","export interface StackingContextEntry {\n  element: Element;\n  zIndex: number | null;\n  createsStackingContext: boolean;\n}\n\nexport interface StackingContextInfo {\n  /** The outermost context that controls how the target participates in the document stack. */\n  element: Element | null;\n  zIndex: number;\n  /** Ordered from the inspected element toward the document root. */\n  chain: StackingContextEntry[];\n}\n\nexport class StackingContextResolver {\n  resolve(element: Element | null): StackingContextInfo {\n    if (!element) return { element: null, zIndex: 0, chain: [] };\n    const chain: StackingContextEntry[] = [];\n    let current: Element | null = element;\n    while (current && current !== document.documentElement) {\n      const style = getComputedStyle(current);\n      chain.push({ element: current, zIndex: numericZIndex(style.zIndex), createsStackingContext: createsStackingContext(style) });\n      current = current.parentElement;\n    }\n    const outermost = [...chain].reverse().find(entry => entry.createsStackingContext);\n    return { element: outermost?.element ?? null, zIndex: outermost?.zIndex ?? 0, chain };\n  }\n}\n\nfunction numericZIndex(value: string): number | null {\n  if (!value || value === \"auto\") return null;\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? Math.trunc(parsed) : null;\n}\n\nfunction createsStackingContext(style: CSSStyleDeclaration): boolean {\n  const position = style.position;\n  if (((position === \"absolute\" || position === \"relative\") && numericZIndex(style.zIndex) !== null) || position === \"fixed\" || position === \"sticky\") return true;\n  if (Number.parseFloat(style.opacity || \"1\") < 1) return true;\n  if (property(style, \"transform\") !== \"none\" || property(style, \"filter\") !== \"none\" || property(style, \"perspective\") !== \"none\") return true;\n  if (style.isolation === \"isolate\" || (!!style.mixBlendMode && style.mixBlendMode !== \"normal\")) return true;\n  const contain = property(style, \"contain\");\n  if (/(^|\\s)(layout|paint|strict|content)(\\s|$)/.test(contain)) return true;\n  const willChange = property(style, \"willChange\").split(\",\").map(value => value.trim());\n  return willChange.some(value => [\"transform\", \"opacity\", \"filter\", \"perspective\", \"contain\"].includes(value));\n}\n\nfunction property(style: CSSStyleDeclaration, name: \"transform\" | \"filter\" | \"perspective\" | \"contain\" | \"willChange\"): string {\n  return (style[name] || \"none\").trim();\n}\n","import type { ExperienceLayer, ExperienceTarget } from \"../../types\";\nimport { StackingContextResolver, type StackingContextInfo } from \"./StackingContextResolver\";\n\n/** Maximum ordinary CSS layer. Native dialog/popover top-layer content can still render above it. */\nexport const ALWAYS_ON_TOP_Z_INDEX = 2_147_483_000;\nexport const SAFE_DEFAULT_Z_INDEX = 1;\n\nexport interface LayerResolution {\n  zIndex: number;\n  mode: ExperienceLayer[\"mode\"] | \"legacy\";\n  context: StackingContextInfo | null;\n  fallback?: \"relative_target_missing\";\n}\n\nexport interface LayerOptions {\n  layer?: ExperienceLayer;\n  legacyZIndex?: number;\n  targetElement?: Element | null;\n}\n\nexport interface AppliedLayer {\n  refresh(): LayerResolution;\n  destroy(): void;\n}\n\nexport class LayerManager {\n  constructor(\n    private resolver = new StackingContextResolver(),\n    private findTarget: (target: ExperienceTarget) => Element | null = findUniqueTarget,\n  ) {}\n\n  resolve(options: LayerOptions): LayerResolution {\n    if (!options.layer) {\n      if (options.legacyZIndex !== undefined) return { zIndex: options.legacyZIndex, mode: \"legacy\", context: null };\n      return { zIndex: ALWAYS_ON_TOP_Z_INDEX, mode: \"legacy\", context: null };\n    }\n    const layer = options.layer;\n    if (layer.mode === \"always_on_top\") return { zIndex: ALWAYS_ON_TOP_Z_INDEX, mode: layer.mode, context: null };\n    if (layer.mode === \"custom\") return { zIndex: layer.zIndex, mode: layer.mode, context: null };\n    if (layer.mode === \"relative\") {\n      const reference = this.findTarget(layer.target);\n      if (!reference) {\n        const automatic = this.auto(options.targetElement);\n        return { ...automatic, mode: layer.mode, fallback: \"relative_target_missing\" };\n      }\n      const context = this.resolver.resolve(reference);\n      return { zIndex: bounded(context.zIndex + (layer.relation === \"above\" ? 1 : -1)), mode: layer.mode, context };\n    }\n    return this.auto(options.targetElement);\n  }\n\n  private auto(targetElement?: Element | null): LayerResolution {\n    const context = this.resolver.resolve(targetElement ?? null);\n    return { zIndex: targetElement ? bounded(context.zIndex + 1) : SAFE_DEFAULT_Z_INDEX, mode: \"auto\", context };\n  }\n\n  apply(host: HTMLElement, options: LayerOptions): AppliedLayer {\n    let observers: MutationObserver[] = [];\n    let active = true;\n    let frameId: number | null = null;\n    let last!: LayerResolution;\n    const disconnect = () => { observers.forEach(observer => observer.disconnect()); observers = []; };\n    const refresh = () => {\n      if (!active) return last;\n      if (frameId !== null) { cancelAnimationFrame(frameId); frameId = null; }\n      disconnect();\n      const resolution = this.resolve(options);\n      last = resolution;\n      const zIndex = String(resolution.zIndex);\n      if (host.style.zIndex !== zIndex) host.style.zIndex = zIndex;\n      if (resolution.fallback) {\n        if (host.dataset.movcuesLayerFallback !== resolution.fallback) host.dataset.movcuesLayerFallback = resolution.fallback;\n      } else if (host.dataset.movcuesLayerFallback) delete host.dataset.movcuesLayerFallback;\n      const dynamicLayer = options.layer?.mode === \"auto\" || options.layer?.mode === \"relative\";\n      const watched = dynamicLayer ? (options.layer?.mode === \"relative\" ? this.findTarget(options.layer.target) : options.targetElement) : null;\n      if (watched && typeof MutationObserver !== \"undefined\") {\n        const observer = new MutationObserver(() => scheduleRefresh());\n        for (let element: Element | null = watched; element; element = element.parentElement) {\n          observer.observe(element, { attributes: true, attributeFilter: [\"class\", \"style\", \"hidden\"] });\n          if (element.parentElement) observer.observe(element.parentElement, { childList: true });\n        }\n        observers.push(observer);\n      }\n      return resolution;\n    };\n    const scheduleRefresh = () => {\n      if (!active || frameId !== null) return;\n      frameId = requestAnimationFrame(() => { frameId = null; refresh(); });\n    };\n    refresh();\n    return {\n      refresh,\n      destroy: () => {\n        active = false;\n        disconnect();\n        if (frameId !== null) cancelAnimationFrame(frameId);\n        frameId = null;\n      },\n    };\n  }\n}\n\nfunction findUniqueTarget(target: ExperienceTarget): Element | null {\n  for (const selector of [target.primarySelector, ...target.fallbackSelectors]) {\n    try { const matches = document.querySelectorAll(selector); if (matches.length === 1) return matches[0]; } catch { /* Invalid saved selectors fall back safely. */ }\n  }\n  return null;\n}\n\nfunction bounded(value: number): number { return Math.max(-2_147_483_648, Math.min(2_147_483_647, value)); }\n","import type { DeliveredChecklist } from \"../types\";\nimport { sanitizeBuilderHtml, safeBuilderCss } from \"./BuilderContent\";\nimport { ALWAYS_ON_TOP_Z_INDEX } from \"./layering/LayerManager\";\n\nexport interface ChecklistRendererCallbacks {\n  onOpen(): void;\n  onCollapse(): void;\n  onDismiss(): void;\n  onAcknowledge(): void;\n  onItemClick(itemId: string): void;\n}\n\nexport class ChecklistRenderer {\n  private host: HTMLElement | null = null;\n\n  render(checklist: DeliveredChecklist, callbacks: ChecklistRendererCallbacks, forceLauncher = false): boolean {\n    this.destroy();\n    const nodes = sanitizeBuilderHtml(checklist.definition.builder.html); const css = safeBuilderCss(checklist.definition.builder.css);\n    if (!nodes || css === null) return false;\n    this.host = document.createElement(\"div\"); this.host.dataset.movcuesChecklist = checklist.id;\n    const side = checklist.definition.behavior.position === \"bottom-left\" ? \"left:16px\" : \"right:16px\";\n    this.host.style.cssText = `position:fixed;bottom:16px;${side};z-index:${ALWAYS_ON_TOP_Z_INDEX};pointer-events:auto`;\n    const root = this.host.attachShadow({ mode: \"open\" }); const style = document.createElement(\"style\");\n    style.textContent = `:host{all:initial}.surface{position:relative;pointer-events:auto}.surface>.movcues-widget{position:relative!important;inset:auto!important}${css}`; root.appendChild(style);\n    const surface = document.createElement(\"div\"); surface.className = \"surface\"; surface.append(...nodes); root.appendChild(surface);\n    const authoredRoot = surface.querySelector<HTMLElement>('[data-movcues-checklist-role=\"root\"]');\n    if (!authoredRoot || surface.querySelectorAll('[data-movcues-checklist-role=\"root\"]').length !== 1) { this.destroy(); return false; }\n    const design=checklist.definition.design,theme=design?.theme.siteTheme;if(design){authoredRoot.style.setProperty('--movcues-bg',design.theme.background);authoredRoot.style.setProperty('--movcues-fg',design.theme.foreground);authoredRoot.style.setProperty('--movcues-primary',design.theme.primary);if(design.theme.spacing!==undefined)authoredRoot.style.setProperty('--movcues-theme-spacing',`${design.theme.spacing}px`);}if(theme){const shadow=theme.shadows.md;authoredRoot.style.setProperty('--movcues-surface',theme.colors.surface);authoredRoot.style.setProperty('--movcues-muted',theme.colors.mutedText);authoredRoot.style.setProperty('--movcues-border',theme.colors.border);authoredRoot.style.setProperty('--movcues-primary-fg',theme.colors.primaryForeground);authoredRoot.style.setProperty('--movcues-font-body',theme.typography.bodyFontFamily);authoredRoot.style.setProperty('--movcues-font-heading',theme.typography.headingFontFamily);authoredRoot.style.setProperty('--movcues-theme-radius',`${theme.radii.lg}px`);authoredRoot.style.setProperty('--movcues-button-radius',`${theme.radii.md}px`);authoredRoot.style.setProperty('--movcues-theme-shadow',`${shadow.x}px ${shadow.y}px ${shadow.blur}px ${shadow.spread}px ${shadow.color}`);}\n    const requiredRoles = [\"title\", \"description\", \"progress\", \"items\", \"launcher-label\", \"remaining-count\", \"completion-title\", \"completion-description\", \"completion-acknowledge\"];\n    const requiredViews = [\"expanded\", \"launcher\", \"completion\"];\n    if (requiredRoles.some(role => authoredRoot.querySelectorAll(`[data-movcues-checklist-role=\"${role}\"]`).length !== 1) || requiredViews.some(view => authoredRoot.querySelectorAll(`[data-movcues-checklist-view=\"${view}\"]`).length !== 1)) { this.destroy(); return false; }\n    const itemElements = new Map<string, HTMLElement>();\n    for (const element of Array.from(authoredRoot.querySelectorAll<HTMLElement>(\"[data-movcues-checklist-item-id]\"))) { const id = element.dataset.movcuesChecklistItemId; if (!id || itemElements.has(id) || element.querySelectorAll('[data-movcues-checklist-item-role=\"state\"]').length !== 1 || element.querySelectorAll('[data-movcues-checklist-item-role=\"title\"]').length !== 1 || element.querySelectorAll('[data-movcues-checklist-item-role=\"description\"]').length !== 1) { this.destroy(); return false; } itemElements.set(id, element); }\n    if (checklist.definition.items.some(item => !itemElements.has(item.id)) || itemElements.size !== checklist.definition.items.length) { this.destroy(); return false; }\n    const cellDocument = authoredRoot.dataset.movcuesDocumentVersion === \"4\";\n    setText(authoredRoot, \"title\", checklist.definition.title); setText(authoredRoot, \"description\", checklist.definition.description ?? \"\");\n    if (!cellDocument) setText(authoredRoot, \"launcher-label\", checklist.definition.title); setText(authoredRoot, \"completion-title\", checklist.definition.completionMessage.title); setText(authoredRoot, \"completion-description\", checklist.definition.completionMessage.description ?? \"\"); setText(authoredRoot, \"completion-acknowledge\", checklist.definition.completionMessage.acknowledgeLabel);\n    authoredRoot.querySelectorAll<HTMLElement>('[data-movcues-checklist-role=\"dismiss\"]').forEach(element => { element.hidden = !checklist.definition.behavior.dismissible; });\n    const completed = new Set(checklist.progress.completedItemIds); const remaining = checklist.definition.items.length - completed.size;\n    authoredRoot.style.setProperty(\"--movcues-checklist-progress\", `${checklist.definition.items.length ? completed.size / checklist.definition.items.length * 100 : 0}%`);\n    setText(authoredRoot, \"progress\", `${completed.size} of ${checklist.definition.items.length} complete`); setText(authoredRoot, \"remaining-count\", checklist.definition.behavior.showRemainingCount ? String(remaining) : \"\");\n    const container = authoredRoot.querySelector<HTMLElement>('[data-movcues-checklist-role=\"items\"]'); if (!container) { this.destroy(); return false; }\n    checklist.definition.items.forEach((item, index) => { const element = itemElements.get(item.id)!; if (!cellDocument) container.appendChild(element); const state = checklist.progress.items[index]?.state ?? \"locked\"; element.dataset.state = state; element.setAttribute(\"aria-disabled\", state === \"locked\" ? \"true\" : \"false\"); setText(element, \"title\", item.title, true); setText(element, \"description\", item.description ?? \"\", true); });\n    const view = checklist.progress.complete ? \"completion\" : forceLauncher || checklist.progress.collapsed ? \"launcher\" : \"expanded\";\n    authoredRoot.querySelectorAll<HTMLElement>(\"[data-movcues-checklist-view]\").forEach(element => element.classList.toggle(\"is-active\", element.dataset.movcuesChecklistView === view));\n    authoredRoot.addEventListener(\"click\", event => { const target = event.target instanceof Element ? event.target : null; if (!target) return; const item = target.closest<HTMLElement>(\"[data-movcues-checklist-item-id]\"); if (item && item.dataset.state !== \"locked\") { callbacks.onItemClick(item.dataset.movcuesChecklistItemId!); return; } const role = target.closest<HTMLElement>(\"[data-movcues-checklist-role]\")?.dataset.movcuesChecklistRole; if (role === \"launcher-label\" || target.closest('[data-movcues-checklist-view=