h min=\"120\" max=\"720\"></label><small>Width for the selected visual state. It automatically fits small screens.</small><label>Checklist title<input data-checklist-title maxlength=\"160\"></label><label>Description<textarea data-checklist-description rows=\"3\" maxlength=\"2000\"></textarea></label><label>Position<select data-checklist-position><option value=\"bottom-right\">Bottom right</option><option value=\"bottom-left\">Bottom left</option></select></label><label>Task order<select data-checklist-order><option value=\"any\">Any order</option><option value=\"sequential\">In order</option></select></label><small>In order unlocks each task after the previous task is completed.</small><label>Start as<select data-checklist-initial><option value=\"expanded\">Expanded</option><option value=\"collapsed\">Collapsed</option></select></label><label class=\"check\"><input type=\"checkbox\" data-checklist-dismissible> Allow dismissal</label><label class=\"check\"><input type=\"checkbox\" data-checklist-remaining> Show remaining count</label><label>Completion title<input data-checklist-completion-title maxlength=\"160\"></label><label>Completion message<textarea data-checklist-completion-description rows=\"3\" maxlength=\"2000\"></textarea></label><label>Done button<input data-checklist-ack maxlength=\"80\"></label><button type=\"button\" class=\"secondary-button\" data-checklist-add>Add task</button>';\n    this.task.dataset.block='checklist_task,checklist_text,checklist_control,checklist_progress';this.task.innerHTML='<div data-checklist-task-fields><label>Task title<input data-checklist-task-title maxlength=\"200\"></label><label>Description<textarea data-checklist-task-description rows=\"3\" maxlength=\"1000\"></textarea></label><label>Action<select data-checklist-action><option value=\"none\">No action</option><option value=\"launch_guide\">Launch Guide</option><option value=\"navigate\">Go to a page</option><option value=\"open_url\">Open external URL</option></select></label><label data-checklist-guide-field>Guide<select data-checklist-action-guide></select></label><label data-checklist-url-field>Page URL<input data-checklist-url type=\"url\" maxlength=\"2000\" placeholder=\"/getting-started\"></label><label>Complete when<select data-checklist-condition><option value=\"item_clicked\">Task clicked</option><option value=\"segment\">Matches saved Segment</option><option value=\"guide_completed\">Guide completed</option></select></label><label data-checklist-segment-field>Segment<select data-checklist-segment></select></label><label data-checklist-completion-guide-field>Guide<select data-checklist-completion-guide></select></label><small data-checklist-action-note></small><label>Sample status<select data-checklist-sample><option value=\"available\">Available</option><option value=\"completed\">Completed</option><option value=\"locked\">Locked</option></select></label><label>Status icon<select data-checklist-indicator><option value=\"check\">Check</option><option value=\"star\">Star</option><option value=\"rocket\">Rocket</option><option value=\"heart\">Heart</option><option value=\"info\">Info</option><option value=\"warning\">Warning</option><option value=\"sparkles\">Sparkles</option><option value=\"arrow\">Arrow</option></select></label><div class=\"history-row\"><button type=\"button\" class=\"secondary-button compact\" data-checklist-task-move=\"-1\">Move earlier</button><button type=\"button\" class=\"secondary-button compact\" data-checklist-task-move=\"1\">Move later</button></div></div><label data-checklist-launcher-field>Launcher label<input data-checklist-launcher-label maxlength=\"200\"></label><label>Font size<input type=\"number\" data-checklist-font min=\"10\" max=\"48\"></label><label>Color<input type=\"color\" data-checklist-color></label>';\n    this.tools.dataset.checklistTools='';this.tools.innerHTML='<select aria-label=\"Checklist visual state\" data-checklist-view><option value=\"expanded\">Expanded</option><o