ondition]',task.completion.type);this.value('[data-checklist-segment]',task.completion.type==='segment'?task.completion.segmentId:'');this.value('[data-checklist-completion-guide]',task.completion.type==='guide_completed'?task.completion.experienceId:'');this.value('[data-checklist-sample]',this.sample.get(task.id)??'available');this.hide('[data-checklist-guide-field]',task.action.type!=='launch_guide');this.hide('[data-checklist-url-field]',!['navigate','open_url'].includes(task.action.type));this.hide('[data-checklist-segment-field]',task.completion.type!=='segment');this.hide('[data-checklist-completion-guide-field]',task.completion.type!=='guide_completed');const note=this.task.querySelector<HTMLElement>('[data-checklist-action-note]')!;note.textContent=task.action.type==='launch_guide'&&this.references.guides.find(g=>g.id===('experienceId'in task.action?task.action.experienceId:''))?.status!=='published'?'Publish the selected Guide before publishing this Checklist.':'Completion is verified by the server. Sample status changes only this editor.';}\n    this.hide('[data-checklist-launcher-field]',block?.type!=='checklist_text'||block.role!=='launcher-label');\n    if(block?.type.startsWith('checklist_')){const visual=block as {fontSize:number;color?:string};this.value('[data-checklist-font]',String(visual.fontSize));this.value('[data-checklist-color]',visual.color??'#111827');if(block.type==='checklist_task')this.value('[data-checklist-indicator]',block.indicator);if(block.type==='checklist_text'&&block.role==='launcher-label')this.value('[data-checklist-launcher-label]',block.text??d.title);}\n  }\n  render(id:string,versionId:string,preview:boolean):boolean {\n    this.preview=preview;const completed=this.view==='completion'?this.definition.items.map(item=>item.id):this.definition.items.filter(item=>this.completed.has(item.id)).map(item=>item.id);const ids=new Set(completed);let unlocked=true;\n    const progress:ChecklistProgress={stateId:'editor-only',collapsed:this.view==='launcher',dismissed:false,complete:this.view==='completion',completionAcknowledged:false,completedItemIds:completed,items:this.definition.items.map(item=>{const state=ids.has(item.id)?'completed':this.definition.behavior.order==='sequential'&&!unlocked?'locked':'available';if(!ids.has(item.id))unlocked=false;return{id:item.id,state};})};\n    const mounted=this.renderer.render({id,versionId,kind:'checklist',priority:0,definition:this.definition,progress},{onOpen:()=>this.transition('expanded'),onCollapse:()=>this.transition('launcher'),onDismiss:()=>this.renderer.destroy(),onAcknowledge:()=>this.renderer.destroy(),onItemClick:itemId=>{this.completed.add(itemId);if(this.definition.items.every(item=>this.completed.has(item.id)))this.view='completion';this.options.render();}});\n    const host=this.host(id);if(host&&document.body&&!document.body.contains(host))document.body.append(host);\n    const surface=host?.shadowRoot?.querySelector<HTMLElement>('.surface'),style=host?.shadowRoot?.querySelector('style');if(surface)surface.dataset.movcuesBuilderSurface='';if(style)(style as HTMLElement).dataset.movcuesBuilderStyle='';\n    this.sync();return mounted;\n  }\n  applyDesign(id:string):void {\n    const host=this.host(id),root=host?.shadowRoot;if(!host||!root)return;host.style.left=this.definition.behavior.position==='bottom-left'?'16px':'auto';host.style.right=this.definition.behavior.position==='bottom-right'?'16px':'auto';\n    root.querySelectorAll<HTMLElement>('[data-movcues-checklist-view]').forEach(view=>view.classList.toggle('is-active',view.dataset.movcuesChecklistView===this.view));\n    let available=true;root.querySelectorAll<HTMLElement>('[data-movcues-checklist-item-id]').forEach(node=>{const explicit=this.sample.get(node.dataset.movcuesChecklistItemId!);node.dataset.state=explicit??(this.definition.behavior.order==='sequential'&&!available?'locked':'available');if(node.dataset.state!=='completed')available=false;});\n    root.querySelector<HTMLElement>('[data-movcues-checklist-role=progress]')!.textContent=`${this.definition.items.filter(item=>this.sample.get(item.id)==='completed').length} of ${this.definition.items.length} complete`;\n    root.querySelectorAll<HTMLElement>('[data-movcues-checklist-role=dismiss]').forEach(node=>node.hidden=!this.definition.behavior.dismissible);\n    const count=root.querySelector<HTMLElement>('[data-movcues-checklist-role=remaining-count]');if(count)count.textContent=this.definition.behavior.showRemainingCount?String(this.definition.items.length):'';\n    this.options.composer()?.setChecklistView(this.view);\n  }\n  private host(id:string):HTMLElement|null{return Array.from(document.querySelectorAll<HTMLElement>('[data-movcues-checklist]')).find(host=>host.dataset.movcuesChecklist===id)??null;}\n  private closeMobileInspector():void{if(innerWidth>480)return;this.root.querySelector('aside')?.classList.add('minimized');this.root.querySelector('[data-minimize]')?.setAttribute('aria-expanded','false');}\n  private transition(view:ChecklistView):void{this.view=view;this.options.render();}\n  getView():ChecklistView{return this.view;}\n  setDefinition(value:RuntimeChecklistDefinition):void{this.definition=value;}\n  private onChange=(event:Event):void=>{\n    const input=event.target as HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement;if(!input.matches('[data-checklist-view]')&&!this.options.canEdit())return;\n    if(input.matches('[data-checklist-view]')){if(this.options.flush()){this.view=input.value as ChecklistView;this.closeMobileInspector();this.options.render();}return;}\n    const c=this.options.composer();if(!c)return;const item=c.getSelectedTask();\n    if(input.matches('[data-checklist-sample]')&&item){this.sample.set(item.id,input.value as 'available'|'locked'|'completed');this.options.composer()?.refreshChecklist();return;}\n    if(input.matches('[data-checklist-view-width]')){c.updateChecklistViewWidth(Number(input.value));return;}\n    if(input.matches('[data-checklist-font]')){c.updateBlock({fontSize:Number(input.value)});return;}if(input.matches('[data-checklist-color]')){c.updateBlock({color:input.value});return;}if(input.matches('[data-checklist-indicator]')){c.updateBlock({indicator:input.value as 'check'});return;}if(input.matches('[data-checklist-launcher-label]')){c.updateBlock({text:input.value});return;}\n    if(this.step.contains(input)){c.updateChecklist(next=>{if(input.matches('[data-checklist-title]'))next.title=input.value;if(input.matches('[data-checklist-description]'))next.description=input.value;if(input.matches('[data-checklist-completion-title]'))next.completionMessage.title=input.value;if(input.matches('[data-checklist-completion-description]'))next.completionMessage.description=input.value;if(input.matches('[data-checklist-ack]'))next.completionMessage.acknowledgeLabel=input.value;if(input.matches('[data-checklist-position]'))next.behavior.position=input.value as 'bottom-right';if(input.matches('[data-checklist-order]'))next.behavior.order=input.value as 'any';if(input.matches('[data-checklist-initial]'))next.behavior.initialState=input.value as 'expanded';if(input.matches('[data-checklist-dismissible]'))next.behavior.dismissible=(input as HTMLInputElement).checked;if(input.matches('[data-checklist-remaining]'))next.behavior.showRemainingCount=(input as HTMLInputElement).checked;});return;}\n    if(!item||!this.task.contains(input))return;\n    const next=structuredClone(item);if(input.matches('[data-checklist-task-title]'))next.title=input.value;if(input.matches('[data-checklist-task-description]'))next.description=input.value;\n    if(input.matches('[data-checklist-action]'))next.action=input.value==='none'?{type:'none'}:input.value==='launch_guide'?{type:'launch_guide',experienceId:this.references.guides[0]?.id??''}:{type:input.value as 'navigate'|'open_url',url:input.value==='navigate'?'/':location.origin};\n    if(input.matches('[data-checklist-action-guide]'))next.action={type:'launch_guide',experienceId:input.value};if(input.matches('[data-checklist-url]')&&'url'in next.action)next.action.url=input.value;\n    if(input.matches('[data-checklist-condition]'))next.completion=input.value==='item_clicked'?{type:'item_clicked'}:input.value==='segment'?{type:'segment',segmentId:this.references.segments[0]?.id??''}:{type:'guide_completed',experienceId:this.references.guides[0]?.id??''};\n    if(input.matches('[data-checklist-segment]'))next.completion={type:'segment',segmentId:input.value};if(input.matches('[data-checklist-completion-guide]'))next.completion={type:'guide_completed',experienceId:input.value};\n    if((next.action.type==='launch_guide'&&!next.action.experienceId)||(next.completion.type==='segment'&&!next.completion.segmentId)||(next.completion.type==='guide_completed'&&!next.completion.experienceId)){this.options.error(['Select a Guide or Segment from this site.']);return;}\n    c.updateChecklist(value=>{value.items=value.items.map(task=>task.id===next.id?next:task);});this.sync();\n  };\n  private onClick=(event:Event):void=>{const button=(event.target as Element)?.closest?.('button');if(!button)return;if(button.matches('[data-checklist-reset]')){this.completed.clear();this.sample.clear();this.view='expanded';this.options.render();return;}if(!this.options.canEdit())return;if(button.matches('[data-checklist-add]')){this.view='expanded';const c=this.options.composer();if(c?.insertTask())this.sync();}if(button.matches('[data-checklist-task-move]'))this.options.composer()?.move(Number((button as HTMLElement).dataset.checklistTaskMove) as -1|1);};\n  private value(selector:string,value:string):void{const input=this.root.querySelector<HTMLInputElement>(selector);if(input&&this.root.activeElement!==input)input.value=value;}\n  private check(selector:string,value:boolean):void{const input=this.root.querySelector<HTMLInputElement>(selector);if(input)input.checked=value;}\n  private hide(selector:string,value:boolean):void{const element=this.task.querySelector<HTMLElement>(selector);if(element)element.hidden=value;}\n  destroyView():void{this.renderer.destroy();}\n  destroy():void{this.renderer.destroy();this.root.removeEventListener('change',this.onChange);this.root.removeEventListener('click',this.onClick);this.step.remove();this.task.remove();this.tools.remove();this.style.remove();}\n}\n","export type ExperienceKind = \"guide\" | \"widget\" | \"checklist\";\nexport type WidgetType = \"anchored_card\" | \"toast\" | \"cursor_follow\" | \"modal\" | \"slideout\" | \"hotspot\" | \"banner\" | \"survey\";\nexport type BuilderMode = \"grapesjs\" | \"onsite\";\nexport interface ExperienceAction { id?: string; label: string; type: \"dismiss\" | \"next_step\" | \"previous_step\" | \"open_url\" | \"track_event\"; url?: string; eventName?: string }\nexport interface ExperienceContent { heading: string; body: string; primaryAction?: ExperienceAction; secondaryAction?: { label: string; type: \"dismiss\" } }\nexport interface ExperienceTarget { primarySelector: string; fallbackSelectors: string[]; label?: string; role?: string; tagName?: string; reliability: \"reliable\" | \"moderate\" | \"fragile\"; targetContext?: { pagePath: string } }\nexport type LegacyExperienceWidth = \"sm\" | \"md\" | \"lg\";\nexport interface ExperienceSize { width: { mode: \"auto\" | \"fixed\" | \"full\"; value?: number }; height: { mode: \"auto\" | \"fixed\" | \"viewport\"; value?: number } }\nimport type { SiteThemeTokens, VisualThemeState } from \"../themes/types\";\nexport interface ExperienceDesign { width: LegacyExperienceWidth; size?: ExperienceSize; theme: { background: string; foreground: string; primary: string; borderRadius: \"sm\" | \"md\" | \"lg\"; spacing?: number; siteTheme?: SiteThemeTokens } }\nexport interface WidgetBuilderState { version: 1; projectData: Record<string, unknown>; html: string; css: string }\nexport type ExperienceLayer = { mode: \"auto\" } | { mode: \"relative\"; relation: \"above\" | \"below\"; target: ExperienceTarget } | { mode: \"always_on_top\" } | { mode: \"custom\"; zIndex: number };\nexport interface ExperienceBehavior { dismissible: boolean; layer?: ExperienceLayer; zIndex?: number; placement?: \"auto\" | \"top\" | \"right\" | \"bottom\" | \"left\"; alignment?: \"start\" | \"center\" | \"end\"; offset?: number; pointer?: { enabled?: boolean; size?: number }; toastPosition?: \"top-left\" | \"top-right\" | \"bottom-left\" | \"bottom-right\"; autoDismissMs?: number | null; cursorOffset?: { x: number; y: number }; modalLayout?: \"center\" | \"fullscreen\"; backdrop?: boolean; backdropOpacity?: number; closeOnBackdrop?: boolean; slideoutPosition?: \"top-left\" | \"top-right\" | \"bottom-left\" | \"bottom-right\" | \"center-left\" | \"center-right\"; bannerPosition?: \"top\" | \"bottom\"; hotspotStyle?: \"pulse\" | \"dot\" | \"question\"; hotspotColor?: string }\nexport interface PageRule { id: string; kind: \"include\" | \"exclude\"; operator: \"equals\" | \"starts_with\" | \"ends_with\" | \"contains\" | \"matches_pattern\"; value: string }\nexport interface ExperienceTargeting { pageRules: PageRule[]; audience: { type: \"all\" } | { type: \"segment\"; segmentId: string } | { type: \"segment_rules\"; logic: \"all\" | \"any\"; conditions: Array<{ id: string; segmentId: string; operator: \"matches\" | \"not_matches\" }> }; trigger: { type: \"page_load\" } | { type: \"custom_event\"; eventName: string } | { type: \"manual\" }; frequency: { mode: \"once\" | \"once_per_session\" | \"every_time\"; cooldownHours?: number; maxImpressions?: number }; priority: number; interruptPolicy?: \"queue\" | \"interrupt\"; schedule?: { startsAt?: string; endsAt?: string }; allowedOrigins?: string[] }\nexport type GuideAdvance = { type: \"button\" } | { type: \"element_click\"; target?: ExperienceTarget } | { type: \"element_hover\"; durationMs?: number; target?: ExperienceTarget } | { type: \"custom_event\"; eventName: string } | { type: \"route\"; pageRules: PageRule[] };\nexport interface GuidePresentation { delayMs?: number; missingTarget?: { action: \"wait\" | \"skip\" | \"dismiss\"; timeoutMs: number } }\nexport type GuideStepPattern = \"anchored_card\" | \"modal\";\nexport interface GuideStep { id: string; label?: string; pattern?: GuideStepPattern; content: ExperienceContent; builder?: WidgetBuilderState; size?: ExperienceSize; advance?: GuideAdvance; presentation?: GuidePresentation; target?: ExperienceTarget; behavior: Pick<ExperienceBehavior, \"placement\" | \"alignment\" | \"offset\" | \"pointer\" | \"dismissible\" | \"layer\" | \"backdrop\" | \"backdropOpacity\" | \"closeOnBackdrop\"> }\nexport function getGuideStepPattern(step: Pick<GuideStep, \"pattern\">): GuideStepPattern { return step.pattern ?? \"anchored_card\"; }\nexport function guideStepRequiresTarget(step: Pick<GuideStep, \"pattern\">): boolean { return getGuideStepPattern(step) === \"anchored_card\"; }\nexport function guideStepSupportsTargetAdvance(step: Pick<GuideStep, \"pattern\">): boolean { return guideStepRequiresTarget(step); }\nexport interface SurveyOption { id: string; label: string }\nexport type SurveyQuestion =\n  | { id: string; type: \"single_choice\"; label: string; required?: boolean; options: SurveyOption[] }\n  | { id: string; type: \"multiple_choice\"; label: string; required?: boolean; options: SurveyOption[] }\n  | { id: string; type: \"short_text\"; label: string; required?: boolean; placeholder?: string; maxLength?: number }\n  | { id: string; type: \"long_text\"; label: string; required?: boolean; placeholder?: string; maxLength?: number }\n  | { id: string; type: \"rating\"; label: string; required?: boolean; min: number; max: number }\n  | { id: string; type: \"nps\"; label: string; required?: boolean };\nexport interface SurveyBranchRule { questionId: string; operator: \"equals\" | \"not_equals\" | \"includes\" | \"gte\" | \"lte\" | \"answered\"; value?: string | number; nextStepId: string }\nexport interface SurveyBranching { rules: SurveyBranchRule[]; defaultNextStepId?: string }\nexport interface SurveyStep { branching?: SurveyBranching; id: string; content: { heading: string; body: string }; questions: SurveyQuestion[]; builder?: WidgetBuilderState; size?: ExperienceSize; behavior?: { layer?: ExperienceLayer } }\nexport interface SurveyConfig { steps: SurveyStep[]; showProgress: boolean; allowBack: boolean; submitLabel: string }\nexport type SurveyAnswers = Record<string, string | string[] | number>;\nexport interface RuntimeWidgetDefinition { content: ExperienceContent; design: ExperienceDesign; behavior: ExperienceBehavior; builder?: WidgetBuilderState; target?: ExperienceTarget; survey?: SurveyConfig; visualTheme?: VisualThemeState; template?: { id: string; version: 1 } }\nexport interface RuntimeGuideDefinition { steps: GuideStep[]; design: ExperienceDesign; behavior?: { layer?: ExperienceLayer }; visualTheme?: VisualThemeState; template?: { id: string; version: 1 } }\nexport type ChecklistItemAction = { type: \"launch_guide\"; experienceId: string } | { type: \"navigate\"; url: string } | { type: \"open_url\"; url: string } | { type: \"none\" };\nexport type ChecklistItemCompletion = { type: \"segment\"; segmentId: string } | { type: \"guide_completed\"; experienceId: string } | { type: \"item_clicked\" };\nexport interface ChecklistItem { id: string; title: string; description?: string; action: ChecklistItemAction; completion: ChecklistItemCompletion }\nexport interface RuntimeChecklistDefinition { title: string; description?: string; items: ChecklistItem[]; behavior: { position: \"bottom-left\" | \"bottom-right\"; order: \"any\" | \"sequential\"; dismissible: boolean; initialState: \"expanded\" | \"collapsed\"; showRemainingCount: boolean }; completionMessage: { title: string; description?: string; acknowledgeLabel: string }; builder: WidgetBuilderState; design?: ExperienceDesign; visualTheme?: VisualThemeState; template?: { id: string; version: 1 } }\nexport interface ChecklistProgress { stateId: string; collapsed: boolean; dismissed: boolean; complete: boolean; completionAcknowledged: boolean; completedItemIds: string[]; items: Array<{ id: string; state: \"completed\" | \"available\" | \"locked\" }> }\nexport type RuntimeDefinition = RuntimeWidgetDefinition | RuntimeGuideDefinition;\nexport type ExperienceLaunchContext = { source: \"api\" } | { source: \"checklist\"; sourceExperienceId: string; sourceItemId: string };\nexport interface DeliveredExperience { id: string; versionId: string; kind: ExperienceKind; widgetType: WidgetType | null; priority: number; interruptPolicy?: \"queue\" | \"interrupt\"; impressionId?: string; definition: RuntimeDefinition; launchContext?: ExperienceLaunchContext }\nexport interface DeliveredChecklist { id: string; versionId: string; kind: \"checklist\"; priority: number; definition: RuntimeChecklistDefinition; progress: ChecklistProgress }\nexport type EditorDefinition = RuntimeDefinition & { targeting: ExperienceTargeting };\nexport type EditorChecklistDefinition = RuntimeChecklistDefinition & { targeting: Pick<ExperienceTargeting,\"pageRules\"|\"audience\"|\"priority\"|\"schedule\"|\"allowedOrigins\"> };\nexport interface EditorDraft { references?: {guides:Array<{id:string;name:string;status:string}>;segments:Array<{id:string;name:string}>;stylePresets?:Array<{id:string;name:string;tokens:SiteThemeTokens}>;siteTheme?:SiteThemeTokens|null}; experience: { id: string; name: string; kind: ExperienceKind; widgetType: WidgetType | null; builderMode: BuilderMode }; version: { id: string; versionNumber: number; revision: number; definition: EditorDefinition | EditorChecklistDefinition } }\nexport function isGuideDefinition(value: RuntimeDefinition): value is RuntimeGuideDefinition { return \"steps\" in value; }\nexport function isChecklistDefinition(value: RuntimeDefinition | RuntimeChecklistDefinition): value is RuntimeChecklistDefinition { return \"items\" in value; }\n","import type { RuntimeChecklistDefinition } from '../types';\nexport type ChecklistView = 'expanded' | 'launcher' | 'completion';\nexport type ChecklistTextRole = 'title' | 'description' | 'launcher-label' | 'remaining-count' | 'completion-title' | 'completion-description';\nexport type ChecklistControlRole = 'collapse' | 'dismiss' | 'completion-acknowledge';\nexport type OnsiteChecklistContext = Pick<RuntimeChecklistDefinition, 'title' | 'description' | 'items' | 'behavior' | 'completionMessage'>;\nexport const checklistCopy = (value: OnsiteChecklistContext) => ({title:value.title,description:value.description??'', 'launcher-label':value.title,'remaining-count':'', 'completion-title':value.completionMessage.title,'completion-description':value.completionMessage.description??''});\nexport const escapeChecklist = (value:string) => value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\nexport const CHECKLIST_CELL_CSS = '.movcues-widget--checklist{width:360px;max-width:calc(100vw - 32px);max-height:calc(100dvh - 32px);overflow:auto;background:var(--movcues-bg,#fff);color:var(--movcues-fg,#111827);border:1px solid var(--movcues-border,#e2e8f0);border-radius:var(--movcues-theme-radius,12px);box-shadow:var(--movcues-theme-shadow,0 12px 40px #0f172a24);font:14px/1.4 var(--movcues-font-body,ui-sans-serif,system-ui)}.movcues-widget [data-movcues-checklist-view]:not(.is-active){display:none!important}.movcues-widget--checklist:has([data-movcues-checklist-view=\"launcher\"].is-active){width:220px}.movcues-widget .movcues-checklist__item{display:flex;align-items:flex-start;gap:10px;width:100%;padding:10px;border:1px solid var(--movcues-border,#e2e8f0);border-radius:var(--movcues-button-radius,8px);background:var(--movcues-surface,#f8fafc);color:inherit;text-align:left;cursor:pointer;font:inherit}.movcues-widget .movcues-checklist__copy{display:grid;gap:3px}.movcues-widget [data-movcues-checklist-item-role=\"title\"]{font-weight:600}.movcues-widget [data-movcues-checklist-item-role=\"description\"]{font-size:.9em;color:var(--movcues-muted,#64748b)}.movcues-widget [data-movcues-checklist-item-role=\"state\"]{display:grid;place-items:center;flex:none;width:22px;height:22px;border:1px solid #94a3b8;border-radius:50%;color:transparent}.movcues-widget [data-state=\"completed\"] [data-movcues-checklist-item-role=\"state\"]{background:#16a34a;border-color:#16a34a;color:#fff}.movcues-widget [data-state=\"locked\"]{opacity:.5;cursor:not-allowed}.movcues-widget .movcues-checklist-progress-track{height:4px;border-radius:4px;background:#e2e8f0;overflow:hidden}.movcues-widget .movcues-checklist-progress-fill{display:block;height:100%;width:var(--movcues-checklist-progress,0%);background:var(--movcues-primary,#2563eb)}.movcues-widget .movcues-checklist-control{border:1px solid var(--movcues-border,#cbd5e1);border-radius:var(--movcues-button-radius,6px);padding:6px 10px;background:var(--movcues-surface,#fff);color:inherit;cursor:pointer;font:inherit}.movcues-widget [data-movcues-checklist-role=\"completion-acknowledge\"]{background:var(--movcues-primary,#2563eb);border-color:var(--movcues-primary,#2563eb);color:var(--movcues-primary-fg,#fff)}.movcues-widget [data-movcues-checklist-view=\"launcher\"]{cursor:pointer}.movcues-widget [hidden]{display:none!important}';\n","import type { SurveyQuestion } from '../types';\n\nexport interface OnsiteSurveyContext { questions: SurveyQuestion[]; submitLabel?: string }\nexport const QUESTION_TYPES = ['single_choice', 'multiple_choice', 'short_text', 'long_text', 'rating', 'nps'] as const;\n\n/** Small pure projection shared by the two compilers; SurveyRenderer owns behavior. */\nexport function surveyQuestionMarkup(question: SurveyQuestion, blockId: string): string {\n  const label = escape(question.label);\n  let controls: string;\n  if (question.type === 'short_text' || question.type === 'long_text') {\n    const attrs = `class=\"movcues-survey-input\" data-movcues-question-input aria-label=\"${label}\" placeholder=\"${escape(question.placeholder ?? '')}\" maxlength=\"${question.maxLength ?? 10000}\"${question.required ? ' aria-required=\"true\"' : ''}`;\n    controls = question.type === 'short_text' ? `<input type=\"text\" ${attrs}>` : `<textarea ${attrs}></textarea>`;\n  } else {\n    const options = question.type === 'rating' || question.type === 'nps'\n      ? Array.from({ length: question.type === 'nps' ? 11 : question.max - question.min + 1 }, (_, index) => { const value = String(index + (question.type === 'nps' ? 0 : question.min)); return { id: value, label: value }; })\n      : question.options;\n    controls = `<div class=\"movcues-survey-options\">${options.map(option => `<button type=\"button\" class=\"movcues-survey-option\" data-movcues-option-id=\"${escape(option.id)}\" aria-pressed=\"false\">${escape(option.label)}</button>`).join('')}</div>`;\n  }\n  return `<div class=\"movcues-block movcues-survey-question\" data-movcues-block-id=\"${escape(blockId)}\" data-movcues-question-id=\"${escape(question.id)}\" data-movcues-question-type=\"${question.type}\"><p class=\"movcues-survey-question__label\">${label}${question.required ? ' *' : ''}</p>${controls}</div>`;\n}\n\nexport function surveyControlsMarkup(blockId: string, label: string): string {\n  return `<div class=\"movcues-block movcues-survey-footer\" data-movcues-block-id=\"${escape(blockId)}\" data-movcues-survey-controls=\"onsite\"><div data-movcues-survey-progress><span>Progress</span><span data-movcues-survey-progress-bar></span></div><p class=\"movcues-survey-validation\" role=\"alert\"></p><div class=\"movcues-survey-actions\"><button type=\"button\" data-movcues-survey-action=\"back\">Back</button><button type=\"button\" data-movcues-survey-action=\"next\">Next</button><button type=\"button\" data-movcues-survey-action=\"submit\">${escape(label)}</button></div></div>`;\n}\n\nexport const SURVEY_CELL_CSS = '.movcues-widget .movcues-survey-question__label{margin:0 0 8px;font-weight:600}.movcues-widget .movcues-survey-options{display:flex;flex-wrap:wrap;gap:6px}.movcues-widget .movcues-survey-option,.movcues-widget [data-movcues-survey-action]{min-height:36px;border:1px solid #cbd5e1;border-radius:6px;background:#fff;color:inherit;padding:8px 12px;font:inherit;cursor:pointer}.movcues-widget .movcues-survey-option.is-selected{border-color:var(--movcues-primary);background:color-mix(in srgb,var(--movcues-primary) 12%,white)}.movcues-widget .movcues-survey-input{box-sizing:border-box;width:100%;min-width:0;min-height:36px;border:1px solid #cbd5e1;border-radius:6px;padding:8px;font:inherit}.movcues-widget textarea.movcues-survey-input{min-height:84px;resize:vertical}.movcues-widget .movcues-survey-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.movcues-widget .movcues-survey-footer{width:100%}.movcues-widget [data-movcues-survey-progress]{font-size:12px;margin-bottom:8px}.movcues-widget [data-movcues-survey-progress-bar]{display:block;height:3px;background:var(--movcues-primary);margin-top:5px}.movcues-widget .movcues-survey-validation{color:#b91c1c;font-size:12px}.movcues-widget .movcues-survey-question.has-error{outline:2px solid #dc2626;outline-offset:4px}';\n\nexport function surveyQuestionErrors(questions: SurveyQuestion[]): string[] {\n  if (!Array.isArray(questions) || questions.length > 20) return ['A Survey step supports at most 20 questions.'];\n  const errors: string[] = [], ids = new Set<string>();\n  for (const question of questions) {\n    if (!question || !QUESTION_TYPES.includes(question.type)) { errors.push('Unsupported Survey question type.'); continue; }\n    if (!question.id || question.id.length > 64 || ids.has(question.id)) errors.push('Question IDs must be unique and contain 1â€“64 characters.');\n    ids.add(question.id);\n    if (!question.label?.trim() || question.label.length > 500) errors.push('Question labels must contain 1â€“500 characters.');\n    if (question.required !== undefined && typeof question.required !== 'boolean') errors.push('Required must be a boolean.');\n    if (question.type === 'single_choice' || question.type === 'multiple_choice') {\n      if (!Array.isArray(question.options) || !question.options.length || question.options.length > 20) errors.push('Choice questions need 1â€“20 options.');\n      else { const optionIds = new Set<string>(); for (const option of question.options) { if (!option.id || option.id.length > 64 || optionIds.has(option.id) || !option.label?.trim() || option.label.length > 200) errors.push('Options need unique IDs and nonempty labels (up to 200 characters).'); optionIds.add(option.id); } }\n    } else if (question.type === 'rating' && (!Number.isInteger(question.min) || !Number.isInteger(question.max) || question.min < 0 || question.max > 100 || question.max <= question.min || question.max - question.min > 20)) errors.push('Rating needs an ascending range of at most 21 values between 0 and 100.');\n    else if ((question.type === 'short_text' || question.type === 'long_text') && ((question.maxLength !== undefined && (!Number.isInteger(question.maxLength) || question.maxLength < 1 || question.maxLength > 10000)) || (question.placeholder?.length ?? 0) > 500)) errors.push('Text limit must be 1â€“10,000 and placeholder at most 500 characters.');\n  }\n  return errors;\n}\n\nfunction escape(value: string): string { return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }\n","import { checklistCopy, escapeChecklist, CHECKLIST_CELL_CSS, type OnsiteChecklistContext, type ChecklistView, type ChecklistTextRole, type ChecklistControlRole } from \"../checklist/ChecklistMarkup\";\nimport { surveyQuestionMarkup, surveyControlsMarkup, surveyQuestionErrors, SURVEY_CELL_CSS, type OnsiteSurveyContext } from \"../survey/SurveyMarkup\";\nimport type { ExperienceAction, ExperienceContent, SurveyQuestion, WidgetBuilderState, WidgetType } from \"../types\";\nimport { builderImageUrlIsSafe, builderLinkUrlIsSafe } from \"../runtime/BuilderContentContract\";\n\nexport const ONSITE_SCHEMA_VERSION = 2 as const;\nexport const ONSITE_SURVEY_SCHEMA_VERSION = 3 as const;\nexport const ONSITE_CHECKLIST_SCHEMA_VERSION = 4 as const;\nexport const ONSITE_LIMITS = {\n  maxDepth: 8,\n  maxNodes: 120,\n  maxRichText: 10_000,\n  maxImageUrl: 2_000,\n  maxInlineImage: 65_536,\n  maxSerializedBytes: 250_000,\n  minFixedSize: 24,\n  maxFixedSize: 1_200,\n} as const;\n\nexport type OnsiteDirection = \"row\" | \"column\";\nexport type OnsiteSizing =\n  | { mode: \"flexible\"; weight: number }\n  | { mode: \"hug\" }\n  | { mode: \"fixed\"; value: number };\nexport interface OnsiteSpacing { top: number; right: number; bottom: number; left: number }\nexport interface OnsiteCellStyle { background?: string; borderColor?: string; borderWidth?: number; borderRadius?: number }\nexport interface OnsiteCell {\n  type: \"cell\";\n  checklistRole?: ChecklistView | \"items\";\n  checklistWidth?: number;\n  id: string;\n  direction: OnsiteDirection;\n  sizing: OnsiteSizing;\n  align: \"start\" | \"center\" | \"end\" | \"stretch\";\n  justify: \"start\" | \"center\" | \"end\" | \"space-between\";\n  gap: number;\n  padding: OnsiteSpacing;\n  responsiveStack?: boolean;\n  style?: OnsiteCellStyle;\n  children?: OnsiteCell[];\n  block?: OnsiteBlock;\n}\n\ninterface BlockBase { id: string; align?: \"left\" | \"center\" | \"right\" }\nexport type OnsiteButtonAction =\n  | { id: string; type: \"next_step\" | \"previous_step\" | \"dismiss\" }\n  | { id: string; type: \"open_url\"; url: string }\n  | { id: string; type: \"track_event\"; eventName: string };\nexport type OnsiteBlock =\n  | (BlockBase & { type: \"checklist_task\"; itemId: string; fontSize: number; color?: string; indicator: OnsiteIcon })\n  | (BlockBase & { type: \"checklist_text\"; role: ChecklistTextRole; fontSize: number; color?: string; text?: string })\n  | (BlockBase & { type: \"checklist_control\"; role: ChecklistControlRole; fontSize: number; color?: string })\n  | (BlockBase & { type: \"checklist_progress\"; fontSize: number; color?: string })\n  | (BlockBase & { type: \"question\"; questionId: string; fontSize: number; color?: string })\n  | (BlockBase & { type: \"survey_controls\" })\n  | (BlockBase & { type: \"heading\"; html: string; level: 1 | 2 | 3 | 4; fontSize: number; weight: 400 | 500 | 600 | 700; color?: string; lineHeight?: number })\n  | (BlockBase & { type: \"text\"; html: string; fontSize: number; weight: 400 | 500 | 600 | 700; color?: string; lineHeight?: number })\n  | (BlockBase & { type: \"button\"; label: string; action: OnsiteButtonAction; variant: \"primary\" | \"secondary\" | \"outline\"; background?: string; color?: string; radius: number; paddingX: number; paddingY: number; width: \"hug\" | \"full\" })\n  | (BlockBase & { type: \"image\"; src: string; alt: string; fit: \"contain\" | \"cover\"; width: number; height?: number; radius: number })\n  | (BlockBase & { type: \"divider\"; orientation: \"horizontal\" | \"vertical\"; thickness: number; color: string })\n  | (BlockBase & { type: \"spacer\"; size: number })\n  | (BlockBase & { type: \"icon\"; icon: OnsiteIcon; size: number; color?: string });\nexport type OnsiteIcon = \"check\" | \"star\" | \"info\" | \"warning\" | \"sparkles\" | \"arrow\" | \"heart\" | \"rocket\";\nexport interface OnsiteDocument { schemaVersion: 2 | 3 | 4; id: string; root: OnsiteCell }\nexport interface CompiledOnsiteDocument { html: string; css: string; content: ExperienceContent; actionBindings: Record<string, OnsiteButtonAction> }\nexport interface OnsiteValidationResult { valid: boolean; errors: string[] }\n\nconst ID_PATTERN = /^[A-Za-z][A-Za-z0-9_-]{2,63}$/;\nconst COLOR_PATTERN = /^(#[0-9a-f]{3,8}|(?:rgb|hsl)a?\\([0-9.,%\\s-]+\\)|[a-z]{1,20})$/i;\nconst SAFE_INLINE_TAGS = new Set([\"BR\", \"STRONG\", \"EM\", \"U\", \"A\", \"UL\", \"OL\", \"LI\"]);\nconst ICONS: Record<OnsiteIcon, string> = { check: \"âœ“\", star: \"â˜…\", info: \"â„¹\", warning: \"âš \", sparkles: \"âœ¦\", arrow: \"â†’\", heart: \"â™¥\", rocket: \"ðŸš€\" };\n\nlet idSequence = 0;\nexport function onsiteId(prefix: \"document\" | \"cell\" | \"block\" | \"action\" | \"question\" | \"option\" | \"step\" | \"item\" = \"cell\"): string {\n  idSequence = (idSequence + 1) % 0xffff;\n  const random = typeof crypto !== \"undefined\" && \"getRandomValues\" in crypto\n    ? Array.from(crypto.getRandomValues(new Uint32Array(2))).map(value => value.toString(36)).join(\"\")\n    : `${Date.now().toString(36)}${Math.random().toString(36).slice(2)}`;\n  return `${prefix}_${random}${idSequence.toString(36)}`.slice(0, 64);\n}\n\nexport function emptyCell(block?: OnsiteBlock): OnsiteCell {\n  return { type: \"cell\", id: onsiteId(\"cell\"), direction: \"column\", sizing: { mode: \"flexible\", weight: 1 }, align: \"stretch\", justify: \"start\", gap: 12, padding: { top: 0, right: 0, bottom: 0, left: 0 }, ...(block ? { block } : {}) };\n}\n\nexport function createBlock(type: OnsiteBlock[\"type\"], guide = false): OnsiteBlock {\n  const id = onsiteId(\"block\");\n  if (type.startsWith(\"checklist_\")) throw new Error(\"Insert a structured Checklist component.\");\n  if (type === \"question\") throw new Error(\"Insert a canonical Survey question first.\");\n  if (type === \"survey_controls\") return { id, type };\n  if (type === \"heading\") return { id, type, html: \"A clear heading\", level: 2, fontSize: 24, weight: 600, lineHeight: 1.25 };\n  if (type === \"text\") return { id, type, html: \"Add supporting text for your visitors.\", fontSize: 15, weight: 400, lineHeight: 1.5 };\n  if (type === \"button\") return { id, type, label: guide ? \"Next\" : \"Got it\", action: { id: onsiteId(\"action\"), type: guide ? \"next_step\" : \"dismiss\" }, variant: \"primary\", radius: 8, paddingX: 16, paddingY: 9, width: \"hug\", align: \"right\" };\n  if (type === \"image\") return { id, type, src: \"\", alt: \"\", fit: \"cover\", width: 100, radius: 8, align: \"center\" };\n  if (type === \"divider\") return { id, type, orientation: \"horizontal\", thickness: 1, color: \"#dbe2ea\" };\n  if (type === \"spacer\") return { id, type, size: 24 };\n  return { id, type: \"icon\", icon: \"sparkles\", size: 28, color: \"#2563eb\", align: \"center\" };\n}\n\nexport function createOnsiteDocument(guide = false): OnsiteDocument {\n  const heading = emptyCell(createBlock(\"heading\", guide));\n  const text = emptyCell(createBlock(\"text\", guide));\n  const button = emptyCell(createBlock(\"button\", guide));\n  return { schemaVersion: 2, id: onsiteId(\"document\"), root: { ...emptyCell(), direction: \"column\", gap: 12, padding: { top: 20, right: 20, bottom: 20, left: 20 }, children: [heading, text, button] } };\n}\n\nexport function createOnsiteSurveyDocument(questions: SurveyQuestion[], content?: ExperienceContent): OnsiteDocument {\n  const document = createOnsiteDocument(); document.schemaVersion = 3;\n  const heading = document.root.children![0].block!; if (heading.type === \"heading\" && content) heading.html = escapeText(content.heading);\n  const body = document.root.children![1].block!; if (body.type === \"text\" && content) body.html = escapeText(content.body);\n  document.root.children = [...document.root.children!.slice(0, 2), ...questions.map(question => emptyCell({ id: onsiteId(\"block\"), type: \"question\", questionId: question.id, fontSize: 14 })), emptyCell(createBlock(\"survey_controls\"))];\n  document.root.children.forEach(cell => { cell.sizing = { mode: \"hug\" }; });\n  return document;\n}\n\nexport function validateOnsiteSurveyDocument(document: OnsiteDocument, context: OnsiteSurveyContext): string[] {\n  const errors = surveyQuestionErrors(context.questions), counts = new Map<string, number>();\n  const known = new Set(context.questions.map(question => question.id)); const blocks = listBlocks(document.root);\n  for (const block of blocks) if (block.type === \"question\") {\n    counts.set(block.questionId, (counts.get(block.questionId) ?? 0) + 1);\n    if (!known.has(block.questionId)) errors.push(`Orphaned question reference: ${block.questionId}.`);\n  }\n  for (const question of context.questions) if (counts.get(question.id) !== 1) errors.push(`Question ${question.id} must be referenced exactly once.`);\n  if (blocks.filter(block => block.type === \"survey_controls\").length !== 1) errors.push(\"Survey cells need exactly one navigation/progress block.\");\n  return errors;\n}\n\nexport function duplicateSurveyCell(document: OnsiteDocument, questions: SurveyQuestion[], id: string): { document: OnsiteDocument; questions: SurveyQuestion[]; cellId: string } | null {\n  const candidate = cloneOnsite(document), nextQuestions = cloneOnsite(questions);\n  const cellId = duplicateCell(candidate, id); if (!cellId) return null;\n  for (const block of listBlocks(findCell(candidate, cellId)!)) if (block.type === \"question\") {\n    const source = questions.find(question => question.id === block.questionId); if (!source) return null;\n    const copy = cloneOnsite(source); copy.id = onsiteId(\"question\");\n    if (copy.type === \"single_choice\" || copy.type === \"multiple_choice\") copy.options.forEach(option => { option.id = onsiteId(\"option\"); });\n    block.questionId = copy.id; nextQuestions.push(copy);\n  }\n  if (!validateOnsiteDocument(candidate).valid || validateOnsiteSurveyDocument(candidate, { questions: nextQuestions }).length) return null;\n  return { document: candidate, questions: nextQuestions, cellId };\n}\n\n\nexport function createOnsiteChecklistDocument(context: OnsiteChecklistContext): OnsiteDocument {\n  const text = (role: ChecklistTextRole, size = 14): OnsiteCell => emptyCell({ id: onsiteId('block'), type: 'checklist_text', role, fontSize: size });\n  const control = (role: ChecklistControlRole): OnsiteCell => emptyCell({ id: onsiteId('block'), type: 'checklist_control', role, fontSize: 14 });\n  const group = (role: ChecklistView | 'items', children: OnsiteCell[]): OnsiteCell => ({...emptyCell(), checklistRole:role, sizing:{mode:'hug'}, padding:role === 'items'?{top:0,right:0,bottom:0,left:0}:{top:16,right:16,bottom:16,left:16}, children});\n  const items=group('items',context.items.map(item=>emptyCell({id:onsiteId('block'),type:'checklist_task',itemId:item.id,fontSize:14,indicator:'check'})));\n  return {schemaVersion:4,id:onsiteId('document'),root:{...emptyCell(),sizing:{mode:'hug'},gap:0,children:[\n    group('expanded',[text('title',20),text('description'),emptyCell({id:onsiteId('block'),type:'checklist_progress',fontSize:12}),items,{...emptyCell(),direction:'row',sizing:{mode:'hug'},children:[control('collapse'),control('dismiss')]}]),\n    group('launcher',[emptyCell({id:onsiteId('block'),type:'icon',icon:'check',size:20}),text('launcher-label'),text('remaining-count')]),\n    group('completion',[emptyCell({id:onsiteId('block'),type:'icon',icon:'check',size:28}),text('completion-title',20),text('completion-description'),control('completion-acknowledge')])\n  ]}};\n}\n\nexport function validateOnsiteChecklistDocument(document: OnsiteDocument, context: OnsiteChecklistContext): string[] {\n  const errors:string[]=[]; const views=document.root.children??[];\n  if (document.schemaVersion!==4 || document.root.checklistRole || document.root.block || views.length!==3 || !['expanded','launcher','completion'].every(role=>views.filter(cell=>cell.checklistRole===role).length===1)) errors.push('Checklist document needs exactly one Expanded, Collapsed and Completed view.');\n  const expected:Record<string,string>={title:'expanded',description:'expanded',progress:'expanded',collapse:'expanded',dismiss:'expanded','launcher-label':'launcher','remaining-count':'launcher','completion-title':'completion','completion-description':'completion','completion-acknowledge':'completion'};\n  const counts=new Map<string,number>(), itemCounts=new Map<string,number>(), ids=new Set<string>();let containers=0;\n  if (!context.items.length || context.items.length>20) errors.push('A Checklist needs 1â€“20 tasks.');\n  for (const item of context.items) { if(ids.has(item.id))errors.push('Checklist item IDs must be unique.');ids.add(item.id); if(!item.title.trim())errors.push('Task title cannot be empty.'); }\n  const visit=(cell:OnsiteCell,view:string,inItems=false):void=>{\n    if(cell.checklistRole==='items'){containers++;if(view!=='expanded'||inItems)errors.push('Task container belongs in the Expanded view.');inItems=true;}\n    if(cell.checklistRole && cell.checklistRole!=='items' && cell!==views.find(value=>value.id===cell.id))errors.push('Checklist views cannot be nested.');\n    const block=cell.block;\n    if(block?.type==='checklist_task'){itemCounts.set(block.itemId,(itemCounts.get(block.itemId)??0)+1);if(!ids.has(block.itemId)||!inItems||view!=='expanded')errors.push('Orphaned task reference or task outside the Expanded task container.');}\n    else if(block?.type==='checklist_text'||block?.type==='checklist_control'||block?.type==='checklist_progress'){\n      const role=block.type==='checklist_progress'?'progress':block.role;counts.set(role,(counts.get(role)??0)+1);if(expected[role]!==view||inItems)errors.push('Checklist structural component is in the wrong view.');\n    } else if(block && ['question','survey_controls','button'].includes(block.type))errors.push('Use Checklist controls and tasks in a Checklist document.');\n    cell.children?.forEach(child=>visit(child,view,inItems));\n  };\n  views.forEach(view=>visit(view,view.checklistRole??''));\n  if(containers!==1)errors.push('Checklist needs exactly one task container.');\n  for(const role of Object.keys(expected))if(counts.get(role)!==1)errors.push(`Checklist role ${role} must appear exactly once.`);\n  for(const item of context.items)if(itemCounts.get(item.id)!==1)errors.push(`Task ${item.id} must be referenced exactly once.`);\n  const order=listBlocks(document.root).filter((block):block is Extract<OnsiteBlock,{type:\"checklist_task\"}>=>block.type===\"checklist_task\").map(block=>block.itemId);\n  if(JSON.stringify(order)!==JSON.stringify(context.items.map(item=>item.id)))errors.push(\"Task layout order must match the canonical item order.\");\n  return errors;\n}\n\nexport function duplicateChecklistCell(document: OnsiteDocument, context: OnsiteChecklistContext, cellId: string): {document:OnsiteDocument;items:OnsiteChecklistContext['items'];cellId:string}|null {\n  const candidate=cloneOnsite(document),items=cloneOnsite(context.items),id=duplicateCell(candidate,cellId);if(!id)return null;\n  for(const block of listBlocks(findCell(candidate,id)!))if(block.type==='checklist_task'){\n    const source=items.find(item=>item.id===block.itemId);if(!source)return null;\n    const copy={...cloneOnsite(source),id:onsiteId('item')};block.itemId=copy.id;items.push(copy);\n  }\n  const ordered=listBlocks(candidate.root).filter((block):block is Extract<OnsiteBlock,{type:'checklist_task'}>=>block.type==='checklist_task').map(block=>items.find(item=>item.id===block.itemId)!);\n  if(validateOnsiteChecklistDocument(candidate,{...context,items:ordered}).length||!validateOnsiteDocument(candidate).valid)return null;\n  return{document:candidate,items:ordered,cellId:id};\n}\n\nexport function onsiteDocumentFromBuilder(builder?: WidgetBuilderState): OnsiteDocument | null {\n  const movcues = builder?.projectData?.movcues;\n  if (!movcues || typeof movcues !== \"object\") return null;\n  const document = (movcues as Record<string, unknown>).onsiteDocument;\n  return isOnsiteDocument(document) ? document : null;\n}\n\nexport function applyOnsiteDocument(builder: WidgetBuilderState, document: OnsiteDocument, widgetType: WidgetType | \"anchored_card\" | \"modal\" | \"checklist\", survey?: OnsiteSurveyContext, checklist?: OnsiteChecklistContext): CompiledOnsiteDocument {\n  const compiled = compileOnsiteDocument(document, widgetType, survey, checklist);\n  builder.version = 1;\n  builder.projectData = { ...builder.projectData, movcues: { ...asRecord(builder.projectData.movcues), authoringSurface: \"onsite\", schemaVersion: document.schemaVersion, onsiteDocument: document, actionBindings: compiled.actionBindings } };\n  builder.html = compiled.html;\n  builder.css = compiled.css;\n  return compiled;\n}\n\nexport function compileOnsiteDocument(document: OnsiteDocument, widgetType: string, survey?: OnsiteSurveyContext, checklist?: OnsiteChecklistContext): CompiledOnsiteDocument {\n  const validation = validateOnsiteDocument(document);\n  if (!validation.valid) throw new Error(validation.errors.join(\" \"));\n  if (document.schemaVersion === 4) {\n    if (widgetType !== \"checklist\" || !checklist || survey) throw new Error(\"Version 4 requires a Checklist context.\");\n    const errors = validateOnsiteChecklistDocument(document, checklist); if (errors.length) throw new Error(errors.join(\" \"));\n  } else if (checklist) throw new Error(\"Checklist cells require document version 4.\");\n  if (document.schemaVersion === 3) {\n    if (widgetType !== \"survey\" || !survey) throw new Error(\"Version 3 requires a Survey question context.\");\n    const errors = validateOnsiteSurveyDocument(document, survey); if (errors.length) throw new Error(errors.join(\" \"));\n  } else if (survey) throw new Error(\"Survey cells require document version 3.\");\n  const css: string[] = [\n    \".movcues-widget{box-sizing:border-box;width:100%;max-width:100%;min-width:0;overflow-wrap:anywhere;padding:var(--movcues-theme-spacing,0);background:var(--movcues-bg);color:var(--movcues-fg);border-color:var(--movcues-border,transparent);border-radius:var(--movcues-theme-radius,inherit);font-family:var(--movcues-font-body,ui-sans-serif,system-ui,sans-serif);font-size:var(--movcues-font-body-size,15px);box-shadow:var(--movcues-theme-shadow,none)}\",\n    \".movcues-widget *{box-sizing:border-box}\",\n    \".movcues-widget .movcues-cell{display:flex;min-width:0;max-width:100%}\",\n    \".movcues-widget .movcues-block{min-width:0;max-width:100%;margin:0}\",\n    \".movcues-widget .movcues-block img{display:block;max-width:100%}\",\n    \".movcues-widget .movcues-heading{font-family:var(--movcues-font-heading,var(--movcues-font-body));font-size:var(--movcues-font-heading-size,inherit)}\",\n    \".movcues-widget .movcues-button{min-height:40px;border:0;border-radius:var(--movcues-button-radius,8px);font:600 14px/1.2 var(--movcues-font-body,ui-sans-serif,system-ui,sans-serif);cursor:pointer}\",\n    \".movcues-widget .movcues-button--primary{background:var(--movcues-primary);color:var(--movcues-primary-fg,#fff)}\",\n    \".movcues-widget .movcues-button--secondary{background:transparent;color:inherit}\",\n    \".movcues-widget .movcues-button--outline{background:transparent;color:inherit;border:1px solid currentColor}\",\n    \".movcues-widget .movcues-block--full{width:100%}\",\n  ];\n  if (document.schemaVersion === 3) css.push(SURVEY_CELL_CSS);\n  if (document.schemaVersion === 4) css.push(CHECKLIST_CELL_CSS);\n  const html = renderCell(document.root, css, 0, survey, checklist);\n  css.push(\"@media(max-width:480px){.movcues-widget [data-movcues-responsive-stack=\\\"true\\\"]{flex-direction:column!important}.movcues-widget [data-movcues-sizing=\\\"fixed\\\"]{max-width:100%!important}.movcues-widget .movcues-button{min-height:40px}.movcues-widget img{height:auto!important}}\");\n  const blocks = listBlocks(document.root);\n  const firstHeading = blocks.find(block => block.type === \"heading\") as Extract<OnsiteBlock, { type: \"heading\" }> | undefined;\n  const text = blocks.filter(block => block.type === \"text\").map(block => richTextToPlain((block as Extract<OnsiteBlock, { type: \"text\" }>).html)).join(\"\\n\").slice(0, 2_000);\n  const actions = blocks.filter(block => block.type === \"button\") as Array<Extract<OnsiteBlock, { type: \"button\" }>>;\n  const actionBindings = Object.fromEntries(actions.map(block => [block.action.id, block.action]));\n  const legacy = actions.slice(0, 2).map(block => ({ label: block.label, type: block.action.type === \"previous_step\" ? \"dismiss\" as const : block.action.type, ...(\"url\" in block.action ? { url: block.action.url } : {}), ...(\"eventName\" in block.action ? { eventName: block.action.eventName } : {}) }));\n  const content: ExperienceContent = {\n    heading: checklist ? checklist.title : firstHeading ? richTextToPlain(firstHeading.html).slice(0, 160) : \"\",\n    body: checklist ? checklist.description ?? \"\" : text,\n    ...(legacy[0] ? { primaryAction: legacy[0] as ExperienceAction } : {}),\n    ...(legacy[1]?.type === \"dismiss\" ? { secondaryAction: { label: legacy[1].label, type: \"dismiss\" as const } } : {}),\n  };\n  return { html: `<section class=\"movcues-widget movcues-widget--${escapeAttribute(widgetType)}\" data-movcues-widget-type=\"${escapeAttribute(widgetType)}\" data-movcues-document-version=\"${document.schemaVersion}\"${checklist ? ' data-movcues-checklist-role=\"root\"' : \"\"}>${html}</section>`, css: css.join(\"\"), content, actionBindings };\n}\n\nfunction renderCell(cell: OnsiteCell, css: string[], depth: number, survey?: OnsiteSurveyContext, checklist?: OnsiteChecklistContext): string {\n  const selector = `.movcues-widget [data-movcues-node-id=\"${cell.id}\"]`;\n  const sizing = cell.sizing.mode === \"flexible\" ? `flex:${round(cell.sizing.weight)} 1 0` : cell.sizing.mode === \"hug\" ? \"flex:0 0 auto\" : `flex:0 1 ${cell.sizing.value}px`;\n  const style = cell.style ?? {};\n  css.push(`${selector}{${sizing};flex-direction:${cell.direction};align-items:${cell.align};justify-content:${cell.justify};gap:${cell.gap}px;padding:${cell.padding.top}px ${cell.padding.right}px ${cell.padding.bottom}px ${cell.padding.left}px;${style.background ? `background:${style.background};` : \"\"}${style.borderWidth ? `border:${style.borderWidth}px solid ${style.borderColor ?? \"#dbe2ea\"};` : \"\"}${style.borderRadius ? `border-radius:${style.borderRadius}px;` : \"\"}}`);\n  if (cell.checklistWidth !== undefined) css.push(`.movcues-widget--checklist:has([data-movcues-node-id=\"${cell.id}\"].is-active){width:${cell.checklistWidth}px}`);\n  const children = cell.children?.map(child => renderCell(child, css, depth + 1, survey, checklist)).join(\"\") ?? (cell.block ? renderBlock(cell.block, css, survey, checklist) : \"\");\n  return `<div class=\"movcues-cell\" data-movcues-node-id=\"${cell.id}\"${cell.checklistRole ? cell.checklistRole === \"items\" ? ' data-movcues-checklist-role=\"items\"' : ` data-movcues-checklist-view=\"${cell.checklistRole}\"` : \"\"} data-movcues-sizing=\"${cell.sizing.mode}\"${cell.responsiveStack ? ' data-movcues-responsive-stack=\"true\"' : \"\"}>${children}</div>`;\n}\n\nfunction renderBlock(block: OnsiteBlock, css: string[], survey?: OnsiteSurveyContext, checklist?: OnsiteChecklistContext): string {\n  const selector = `.movcues-widget [data-movcues-block-id=\"${block.id}\"]`;\n  const align = block.align ?? \"left\";\n  if ((block.type === \"checklist_task\" || block.type === \"checklist_text\" || block.type === \"checklist_control\" || block.type === \"checklist_progress\")) {\n    if (!checklist) throw new Error(\"Checklist component needs canonical context.\");\n    const item = block as Extract<OnsiteBlock, { type: \"checklist_task\" | \"checklist_text\" | \"checklist_control\" | \"checklist_progress\" }>;\n    css.push(`${selector}{font-size:${item.fontSize}px;text-align:${align};${item.color ? `color:${item.color};` : \"\"}}`);\n    const attrs = `class=\"movcues-block\" data-movcues-block-id=\"${block.id}\"`;\n    if (item.type === \"checklist_task\") {\n      const task = checklist.items.find(value => value.id === item.itemId)!;\n      return `<button type=\"button\" class=\"movcues-block movcues-checklist__item\" data-movcues-block-id=\"${item.id}\" data-movcues-checklist-role=\"item\" data-movcues-checklist-item-id=\"${escapeChecklist(task.id)}\"><span data-movcues-checklist-item-role=\"state\">${ICONS[item.indicator]}</span><span 