wanted, responsiveStack: wanted === \"row\", children: edge === \"top\" || edge === \"left\" ? [added, old] : [old, added] }; }\n  return added.id;\n}\n/** Insert beside one cell, wrapping only that cell when its parent's axis differs. */\nexport function insertAdjacentCell(document: OnsiteDocument, cellId: string, edge: \"top\" | \"right\" | \"bottom\" | \"left\"): string | null {\n  const cell = findCell(document, cellId); if (!cell) return null;\n  if (cell === document.root) return insertEdgeCell(document, edge);\n  const parent = parentCell(document, cellId); if (!parent?.children) return null;\n  const direction = edge === \"left\" || edge === \"right\" ? \"row\" : \"column\";\n  const before = edge === \"top\" || edge === \"left\";\n  const index = parent.children.indexOf(cell); const added = emptyCell();\n  if (parent.direction === direction) parent.children.splice(index + (before ? 0 : 1), 0, added);\n  else {\n    const group: OnsiteCell = { ...emptyCell(), direction, sizing: cloneOnsite(cell.sizing), gap: parent.gap, responsiveStack: direction === \"row\", children: before ? [added, cell] : [cell, added] };\n    cell.sizing = { mode: \"flexible\", weight: 1 };\n    parent.children.splice(index, 1, group);\n  }\n  return added.id;\n}\nexport function removeCell(document: OnsiteDocument, id: string): boolean {\n  const parent = parentCell(document, id); if (!parent?.children || parent.children.length <= 1) { const cell = findCell(document, id); if (!cell || cell === document.root) return false; delete cell.block; return true; }\n  parent.children = parent.children.filter(child => child.id !== id); if (parent.children.length === 1) collapseSingleChild(parent); return true;\n}\nexport function moveCell(document: OnsiteDocument, id: string, delta: -1 | 1): boolean { const parent = parentCell(document, id); if (!parent?.children) return false; const index = parent.children.findIndex(child => child.id === id); const next = index + delta; if (index < 0 || next < 0 || next >= parent.children.length) return false; [parent.children[index], parent.children[next]] = [parent.children[next], parent.children[index]]; return true; }\nexport function resizeSiblings(document: OnsiteDocument, firstId: string, secondId: string, firstWeight: number): boolean { const parent = parentCell(document, firstId); if (!parent?.children || parent !== parentCell(document, secondId)) return false; const a = parent.children.find(child => child.id === firstId); const b = parent.children.find(child => child.id === secondId); if (!a || !b) return false; const bounded = Math.max(0.1, Math.min(1.9, Math.round(firstWeight * 20) / 20)); a.sizing = { mode: \"flexible\", weight: bounded }; b.sizing = { mode: \"flexible\", weight: 2 - bounded }; return true; }\nexport function duplicateCell(document: OnsiteDocument, id: string): string | null { const source = findCell(document, id); const parent = parentCell(document, id); if (!source || !parent?.children) return null; const copy = structuredCloneSafe(source); regenerateIds(copy); const index = parent.children.findIndex(child => child.id === id); parent.children.splice(index + 1, 0, copy); return copy.id; }\nfunction regenerateIds(cell: OnsiteCell): void { cell.id = onsiteId(\"cell\"); if (cell.block) { cell.block.id = onsiteId(\"block\"); if (cell.block.type === \"button\") cell.block.action.id = onsiteId(\"action\"); } cell.children?.forEach(regenerateIds); }\nfunction collapseSingleChild(cell: OnsiteCell): void { if (cell.checklistRole) return; const child = cell.children?.[0]; if (!child) return; const id = cell.id; Object.assign(cell, child, { id }); }\n\nexport function duplicateDocument(document: OnsiteDocument): OnsiteDocument { const copy = structuredCloneSafe(document); copy.id = onsiteId(\"document\"); regenerateIds(copy.root); return copy; }\nexport function cloneOnsite<T>(value: T): T { return structuredCloneSafe(value); }\nfunction structuredCloneSafe<T>(value: T): T { return typeof structuredClone === \"function\" ? structuredClone(value) : JSON.parse(JSON.stringify(value)) as T; }\n\nexport function migrateV1Builder(builder: WidgetBuilderState, content: ExperienceContent, widgetType: WidgetType | \"anchored_card\" | \"modal\" | \"checklist\", guide = false): OnsiteDocument | null {\n  if (onsiteDocumentFromBuilder(builder)) return onsiteDocumentFromBuilder(builder);\n  if (typeof document === \"undefined\") return null;\n  const template = document.createElement(\"template\"); template.innerHTML = builder.html;\n  const root = template.content.querySelector(\".movcues-widget\"); if (!root) return null;\n  const known = root.querySelectorAll(\"[data-movcues-content],[data-movcues-action-id],img\");\n  if (!known.length || root.querySelector(\"[data-movcues-question-id],[data-movcues-checklist-role]\")) return null;\n  const compatibility = root.cloneNode(true) as Element; compatibility.querySelectorAll(\"[data-movcues-content],[data-movcues-action-id],img\").forEach(element => element.remove()); compatibility.querySelectorAll(\"*\").forEach(element => { if (!element.textContent?.trim() && !element.children.length) element.remove(); });\n  if (compatibility.textContent?.trim() || compatibility.children.length) return null;\n  const cells: OnsiteCell[] = [];\n  const alignment = (element: Element): \"left\" | \"center\" | \"right\" | undefined => element.classList.contains(\"movcues-align-center\") ? \"center\" : element.classList.contains(\"movcues-align-right\") ? \"right\" : element.classList.contains(\"movcues-align-left\") ? \"left\" : undefined;\n  const heading = root.querySelector<HTMLElement>('[data-movcues-content=\"heading\"]'); if (heading) { const block = createBlock(\"heading\", guide) as Extract<OnsiteBlock, { type: \"heading\" }>; block.html = sanitizeRichText(heading.innerHTML); block.align = alignment(heading); cells.push(emptyCell(block)); }\n  const body = root.querySelector<HTMLElement>('[data-movcues-content=\"body\"]'); if (body) { const block = createBlock(\"text\", guide) as Extract<OnsiteBlock, { type: \"text\" }>; block.html = sanitizeRichText(body.innerHTML); block.align = alignment(body); cells.push(emptyCell(block)); }\n  root.querySelectorAll<HTMLImageElement>(\"img\").forEach(image => { const block = createBlock(\"image\", guide) as Extract<OnsiteBlock, { type: \"image\" }>; block.src = image.getAttribute(\"src\") ?? \"\"; block.alt = image.getAttribute(\"alt\") ?? \"\"; cells.push(emptyCell(block)); });\n  for (const [marker, fallback] of [[\"secondary\", content.secondaryAction], [\"primary\", content.primaryAction]] as const) { const button = root.querySelector<HTMLElement>(`[data-movcues-action-id=\"${marker}\"]`); if (!button || !fallback) continue; const block = createBlock(\"button\", guide) as Extract<OnsiteBlock, { type: \"button\" }>; block.label = fallback.label; block.variant = marker === \"primary\" ? \"primary\" : \"secondary\"; block.action = { id: onsiteId(\"action\"), ...(fallback.type === \"open_url\" && fallback.url ? { type: \"open_url\" as const, url: fallback.url } : fallback.type === \"track_event\" && fallback.eventName ? { type: \"track_event\" as const, eventName: fallback.eventName } : { type: fallback.type === \"next_step\" ? \"next_step\" as const : \"dismiss\" as const }) }; cells.push(emptyCell(block)); }\n  if (!cells.length) return null;\n  const migrated: OnsiteDocument = { schemaVersion: 2, id: onsiteId(\"document\"), root: { ...emptyCell(), direction: \"column\", gap: 12, padding: { top: 20, right: 20, bottom: 20, left: 20 }, children: cells } };\n  applyOnsiteDocument(builder, migrated, widgetType); return migrated;\n}\n\nexport function sanitizeRichText(input: string): string {\n  if (typeof document === \"undefined\") return sanitizeRichTextWithoutDom(input);\n  const template = document.createElement(\"template\"); template.innerHTML = input;\n  for (const element of Array.from(template.content.querySelectorAll(\"*\"))) {\n    if (!SAFE_INLINE_TAGS.has(element.tagName)) { element.replaceWith(...Array.from(element.childNodes)); continue; }\n    for (const attribute of Array.from(element.attributes)) if (!(element.tagName === \"A\" && [\"href\", \"target\", \"rel\"].includes(attribute.name))) element.removeAttribute(attribute.name);\n    if (element.tagName === \"A\") { const href = element.getAttribute(\"href\") ?? \"\"; if (!builderLinkUrlIsSafe(href)) element.removeAttribute(\"href\"); const target = element.getAttribute(\"target\"); if (target && ![\"_blank\", \"_self\"].includes(target)) element.removeAttribute(\"target\"); if (target === \"_blank\") element.setAttribute(\"rel\", \"noopener noreferrer\"); }\n  }\n  return template.innerHTML;\n}\nfunction sanitizeRichTextWithoutDom(input: string): string { return input.replace(/<(?!\\/?(?:br|strong|em|u|a|ul|ol|li)(?:\\s|>|\\/))/gi, \"&lt;\").replace(/\\son[a-z]+\\s*=\\s*([\"']).*?\\1/gi, \"\").replace(/javascript\\s*:/gi, \"\"); }\nfunction richTextToPlain(input: string): string {\n  if (typeof document === \"undefined\") return input.replace(/<br\\s*\\/?>/gi, \"\\n\").replace(/<\\/li>/gi, \"\\n\").replace(/<[^>]+>/g, \"\").replace(/&nbsp;/g, \" \").trim();\n  const template = document.createElement(\"template\"); template.innerHTML = input;\n  const read = (node: Node): string => {\n    if (node.nodeType === 3) return node.textContent ?? \"\";\n    let value = \"\";\n    for (const child of Array.from(node.childNodes)) { if (child instanceof HTMLElement && child.tagName === \"BR\") value += \"\\n\"; else { value += read(child); if (child instanceof HTMLElement && child.tagName === \"LI\") value += \"\\n\"; } }\n    return value;\n  };\n  return read(template.content).trim();\n}\nfunction isOnsiteDocument(value: unknown): value is OnsiteDocument { return isOnsiteDocumentShape(value) && validateOnsiteDocument(value).valid; }\nfunction isOnsiteDocumentShape(value: unknown): value is OnsiteDocument { return !!value && typeof value === \"object\" && [2, 3, 4].includes((value as OnsiteDocument).schemaVersion) && !!(value as OnsiteDocument).root && (value as OnsiteDocument).root.type === \"cell\"; }\nfunction asRecord(value: unknown): Record<string, unknown> { return value && typeof value === \"object\" && !Array.isArray(value) ? value as Record<string, unknown> : {}; }\nfunction escapeText(value: string): string { return value.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\"); }\nfunction escapeAttribute(value: string): string { return escapeText(value).replace(/\"/g, \"&quot;\"); }\nfunction round(value: number): string { return String(Math.round(value * 100) / 100); }\n","import type { SurveyAnswers, SurveyBranchRule, SurveyConfig } from '../types';\n\nexport function nextSurveyStep(survey: SurveyConfig, index: number, answers: SurveyAnswers): number | null {\n  const step = survey.steps[index]; if (!step) return null;\n  const rule = step.branching?.rules.find(rule => matches(rule, answers[rule.questionId]));\n  const destination = rule?.nextStepId ?? step.branching?.defaultNextStepId;\n  if (destination === 'submit') return null;\n  const next = destination ? survey.steps.findIndex(step => step.id === destination) : index + 1;\n  return next > index && next < survey.steps.length ? next : null;\n}\n\n/** Derived solely from the published definition and answer values, never client visited-step claims. */\nexport function surveyPath(survey: SurveyConfig, answers: SurveyAnswers): number[] {\n  const path: number[] = []; let index: number | null = survey.steps.length ? 0 : null;\n  while (index !== null && path.length < survey.steps.length) { path.push(index); index = nextSurveyStep(survey, index, answers); }\n  return path;\n}\n\nexport function answersOnSurveyPath(survey: SurveyConfig, answers: SurveyAnswers): SurveyAnswers {\n  const ids = new Set(surveyPath(survey, answers).flatMap(index => survey.steps[index].questions.map(question => question.id)));\n  return Object.fromEntries(Object.entries(answers).filter(([id]) => ids.has(id)));\n}\n\nexport function surveyBranchErrors(survey: SurveyConfig): string[] {\n  const errors: string[] = [];\n  survey.steps.forEach((step, index) => {\n    if (!step.branching) return;\n    const forward = (id?: string) => id === undefined || id === 'submit' || survey.steps.findIndex(step => step.id === id) > index;\n    if (!forward(step.branching.defaultNextStepId)) errors.push('Survey navigation must target a later step or Submit.');\n    if (!Array.isArray(step.branching.rules) || step.branching.rules.length > 10) { errors.push('A Survey step supports at most 10 branch rules.'); return; }\n    for (const rule of step.branching.rules) {\n      const question = step.questions.find(question => question.id === rule.questionId);\n      if (!question || !forward(rule.nextStepId) || !rule.nextStepId) { errors.push('A branch must use a question on its own step and a forward destination.'); continue; }\n      if (rule.operator === 'answered') { if (rule.value !== undefined) errors.push('Answered conditions do not use a comparison value.'); continue; }\n      const choice = question.type === 'single_choice' || question.type === 'multiple_choice';\n      const numeric = question.type === 'rating' || question.type === 'nps';\n      if (rule.operator === 'includes') {\n        if (question.type !== 'multiple_choice' || typeof rule.value !== 'string' || !question.options.some(option => option.id === rule.value)) errors.push('Includes needs an existing multiple-choice option.');\n      } else if (rule.operator === 'gte' || rule.operator === 'lte') {\n        if (!numeric || typeof rule.value !== 'number' || !Number.isInteger(rule.value) || rule.value < (question.type === 'nps' ? 0 : question.min) || rule.value > (question.type === 'nps' ? 10 : question.max)) errors.push('Numeric conditions need a value in the question range.');\n      } else if (rule.operator === 'equals' || rule.operator === 'not_equals') {\n        if (question.type === 'multiple_choice' || (numeric ? typeof rule.value !== 'number' || !Number.isInteger(rule.value) || rule.value < (question.type === 'nps' ? 0 : question.min) || rule.value > (question.type === 'nps' ? 10 : question.max) : typeof rule.value !== 'string') || (choice && !question.options.some(option => option.id === rule.value))) errors.push('Comparison value must match the question type and options.');\n      } else errors.push('Unsupported Survey branch operator.');\n    }\n  });\n  return errors;\n}\n\nfunction matches(rule: SurveyBranchRule, answer: SurveyAnswers[string] | undefined): boolean {\n  if (rule.operator === 'answered') return answer !== undefined && answer !== '' && (!Array.isArray(answer) || answer.length > 0);\n  if (rule.operator === 'equals') return answer === rule.value;\n  if (rule.operator === 'not_equals') return answer !== undefined && answer !== rule.value;\n  if (rule.operator === 'includes') return Array.isArray(answer) && typeof rule.value === 'string' && answer.includes(rule.value);\n  if (rule.operator === 'gte') return typeof answer === 'number' && typeof rule.value === 'number' && answer >= rule.value;\n  if (rule.operator === 'lte') return typeof answer === 'number' && typeof rule.value === 'number' && answer <= rule.value;\n  return false;\n}\n","import type { SurveyQuestion, SurveyStep } from '../types';\nimport { applyOnsiteDocument, cloneOnsite, createOnsiteSurveyDocument, duplicateDocument, listBlocks, onsiteDocumentFromBuilder, onsiteId } from '../onsite/OnsiteDocument';\n\nexport function newSurveyQuestion(type: SurveyQuestion['type']): SurveyQuestion {\n  const base = { id: onsiteId('question'), label: 'Your question', required: false };\n  if (type === 'single_choice' || type === 'multiple_choice') return { ...base, type, options: [{ id: onsiteId('option'), label: 'Yes' }, { id: onsiteId('option'), label: 'No' }] };\n  if (type === 'short_text' || type === 'long_text') return { ...base, type, placeholder: '', maxLength: type === 'short_text' ? 200 : 2000 };\n  if (type === 'rating') return { ...base, type, min: 1, max: 5 };\n  return { ...base, type: 'nps' };\n}\n\nexport function newSurveyStep(submitLabel: string): SurveyStep {\n  const step: SurveyStep = { id: onsiteId('step'), content: { heading: 'New Survey step', body: '' }, questions: [], builder: { version: 1, html: '', css: '', projectData: {} } };\n  step.content = applyOnsiteDocument(step.builder!, createOnsiteSurveyDocument(step.questions, step.content), 'survey', { questions: step.questions, submitLabel }).content;\n  return step;\n}\n\nexport function duplicateSurveyStep(source: SurveyStep, submitLabel: string): SurveyStep {\n  const copy = cloneOnsite(source); copy.id = onsiteId('step');\n  const questions = new Map<string, string>(), options = new Map<string, string>();\n  copy.questions.forEach(question => {\n    const old = question.id; question.id = onsiteId('question'); questions.set(old, question.id);\n    if ('options' in question) question.options.forEach(option => { const old = option.id; option.id = onsiteId('option'); options.set(`${question.id}:${old}`, option.id); });\n  });\n  copy.branching?.rules.forEach(rule => { rule.questionId = questions.get(rule.questionId)!; const key = `${rule.questionId}:${rule.value}`; if (typeof rule.value === 'string' && options.has(key)) rule.value = options.get(key)!; });\n  const document = onsiteDocumentFromBuilder(copy.builder);\n  if (!document || !copy.builder) throw new Error('This Survey step is not an on-site document.');\n  const duplicated = duplicateDocument(document);\n  listBlocks(duplicated.root).forEach(block => { if (block.type === 'question') block.questionId = questions.get(block.questionId)!; });\n  copy.content = applyOnsiteDocument(copy.builder, duplicated, 'survey', { questions: copy.questions, submitLabel }).content;\n  return copy;\n}\n","import type { SurveyBranchRule, SurveyConfig, SurveyQuestion } from '../types';\nimport { applyOnsiteDocument, cloneOnsite, onsiteDocumentFromBuilder, onsiteId } from '../onsite/OnsiteDocument';\nimport { QUESTION_TYPES } from '../survey/SurveyMarkup';\nimport { surveyBranchErrors } from '../survey/SurveyLogic';\nimport { duplicateSurveyStep, newSurveyQuestion, newSurveyStep } from './SurveyEditing';\nimport type { OnsiteCompositionEditor } from './OnsiteCompositionEditor';\n\ninterface Options {\n  index(): number;\n  composer(): OnsiteCompositionEditor | null;\n  canEdit(): boolean;\n  flush(): boolean;\n  changed(): void;\n  stepsChanged(index: number): void;\n  error(errors: string[]): void;\n}\nconst LABELS: Record<SurveyQuestion['type'], string> = { single_choice: 'Single choice', multiple_choice: 'Multiple choice', short_text: 'Short text', long_text: 'Long text', rating: 'Rating', nps: 'NPS' };\n\n/** Editor-only Survey controls. The existing cell editor owns layout and history. */\nexport class SurveyEditor {\n  private questionHost = document.createElement('div');\n  private stepHost = document.createElement('div');\n  private dock = document.createElement('div');\n  private style = document.createElement('style');\n  constructor(private root: ShadowRoot, private survey: SurveyConfig, private options: Options) {\n    this.questionHost.dataset.block = 'question'; this.questionHost.hidden = true;\n    this.questionHost.innerHTML = `<label>Question type<select data-survey-question-type>${QUESTION_TYPES.map(type => `<option value=\"${type}\">${LABELS[type]}</option>`).join('')}</select></label><label>Question label<input data-survey-question-label aria-label=\"Question label\" maxlength=\"500\"></label><label class=\"check\"><input type=\"checkbox\" data-survey-question-required> Required</label><label data-question-options>Choices (one per line)<textarea data-survey-options rows=\"4\" maxlength=\"4000\"></textarea></label><div data-question-text><label>Placeholder<input data-survey-placeholder maxlength=\"500\"></label><label>Answer length limit<input type=\"number\" data-survey-max-length min=\"1\" max=\"10000\"></label></div><div data-question-rating><label>Minimum<input type=\"number\" data-survey-rating-min min=\"0\" max=\"99\"></label><label>Maximum<input type=\"number\" data-survey-rating-max min=\"1\" max=\"100\"></label></div><label>Question font size<input data-survey-font-size type=\"number\" min=\"10\" max=\"36\"></label><label>Question color<input data-survey-question-color type=\"color\"></label>`;\n    this.stepHost.dataset.surveyStepInspector = '';\n    this.stepHost.innerHTML = '<label>Survey step heading<input data-survey-step-heading maxlength=\"160\"></label><label class=\"check\"><input type=\"checkbox\" data-survey-allow-back> Allow Back</label><label class=\"check\"><input type=\"checkbox\" data-survey-show-progress> Show progress</label><label>Submit label<input data-survey-submit-label maxlength=\"80\"></label><details data-survey-branch-section><summary>After this step</summary><label>Default next step<select data-survey-default-next></select></label><div data-survey-rules></div><button type=\"button\" class=\"secondary-button\" data-survey-add-rule>Add answer rule</button><small>First matching rule wins. Destinations can only move forward.</small></details>';\n    this.dock.dataset.surveyDock = '';\n    this.dock.innerHTML = '<button type=\"button\" class=\"secondary-button compact\" data-survey-add-step aria-label=\"Add Survey step\">ï¼‹</button><details><summary aria-label=\"Survey step actions\">â‹¯</summary><div><button type=\"button\" data-survey-duplicate-step>Duplicate step</button><button type=\"button\" data-survey-move=\"-1\">Move step earlier</button><button type=\"button\" data-survey-move=\"1\">Move step later</button><button type=\"button\" data-survey-delete-step>Delete step</button></div></details>';\n    this.style.textContent = '[data-survey-step-inspector],[data-block=question]{display:grid;gap:8px}[data-survey-options]{box-sizing:border-box;width:100%;border:1px solid #d7dce3;border-radius:6px;padding:7px;font:12px/1.5 ui-sans-serif,system-ui}[data-survey-branch-section]>summary{cursor:pointer;font-weight:600;margin:4px 0 8px}[data-survey-rule]{display:grid;grid-template-columns:minmax(0,1fr);gap:5px;padding:8px 0;border-top:1px solid #e5e7eb}[data-survey-step-inspector] small{display:block;color:#64748b;font-size:11px;margin-top:6px}.step-navigator>[data-survey-dock]{display:flex;flex:none;gap:4px;align-items:center}[data-survey-dock][hidden]{display:none!important}[data-survey-dock] details>summary{list-style:none;cursor:pointer;border:1px solid #d7dce3;border-radius:6px;padding:3px 7px}[data-survey-dock] details>div{position:absolute;bottom:calc(100% + 6px);right:4px;display:grid;gap:4px;min-width:150px;padding:6px;background:#fff;border:1px solid #d7dce3;border-radius:8px;box-shadow:0 4px 18px #0f172a20}[data-survey-dock] details button{border:0;background:#fff;padding:7px;text-align:left;font:12px ui-sans-serif,system-ui;cursor:pointer}';\n    root.querySelector('[data-inspector=block]')?.append(this.questionHost);\n    root.querySelector('[data-inspector=step]')?.append(this.stepHost);\n    root.querySelector('[data-guide]')?.append(this.dock); root.append(this.style);\n    root.addEventListener('change', this.onChange); root.addEventListener('click', this.onClick);\n  }\n\n  sync(): void {\n    const step = this.survey.steps[this.options.index()], composer = this.options.composer();\n    if (!step) return;\n    this.dock.hidden = !this.options.canEdit();\n    this.value('[data-survey-step-heading]', step.content.heading);\n    this.check('[data-survey-allow-back]', this.survey.allowBack); this.check('[data-survey-show-progress]', this.survey.showProgress); this.value('[data-survey-submit-label]', this.survey.submitLabel);\n    this.root.querySelectorAll('[data-step] small').forEach((label, index) => { if (this.survey.steps[index]) label.textContent = this.survey.steps[index].content.heading || `Step ${index + 1}`; });\n    const question = composer?.getSelectedQuestion(); this.questionHost.hidden = !question;\n    if (question) {\n      this.value('[data-survey-question-type]', question.type); this.value('[data-survey-question-label]', question.label); this.check('[data-survey-question-required]', Boolean(question.required));\n      this.questionHost.querySelector<HTMLElement>('[data-question-options]')!.hidden = !('options' in question);\n      this.questionHost.querySelector<HTMLElement>('[data-question-text]')!.hidden = !['short_text', 'long_text'].includes(question.type);\n      this.questionHost.querySelector<HTMLElement>('[data-question-rating]')!.hidden = question.type !== 'rating';\n      if ('options' in question) this.value('[data-survey-options]', question.options.map(option => option.label).join('\\n'));\n      if (question.type === 'short_text' || question.type === 'long_text') { this.value('[data-survey-placeholder]', question.placeholder ?? ''); this.value('[data-survey-max-length]', String(question.maxLength ?? 10000)); }\n      if (question.type === 'rating') { this.value('[data-survey-rating-min]', String(question.min)); this.value('[data-survey-rating-max]', String(question.max)); }\n      const block = composer?.getSelectedBlock(); if (block?.type === 'question') { this.value('[data-survey-font-size]', String(block.fontSize)); this.value('[data-survey-question-color]', block.color ?? '#111827'); }\n    }\n    const select = this.root.querySelector<HTMLSelectElement>('[data-survey-default-next]')!;\n    const choices = this.destinations(); const markup = '<option value=\"\">Next in order</option>' + choices;\n    if (select.innerHTML !== markup) select.innerHTML = markup;\n    this.value('[data-survey-default-next]', step.branching?.defaultNextStepId ?? '');\n    const rules = this.root.querySelector<HTMLElement>('[data-survey-rules]')!;\n    const signature = JSON.stringify([step.id, step.questions, step.branching, this.survey.steps.map(step => [step.id, step.content.heading])]);\n    if (rules.dataset.signature !== signature) { rules.dataset.signature = signature; rules.innerHTML = (step.branching?.rules ?? []).map((rule, index) => this.ruleMarkup(rule, index)).join(''); }\n    this.root.querySelector<HTMLButtonElement>('[data-survey-add-rule]')!.disabled = !step.questions.length || (step.branching?.rules.length ?? 0) >= 10;\n  }\n\n  private destinations(): string {\n    return this.survey.steps.slice(this.options.index() + 1).map((step, offset) => `<option value=\"${escape(step.id)}\">${this.options.index() + offset + 2}. ${escape(step.content.heading || 'Survey step')}</option>`).join('') + '<option value=\"submit\">Submit Survey</option>';\n  }\n  private ruleMarkup(rule: SurveyBranchRule, index: number): string {\n    const questions = this.survey.steps[this.options.index()].questions, question = questions.find(question => question.id === rule.questionId)!;\n    const operators = question?.type === 'multiple_choice' ? [['includes', 'includes'], ['answered', 'has an answer']] : question?.type === 'rating' || question?.type === 'nps' ? [['equals', 'equals'], ['not_equals', 'does not equal'], ['gte', 'is at least'], ['lte', 'is at most'], ['answered', 'has an answer']] : [['equals', 'equals'], ['not_equals', 'does not equal'], ['answered', 'has an answer']];\n    const value = rule.operator === 'answered' ? '' : question && 'options' in question ? `<label>Answer<select data-rule-value>${question.options.map(option => `<option value=\"${escape(option.id)}\"${rule.value === option.id ? ' selected' : ''}>${escape(option.label)}</option>`).join('')}</select></label>` : `<label>Answer<input data-rule-value value=\"${escape(String(rule.value ?? ''))}\"${question?.type === 'rating' || question?.type === 'nps' ? ' type=\"number\"' : ''}></label>`;\n    return `<div data-survey-rule=\"${index}\"><label>Question<select data-rule-question>${questions.map(question => `<option value=\"${escape(question.id)}\"${question.id === rule.questionId ? ' selected' : ''}>${escape(question.label)}</option>`).join('')}</select></label><label>Condition<select data-rule-operator>${operators.map(([key, label]) => `<option value=\"${key}\"${key === rule.operator ? ' selected' : ''}>${label}</option>`).join('')}</select></label>${value}<label>Go to<select data-rule-next>${this.destinations().replace(`value=\"${escape(rule.nextStepId)}\"`, `value=\"${escape(rule.nextStepId)}\" selected`)}</select></label><button class=\"secondary-button compact\" type=\"button\" data-survey-remove-rule=\"${index}\">Remove rule</button></div>`;\n  }\n\n  private onChange = (event: Event): void => {\n    const input = event.target as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;\n    if (!input.dataset || !this.options.canEdit()) return;\n    const composer = this.options.composer(), step = this.survey.steps[this.options.index()], question = composer?.getSelectedQuestion();\n    if (input.matches('[data-survey-default-next],[data-rule-question],[data-rule-operator],[data-rule-value],[data-rule-next]')) {\n      const branching = cloneOnsite(step.branching ?? { rules: [] });\n      if (input.matches('[data-survey-default-next]')) branching.defaultNextStepId = input.value || undefined;\n      else {\n        const index = Number(input.closest<HTMLElement>('[data-survey-rule]')!.dataset.surveyRule), rule = branching.rules[index];\n        if (input.matches('[data-rule-question]')) Object.assign(rule, this.defaultRule(step.questions.find(question => question.id === input.value)!));\n        if (input.matches('[data-rule-operator]')) { rule.operator = input.value as SurveyBranchRule['operator']; if (rule.operator === 'answered') delete rule.value; else if (rule.value === undefined) rule.value = this.defaultRule(step.questions.find(question => question.id === rule.questionId)!).value; }\n        if (input.matches('[data-rule-next]')) rule.nextStepId = input.value;\n        if (input.matches('[data-rule-value]')) { const question = step.questions.find(question => question.id === rule.questionId)!; rule.value = question.type === 'rating' || question.type === 'nps' ? Number(input.value) : input.value; }\n      }\n      composer?.updateBranching(branching); this.sync(); return;\n    }\n    if (input.matches('[data-survey-allow-back],[data-survey-show-progress],[data-survey-submit-label]')) {\n      if (!this.options.flush()) return;\n      if (input.matches('[data-survey-submit-label]') && !input.value.trim()) { this.options.error(['Submit label cannot be empty.']); return; }\n      this.survey.allowBack = this.root.querySelector<HTMLInputElement>('[data-survey-allow-back]')!.checked;\n      this.survey.showProgress = this.root.querySelector<HTMLInputElement>('[data-survey-show-progress]')!.checked;\n      this.survey.submitLabel = this.root.querySelector<HTMLInputElement>('[data-survey-submit-label]')!.value.trim();\n      this.recompile(); composer?.refreshSurvey(); this.options.changed(); return;\n    }\n    if (input.matches('[data-survey-step-heading]')) { composer?.updateStepHeading(input.value); this.sync(); return; }\n    if (!question || !composer || !this.questionHost.contains(input)) return;\n    if (input.matches('[data-survey-font-size]')) { composer.updateBlock({ fontSize: Number(input.value) }); return; }\n    if (input.matches('[data-survey-question-color]')) { composer.updateBlock({ color: input.value }); return; }\n    const next = cloneOnsite(question);\n    // Type changes replace the union object, so no stale options/ranges survive.\n    const value = input.matches('[data-survey-question-type]') ? { ...newSurveyQuestion(input.value as SurveyQuestion['type']), id: question.id, label: question.label, required: question.required } : next;\n    if (input.matches('[data-survey-question-label]')) value.label = input.value;\n    if (input.matches('[data-survey-question-required]')) value.required = (input as HTMLInputElement).checked;\n    if ('options' in value && input.matches('[data-survey-options]')) { const existing = value.options; value.options = input.value.split('\\n').map((label, index) => ({ id: existing[index]?.id ?? onsiteId('option'), label })); }\n    if (value.type === 'short_text' || value.type === 'long_text') { if (input.matches('[data-survey-placeholder]')) value.placeholder = input.value; if (input.matches('[data-survey-max-length]')) value.maxLength = Number(input.value); }\n    if (value.type === 'rating') { if (input.matches('[data-survey-rating-min]')) value.min = Number(input.value); if (input.matches('[data-survey-rating-max]')) value.max = Number(input.value); }\n    composer.updateQuestion(value); this.sync();\n  };\n\n  private onClick = (event: Event): void => {\n    const target = event.target instanceof Element ? event.target.closest<HTMLButtonElement>('button') : null;\n    if (!target || !this.options.canEdit()) return;\n    const step = this.survey.steps[this.options.index()], composer = this.options.composer();\n    if (target.matches('[data-survey-add-rule]')) { if (!step.questions.length) return; composer?.updateBranching({ ...step.branching, rules: [...(step.branching?.rules ?? []), this.defaultRule(step.questions[0])] }); this.sync(); return; }\n    if (target.matches('[data-survey-remove-rule]')) { composer?.updateBranching({ ...step.branching, rules: step.branching!.rules.filter((_, index) => index !== Number(target.dataset.surveyRemoveRule)) }); this.sync(); return; }\n    if (!this.dock.contains(target) || !this.options.flush()) return;\n    let index = this.options.index(); const steps = cloneOnsite(this.survey.steps);\n    if (target.matches('[data-survey-add-step]')) { if (steps.length >= 20) return; steps.push(newSurveyStep(this.survey.submitLabel)); index = steps.length - 1; }\n    if (target.matches('[data-survey-duplicate-step]')) { if (steps.length >= 20) return; steps.splice(index + 1, 0, duplicateSurveyStep(steps[index], this.survey.submitLabel)); index++; }\n    if (target.matches('[data-survey-move]')) { const next = index + Number(target.dataset.surveyMove); if (next < 0 || next >= steps.length) return; [steps[index], steps[next]] = [steps[next], steps[index]]; index = next; }\n    if (target.matches('[data-survey-delete-step]')) {\n      if (steps.length === 1) return;\n      const removed = steps.splice(index, 1)[0].id; index = Math.min(index, steps.length - 1);\n      steps.forEach(step => { if (step.branching) { step.branching.rules = step.branching.rules.filter(rule => rule.nextStepId !== removed); if (step.branching.defaultNextStepId === removed) delete step.branching.defaultNextStepId; } });\n    }\n    const errors = surveyBranchErrors({ ...this.survey, steps }); if (errors.length) { this.options.error(errors); return; }\n    this.survey.steps = steps; this.dock.querySelector('details')!.open = false; this.options.stepsChanged(index);\n  };\n\n  private defaultRule(question: SurveyQuestion): SurveyBranchRule {\n    return { questionId: question.id, operator: question.type === 'multiple_choice' ? 'includes' : 'equals', value: 'options' in question ? question.options[0].id : question.type === 'rating' ? question.min : question.type === 'nps' ? 0 : '', nextStepId: this.survey.steps[this.options.index() + 1]?.id ?? 'submit' };\n  }\n  private recompile(): void { this.survey.steps.forEach(step => { const doc = onsiteDocumentFromBuilder(step.builder); if (doc && step.builder) Object.assign(step.content, applyOnsiteDocument(step.builder, doc, 'survey', { questions: step.questions, submitLabel: this.survey.submitLabel }).content); }); }\n  private value(selector: string, value: string): void { const input = this.root.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(selector); if (input && this.root.activeElement !== input) input.value = value; }\n  private check(selector: string, value: boolean): void { const input = this.root.querySelector<HTMLInputElement>(selector); if (input) input.checked = value; }\n  destroy(): void { this.root.removeEventListener('change', this.onChange); this.root.removeEventListener('click', this.onClick); this.questionHost.remove(); this.stepHost.remove(); this.dock.remove(); this.style.remove(); }\n}\n\nfunction escape(value: string): string { return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }\n","import type { EditorAuthoringState, EditorContinuation, EditorSession } from \"./runtimeInterfaces\";\n\nexport const EDITOR_CONTINUATION_KEY = \"__movcues_experience_editor_session__\";\n\nexport function readEditorContinuation(): EditorContinuation | null {\n  try {\n    const value = JSON.parse(sessionStorage.getItem(EDITOR_CONTINUATION_KEY) ?? \"null\") as Partial<EditorContinuation & EditorSession> | null;\n    const session = value && isSession(value.session) ? value.session : isSession(value) ? value : null;\n    if (!session || Date.parse(session.expiresAt) <= Date.now()) {\n      clearEditorContinuation();\n      return null;\n    }\n    return { session, editorState: isEditorState(value?.editorState) ? value.editorState : undefined };\n  } catch {\n    clearEditorContinuation();\n    return null;\n  }\n}\n\nexport function storeEditorContinuation(continuation: EditorContinuation): void {\n  try { sessionStorage.setItem(EDITOR_CONTINUATION_KEY, JSON.stringify(continuation)); } catch { /* continuation is best effort */ }\n}\n\nexport function clearEditorContinuation(): void {\n  try { sessionStorage.removeItem(EDITOR_CONTINUATION_KEY); } catch { /* storage may be unavailable */ }\n}\n\nfunction isSession(value: unknown): value is EditorSession {\n  if (!value || typeof value !== \"object\") return false;\n  const session = value as Partial<EditorSession>;\n  return typeof session.sessionId === \"string\" && !!session.sessionId && typeof session.accessToken === \"string\" && !!session.accessToken && typeof session.expiresAt === \"string\" && Number.isFinite(Date.parse(session.expiresAt));\n}\n\nfunction isEditorState(value: unknown): value is EditorAuthoringState {\n  if (!value || typeof value !== \"object\") return false;\n  const state = value as Partial<EditorAuthoringState>;\n  return typeof state.experienceId === \"string\" && !!state.experienceId && (state.selectedStepId === undefined || typeof state.selectedStepId === \"string\") && (state.mode === \"select\" || state.mode === \"design\" || state.mode === \"target\" || state.mode === \"navigate\" || state.mode === \"preview\");\n}\n","type RouteChangeListener = (url: string) => void;\n\n/**\n * Detects client-side route changes across all common SPA routing\n * strategies (pushState/replaceState, popstate, hashchange) without any\n * framework-specific adapter. History patching is done carefully: we wrap\n * the existing methods and always call through to the original\n * implementation so the host app's routing is never broken.\n */\nexport class RouteObserver {\n  private listeners = new Set<RouteChangeListener>();\n  private lastUrl = location.href;\n  private installed = false;\n  private originalPushState = history.pushState;\n  private originalReplaceState = history.replaceState;\n  private onPopState = () => this.checkForChange();\n  private onHashChange = () => this.checkForChange();\n\n  start(): void {\n    if (this.installed) return;\n    this.installed = true;\n\n    const self = this;\n\n    history.pushState = function (this: History, ...args: Parameters<History[\"pushState\"]>) {\n      const result = self.originalPushState.apply(this, args);\n      self.checkForChange();\n      return result;\n    };\n\n    history.replaceState = function (this: History, ...args: Parameters<History[\"replaceState\"]>) {\n      const result = self.originalReplaceState.apply(this, args);\n      self.checkForChange();\n      return result;\n    };\n\n    window.addEventListener(\"popstate\", this.onPopState);\n    window.addEventListener(\"hashchange\", this.onHashChange);\n  }\n\n  stop(): void {\n    if (!this.installed) return;\n    this.installed = false;\n    history.pushState = this.originalPushState;\n    history.replaceState = this.originalReplaceState;\n    window.removeEventListener(\"popstate\", this.onPopState);\n    window.removeEventListener(\"hashchange\", this.onHashChange);\n  }\n\n  onChange(fn: RouteChangeListener): () => void {\n    this.listeners.add(fn);\n    return () => this.listeners.delete(fn);\n  }\n\n  private checkForChange(): void {\n    // Defer a tick so frameworks that update the DOM asynchronously after a\n    // route change (React Router, Next.js, Vue Router, etc.) have a chance\n    // to settle before we snapshot page context.\n    setTimeout(() => {\n      const url = location.href;\n      if (url !== this.lastUrl) {\n        this.lastUrl = url;\n        for (const fn of this.listeners) {\n          try {\n            fn(url);\n          } catch {\n            /* isolate listener failures */\n          }\n        }\n      }\n    }, 0);\n  }\n}\n","import type { ExperienceDesign, ExperienceSize, WidgetType } from \"../types\";\n\ninterface WidgetSizeConstraint {\n  width: { default: number | \"full\"; min?: number; max?: number; allowFull?: boolean };\n  height: { allowFixed?: boolean; allowViewport?: boolean; min?: number; max?: number };\n  viewportGutter: number;\n}\n\nexport const WIDGET_SIZE_CONSTRAINTS: Record<WidgetType, WidgetSizeConstraint> = {\n  anchored_card: { width: { default: 320, min: 240, max: 480 }, height: { allowFixed: true, min: 120, max: 700 }, viewportGutter: 24 },\n  toast: { width: { default: 380, min: 280, max: 520 }, height: {}, viewportGutter: 24 },\n  cursor_follow: { width: { default: 280, min: 200, max: 360 }, height: {}, viewportGutter: 24 },\n  modal: { width: { default: 600, min: 320, max: 960, allowFull: true }, height: { allowFixed: true, allowViewport: true, min: 200, max: 900 }, viewportGutter: 24 },\n  slideout: { width: { default: 400, min: 320, max: 640 }, height: { allowFixed: true, allowViewport: true, min: 240, max: 900 }, viewportGutter: 24 },\n  hotspot: { width: { default: 300, min: 220, max: 420 }, height: {}, viewportGutter: 24 },\n  banner: { width: { default: \"full\" }, height: {}, viewportGutter: 0 },\n  survey: { width: { default: 700, min: 320, max: 960, allowFull: true }, height: { allowFixed: true, allowViewport: true, min: 200, max: 900 }, viewportGutter: 24 },\n};\n\nexport function normalizeWidgetSize(widgetType: WidgetType, design: ExperienceDesign): ExperienceSize {\n  const constraint = WIDGET_SIZE_CONSTRAINTS[widgetType];\n  if (widgetType === \"banner\") return { width: { mode: \"full\" }, height: { mode: \"auto\" } };\n  const legacyValue = design.width === \"sm\" ? constraint.width.min! : design.width === \"lg\" ? constraint.width.max! : constraint.width.default as number;\n  const requestedWidth = design.size?.width;\n  const width = requestedWidth?.mode === \"full\" && constraint.width.allowFull\n    ? { mode: \"full\" as const }\n    : { mode: \"fixed\" as const, value: clamp(requestedWidth?.value ?? legacyValue, constraint.width.min!, constraint.width.max!) };\n  const requestedHeight = design.size?.height;\n  const height = requestedHeight?.mode === \"fixed\" && constraint.height.allowFixed\n    ? { mode: \"fixed\" as const, value: clamp(requestedHeight.value ?? constraint.height.min!, constraint.height.min!, constraint.height.max!) }\n    : requestedHeight?.mode === \"viewport\" && constraint.height.allowViewport ? { mode: \"viewport\" as const } : { mode: \"auto\" as const };\n  return { width, height };\n}\n\nexport function applyWidgetSizeEnvelope(card: HTMLElement, widgetType: WidgetType, design: ExperienceDesign): void {\n  const constraint = WIDGET_SIZE_CONSTRAINTS[widgetType]; const size = normalizeWidgetSize(widgetType, design); const gutter = Math.max(24, constraint.viewportGutter);\n  card.dataset.sizeWidth = size.width.mode; card.dataset.sizeHeight = size.height.mode;\n  if (size.width.mode === \"full\") {\n    card.style.width = widgetType === \"banner\" ? \"100%\" : `calc(100vw - ${gutter}px)`;\n    card.style.minWidth = \"0\"; card.style.maxWidth = \"none\";\n  } else {\n    card.style.width = `${size.width.value}px`;\n    card.style.minWidth = `min(${constraint.width.min}px, calc(100vw - ${gutter}px))`;\n    card.style.maxWidth = `min(${constraint.width.max}px, calc(100vw - ${gutter}px))`;\n  }\n  card.style.height = size.height.mode === \"fixed\" ? `${size.height.value}px` : size.height.mode === \"viewport\" ? `calc(100vh - ${gutter}px)` : \"auto\";\n  card.style.maxHeight = `calc(100vh - ${gutter}px)`;\n  // Builder widgets manage their own internal overflow. Keeping this outer\n  // placement card visible prevents it from cutting off authored shadows and\n  // other deliberate visual overflow at the card's exact size boundary.\n  card.style.overflow = \"visible\";\n}\n\nexport function applyBuilderSizeContent(card: HTMLElement, widgetType: WidgetType, design: ExperienceDesign): void {\n  const content = card.querySelector<HTMLElement>(\".builder-content\"); const widget = content?.querySelector<HTMLElement>(\":scope > .movcues-widget\");\n  if (!content || !widget) return;\n  const size = normalizeWidgetSize(widgetType, design); const fillsHeight = size.height.mode !== \"auto\";\n  content.style.width = \"100%\"; content.style.height = fillsHeight ? \"100%\" : \"auto\";\n  widget.style.setProperty(\"box-sizing\", \"border-box\");\n  // Saved builder CSS owns the visual width for every widget type. The card\n  // supplies only the bounded positioning envelope; forcing a child width of\n  // 100% here expands authored compact cards, toasts, and slideouts to their\n  // generic runtime defaults. Keep content inside that envelope without\n  // replacing an authored width.\n  widget.style.setProperty(\"min-width\", \"0\", \"important\"); widget.style.setProperty(\"max-width\", \"100%\", \"important\");\n  widget.style.setProperty(\"height\", fillsHeight ? \"100%\" : \"auto\", \"important\"); widget.style.setProperty(\"max-height\", fillsHeight ? \"100%\" : \"none\", \"important\");\n}\n\nfunction clamp(value: number, min: number, max: number): number { return Math.min(max, Math.max(min, Number.isFinite(value) ? Math.round(value) : min)); }\n","import type { ExperienceBehavior, ExperienceDesign } from \"../types\";\n\nconst PANEL_NAMES = [\"top\", \"right\", \"bottom\", \"left\"] as const;\nconst SCROLL_KEYS = new Set([\"ArrowDown\", \"ArrowLeft\", \"ArrowRight\", \"ArrowUp\", \"End\", \"Home\", \"PageDown\", \"PageUp\", \" \"]);\n\nlet scrollLockCount = 0;\nlet scrollLockCleanup: (() => void) | null = null;\n\n/**\n * Dims the viewport around an anchored target without changing the target or\n * the page DOM. Geometry is supplied by AnchoredCardRenderer so the backdrop\n * shares its coalesced positioning lifecycle.\n */\nexport class AnchoredTargetBackdrop {\n  private panels: HTMLElement[] = [];\n  private highlight: HTMLElement;\n  private releaseScrollLock: (() => void) | null;\n\n  constructor(root: ShadowRoot, card: HTMLElement, behavior: ExperienceBehavior, design: ExperienceDesign, onDismiss: () => void) {\n    this.releaseScrollLock = lockDocumentScroll();\n    const opacity = finiteClamp(behavior.backdropOpacity ?? 0.45, 0, 1);\n    this.panels = PANEL_NAMES.map(name => {\n      const panel = document.createElement(\"div\");\n      panel.dataset.movcuesTargetBackdrop = name;\n      panel.style.cssText = `position:fixed;box-sizing:border-box;background:rgba(0,0,0,${opacity});pointer-events:auto`;\n      if (behavior.closeOnBackdrop && behavior.dismissible) panel.addEventListener(\"click\", onDismiss);\n      root.insertBefore(panel, card);\n      return panel;\n    });\n    this.highlight = document.createElement(\"div\");\n    this.highlight.dataset.movcuesTargetHighlight = \"\";\n    this.highlight.style.cssText = \"position:fixed;box-sizing:border-box;border-radius:4px;pointer-events:none\";\n    this.highlight.style.outline = `2px solid ${design.theme.primary}`;\n    root.insertBefore(this.highlight, card);\n  }\n\n  update(rect: DOMRect): void {\n    const viewportWidth = Math.max(0, innerWidth);\n    const viewportHeight = Math.max(0, innerHeight);\n    const left = finiteClamp(rect.left, 0, viewportWidth);\n    const right = finiteClamp(rect.right, 0, viewportWidth);\n    const top = finiteClamp(rect.top, 0, viewportHeight);\n    const bottom = finiteClamp(rect.bottom, 0, viewportHeight);\n    const middleHeight = Math.max(0, bottom - top);\n\n    setRect(this.panels[0], 0, 0, viewportWidth, top);\n    setRect(this.panels[1], right, top, Math.max(0, viewportWidth - right), middleHeight);\n    setRect(this.panels[2], 0, bottom, viewportWidth, Math.max(0, viewportHeight - bottom));\n    setRect(this.panels[3], 0, top, left, middleHeight);\n    setRect(this.highlight, rect.left, rect.top, Math.max(0, rect.width), Math.max(0, rect.height));\n  }\n\n  setHidden(hidden: boolean): void {\n    if (hidden) { this.releaseScrollLock?.(); this.releaseScrollLock = null; }\n    else if (!this.releaseScrollLock) this.releaseScrollLock = lockDocumentScroll();\n    const visibility = hidden ? \"hidden\" : \"\";\n    this.panels.forEach(panel => { panel.style.visibility = visibility; });\n    this.highlight.style.visibility = visibility;\n  }\n\n  destroy(): void {\n    this.releaseScrollLock?.(); this.releaseScrollLock = null;\n    this.panels.forEach(panel => panel.remove());\n    this.panels = [];\n    this.highlight.remove();\n  }\n}\n\nfunction lockDocumentScroll(): () => void {\n  scrollLockCount += 1;\n  if (scrollLockCount === 1) {\n    const rootStyle = captureProperty(document.documentElement.style, \"overflow\");\n    const bodyStyle = document.body ? captureProperty(document.body.style, \"overflow\") : null;\n    document.documentElement.style.setProperty(\"overflow\", \"hidden\", \"important\");\n    document.body?.style.setProperty(\"overflow\", \"hidden\", \"important\");\n    const preventScroll = (event: Event) => {\n      // The document stays locked, but scrollable controls and widget content\n      // must remain usable (including controls inside a shadow root).\n      const delta = event instanceof WheelEvent ? event.deltaY : 0;\n      if (event.composedPath().some(node => node instanceof HTMLElement && node !== document.body && node !== document.documentElement &&\n        /auto|scroll/.test(getComputedStyle(node).overflowY) && node.scrollHeight > node.clientHeight &&\n        (!delta || (delta > 0 ? node.scrollTop + node.clientHeight < node.scrollHeight : node.scrollTop > 0)))) return;\n      if (event.cancelable) event.preventDefault();\n    };\n    const preventScrollKey = (event: KeyboardEvent) => {\n      if (!SCROLL_KEYS.has(event.key) || event.composedPath().some(isEditableControl)) return;\n      if (event.cancelable) event.preventDefault();\n    };\n    document.addEventListener(\"wheel\", preventScroll, { capture: true, passive: false });\n    document.addEventListener(\"touchmove\", preventScroll, { capture: true, passive: false });\n    document.addEventListener(\"keydown\", preventScrollKey, true);\n    scrollLockCleanup = () => {\n      document.removeEventListener(\"wheel\", preventScroll, true);\n      document.removeEventListener(\"touchmove\", preventScroll, true);\n      document.removeEventListener(\"keydown\", preventScrollKey, true);\n      restoreProperty(document.documentElement.style, \"overflow\", rootStyle);\n      if (bodyStyle && document.body) restoreProperty(document.body.style, \"overflow\", bodyStyle);\n    };\n  }\n  let released = false;\n  return () => {\n    if (released) return;\n    released = true;\n    scrollLockCount = Math.max(0, scrollLockCount - 1);\n    if (scrollLockCount === 0) { scrollLockCleanup?.(); scrollLockCleanup = null; }\n  };\n}\n\nfunction isEditableControl(target: EventTarget | null): boolean {\n  return target instanceof Element && Boolean(target.closest(\"input,textarea,select,button,[contenteditable]:not([contenteditable='false'])\"));\n}\n\ninterface CapturedProperty { value: string; priority: string }\n\nfunction captureProperty(style: CSSStyleDeclaration, property: string): CapturedProperty {\n  return { value: style.getPropertyValue(property), priority: style.getPropertyPriority(property) };\n}\n\nfunction restoreProperty(style: CSSStyleDeclaration, property: string, captured: CapturedProperty): void {\n  if (captured.value) style.setProperty(property, captured.value, captured.priority);\n  else style.removeProperty(property);\n}\n\nfunction setRect(element: HTMLElement, left: number, top: number, width: number, height: number): void {\n  element.style.left = `${left}px`;\n  element.style.top = `${top}px`;\n  element.style.width = `${width}px`;\n  element.style.height = `${height}px`;\n}\n\nfunction finiteClamp(value: number, minimum: number, maximum: number): number {\n  return Number.isFinite(value) ? Math.max(minimum, Math.min(value, maximum)) : minimum;\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, ExperienceTarget, WidgetBuilderState, WidgetType } from \"../types\";\nimport { mountBuilderContent } from \"./BuilderContent\";\nimport { applyBuilderSizeContent, applyWidgetSizeEnvelope } from \"./WidgetSizing\";\nimport { AnchoredTargetBackdrop } from \"./AnchoredTargetBackdrop\";\n\nexport interface RenderCallbacks { onDismiss: () => void; onPrimary: () => void; onSecondary: () => void; onBack?: () => void }\n\nexport function findTarget(target?: ExperienceTarget): Element | null {\n  if (!target) return null;\n  for (const selector of [target.primarySelector, ...target.fallbackSelectors]) {\n    try { const matches = document.querySelectorAll(selector); if (matches.length === 1) return matches[0]; } catch { /* invalid selector cannot break host */ }\n  }\n  return null;\n}\n\n/** Resolves a selector that may be rendered after the experience manifest arrives. */\nexport function waitForTarget(target: ExperienceTarget | undefined, onFound: (element: Element) => void, onUnavailable: () => void, timeoutMs = 5000): () => void {\n  const immediate = findTarget(target); if (immediate) { onFound(immediate); return () => void 0; }\n  let stopped = false; let observer: MutationObserver | null = null; let timer = 0; let frameId: number | null = null;\n  const stop = () => {\n    if (stopped) return;\n    stopped = true; observer?.disconnect(); clearTimeout(timer);\n    if (frameId !== null) cancelAnimationFrame(frameId);\n    frameId = null;\n  };\n  const check = () => { if (stopped) return; const element = findTarget(target); if (element) { stop(); onFound(element); } };\n  const scheduleCheck = () => {\n    if (stopped || frameId !== null) return;\n    frameId = requestAnimationFrame(() => { frameId = null; check(); });\n  };\n  if (typeof MutationObserver === \"undefined\" || !document.documentElement) { timer = window.setTimeout(() => { stop(); onUnavailable(); }, timeoutMs); return stop; }\n  observer = new MutationObserver(scheduleCheck); observer.observe(document.documentElement, { childList: true, subtree: true }); timer = window.setTimeout(() => { if (!stopped) { stop(); onUnavailable(); } }, timeoutMs);\n  return stop;\n}\n\nexport function buildCard(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState, widgetType?: WidgetType): HTMLElement {\n  const card = document.createElement(\"section\");\n  card.className = \"card\";\n  card.style.setProperty(\"--movcues-bg\", design.theme.background);\n  card.style.setProperty(\"--movcues-fg\", design.theme.foreground);\n  card.style.setProperty(\"--movcues-primary\", design.theme.primary);\n  if (design.theme.spacing !== undefined) card.style.setProperty(\"--movcues-theme-spacing\", `${design.theme.spacing}px`);\n  const theme = design.theme.siteTheme;\n  if (theme) {\n    card.style.setProperty(\"--movcues-surface\", theme.colors.surface);\n    card.style.setProperty(\"--movcues-muted\", theme.colors.mutedText);\n    card.style.setProperty(\"--movcues-border\", theme.colors.border);\n    card.style.setProperty(\"--movcues-primary-fg\", theme.colors.primaryForeground);\n    card.style.setProperty(\"--movcues-font-body\", theme.typography.bodyFontFamily);\n    card.style.setProperty(\"--movcues-font-heading\", theme.typography.headingFontFamily);\n    card.style.setProperty(\"--movcues-font-body-size\", `${theme.typography.bodyFontSize}px`);\n    card.style.setProperty(\"--movcues-font-heading-size\", `${theme.typography.headingFontSize}px`);\n    card.style.setProperty(\"--movcues-theme-radius\", `${theme.radii.lg}px`);\n    card.style.setProperty(\"--movcues-button-radius\", `${theme.radii.md}px`);\n    const shadow = theme.shadows.md;\n    card.style.setProperty(\"--movcues-theme-shadow\", `${shadow.x}px ${shadow.y}px ${shadow.blur}px ${shadow.spread}px ${shadow.color}`);\n  }\n  card.dataset.width = design.width; card.dataset.radius = design.theme.borderRadius;\n  if (widgetType) applyWidgetSizeEnvelope(card, widgetType, design);\n  const mountedBuilder = Boolean(builder && mountBuilderContent(root, card, builder, callbacks, widgetType === \"survey\"));\n  if (mountedBuilder && widgetType) applyBuilderSizeContent(card, widgetType, design);\n  if (!mountedBuilder) {\n    const primary = content.primaryAction ? `<button class=\"primary\" data-primary>${escapeText(content.primaryAction.label)}</button>` : \"\";\n    const secondary = content.secondaryAction ? `<button class=\"secondary\" data-secondary>${escapeText(content.secondaryAction.label)}</button>` : \"\";\n    card.insertAdjacentHTML(\"beforeend\", `<div class=\"legacy-content\"><h2>${escapeText(content.heading)}</h2><p>${escapeText(content.body)}</p><footer>${secondary}${primary}</footer></div>`);\n    card.querySelector(\"[data-primary]\")?.addEventListener(\"click\", callbacks.onPrimary);\n    card.querySelector(\"[data-secondary]\")?.addEventListener(\"click\", callbacks.onSecondary);\n  }\n  if (behavior.dismissible) mountRuntimeDismissControl(card, callbacks.onDismiss);\n  root.appendChild(card);\n  if (mountedBuilder && widgetType) fitBuilderWidthEnvelope(card);\n  if (mountedBuilder && widgetType === \"anchored_card\") fitAnchoredBuilderEnvelope(card);\n  return card;\n}\n\n/**\n * Runtime controls are deliberately kept outside the authored builder surface.\n * The nested shadow root means saved CSS remains authoritative for saved\n * content, while it cannot accidentally turn a dismiss control into part of an\n * authored flex or grid layout.\n */\nfunction mountRuntimeDismissControl(card: HTMLElement, onDismiss: () => void): void {\n  const chrome = document.createElement(\"div\");\n  chrome.className = \"movcues-runtime-chrome\";\n  chrome.dataset.movcuesRuntimeChrome = \"dismiss\";\n  chrome.style.setProperty(\"position\", \"absolute\", \"important\");\n  chrome.style.setProperty(\"inset\", \"0\", \"important\");\n  chrome.style.setProperty(\"z-index\", \"2\", \"important\");\n  chrome.style.setProperty(\"pointer-events\", \"none\", \"important\");\n  const chromeRoot = chrome.attachShadow({ mode: \"open\" });\n  const style = document.createElement(\"style\");\n  style.textContent = `:host{all:initial;color:inherit}button{position:absolute;top:7px;right:8px;display:block;box-sizing:border-box;flex:none;margin:0;border:0;border-radius:7px;padding:3px 7px;background:transparent;color:inherit;font:20px/1 ui-sans-serif,system-ui,sans-serif;cursor:pointer;pointer-events:auto}`;\n  const close = document.createElement(\"button\");\n  close.type = \"button\";\n  close.className = \"movcues-runtime-close\";\n  close.dataset.dismiss = \"\";\n  close.setAttribute(\"aria-label\", \"Dismiss\");\n  close.textContent = \"Ã—\";\n  close.addEventListener(\"click\", onDismiss);\n  chromeRoot.append(style, close);\n  card.appendChild(chrome);\n}\n\n/**\n * Old mixed-guide drafts can contain a modal-sized guide envelope around a\n * narrower authored anchored card. Placement and the runtime close button use\n * the envelope, so collapse only a genuinely oversized envelope to its visual\n * root before calculating target-relative coordinates.\n */\nfunction fitAnchoredBuilderEnvelope(card: HTMLElement): void {\n  const widget = card.querySelector<HTMLElement>(\".builder-content > .movcues-widget\");\n  if (!widget) return;\n  const cardRect = card.getBoundingClientRect(); const widgetRect = widget.getBoundingClientRect();\n  if (widgetRect.width > 0 && cardRect.width - widgetRect.width > 0.5) card.style.width = `${Math.ceil(widgetRect.width)}px`;\n  if (widgetRect.height > 0 && cardRect.height - widgetRect.height > 0.5) card.style.height = `${Math.ceil(widgetRect.height)}px`;\n}\n\n/**\n * The outer card is only a positioning envelope. Once saved CSS establishes\n * the visual root width, collapse the shell to it so card positioning and\n * runtime chrome exactly follow the authored widget.\n */\nfunction fitBuilderWidthEnvelope(card: HTMLElement): void {\n  const widget = card.querySelector<HTMLElement>(\".builder-content > .movcues-widget\");\n  if (!widget) return;\n  const widgetRect = widget.getBoundingClientRect();\n  if (widgetRect.width <= 0) return;\n  card.style.width = `${Math.ceil(widgetRect.width)}px`;\n  card.style.minWidth = \"0\";\n}\n\nexport class AnchoredCardRenderer {\n  private cleanup: Array<() => void> = [];\n  render(root: ShadowRoot, target: Element, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState, widgetType?: WidgetType): HTMLElement {\n    this.destroy();\n    const card = buildCard(root, content, design, behavior, callbacks, builder, widgetType);\n    const pointer = behavior.pointer?.enabled === false ? null : buildPointer(card, design, behavior);\n    const backdrop = behavior.backdrop ? new AnchoredTargetBackdrop(root, card, behavior, design, callbacks.onDismiss) : null;\n    let frameId: number | null = null;\n    let destroyed = false;\n    let hidden = false;\n    let resolvedPlacement: ResolvedPlacement | null = null;\n    let cardSize: Size | null = null;\n    let measureCard = true;\n    let lastLeft: number | null = null;\n    let lastTop: number | null = null;\n    const setHidden = (next: boolean) => {\n      if (hidden === next) return;\n      hidden = next;\n      card.style.visibility = next ? \"hidden\" : \"\";\n      card.style.pointerEvents = next ? \"none\" : \"\";\n      backdrop?.setHidden(next);\n    };\n    const update = () => {\n      if (destroyed) return;\n      if (!target.isConnected) {\n        setHidden(true);\n        return;\n      }\n      const rect = target.getBoundingClientRect();\n      // A collapsed/hidden target has no usable spotlight or anchor rectangle.\n      if (rect.width <= 0 || rect.height <= 0) { setHidden(true); return; }\n      backdrop?.update(rect);\n      if (measureCard || !cardSize) {\n        const bounds = card.getBoundingClientRect();\n        cardSize = { width: bounds.width, height: bounds.height };\n        measureCard = false;\n      }\n      const bounds = cardSize;\n      if (!resolvedPlacement) resolvedPlacement = resolvePlacement(rect, bounds, behavior);\n      const coordinates = coordinatesFor(rect, bounds, behavior, resolvedPlacement);\n      const naturalCardRect = rectAt(coordinates.left, coordinates.top, bounds.width, bounds.height);\n      if (!intersectsViewport(rect) && !intersectsViewport(naturalCardRect)) { setHidden(true); return; }\n\n      setHidden(false);\n      const left = clampHorizontally(coordinates.left, bounds.width);\n      if (pointer) positionPointer(pointer, rect, bounds, left, coordinates.top, resolvedPlacement, behavior);\n      if (left !== lastLeft) { lastLeft = left; card.style.left = `${left}px`; }\n      if (coordinates.top !== lastTop) { lastTop = coordinates.top; card.style.top = `${coordinates.top}px`; }\n    };\n    const schedule = (reconsiderPlacement = false, remeasureCard = false) => {\n      if (destroyed) return;\n      if (reconsiderPlacement && isAutomaticPlacement(behavior)) resolvedPlacement = null;\n      if (remeasureCard) measureCard = true;\n      if (frameId !== null) return;\n      frameId = requestAnimationFrame(() => { frameId = null; update(); });\n    };\n    const onScroll = (event: Event) => {\n      const scrollContainer = event.target;\n      if (target.isConnected && scrollContainer instanceof Element && !scrollContainer.contains(target)) return;\n      schedule();\n    };\n    const onResize = () => schedule(true, true);\n    window.addEventListener(\"scroll\", onScroll, { capture: true, passive: true });\n    window.addEventListener(\"resize\", onResize);\n    this.cleanup.push(\n      () => window.removeEventListener(\"scroll\", onScroll, true),\n      () => window.removeEventListener(\"resize\", onResize),\n      () => { destroyed = true; if (frameId !== null) cancelAnimationFrame(frameId); frameId = null; },\n      () => backdrop?.destroy(),\n    );\n    if (typeof ResizeObserver !== \"undefined\") {\n      const observer = new ResizeObserver((entries) => schedule(true, entries.some(entry => entry.target === card)));\n      observer.observe(target); observer.observe(card);\n      this.cleanup.push(() => observer.disconnect());\n    }\n    update(); return card;\n  }\n  destroy(): void { this.cleanup.splice(0).forEach((fn) => fn()); }\n}\n\nfunction buildPointer(card: HTMLElement, design: ExperienceDesign, behavior: ExperienceBehavior): HTMLElement {\n  const pointer = document.createElement(\"span\");\n  const size = pointerSize(behavior);\n  pointer.className = \"movcues-anchor-pointer\";\n  pointer.setAttribute(\"aria-hidden\", \"true\");\n  pointer.style.setProperty(\"--movcues-pointer-size\", `${size}px`);\n  pointer.style.color = pointerColor(card, design);\n  pointer.innerHTML = '<svg viewBox=\"0 0 10 10\" focusable=\"false\" aria-hidden=\"true\"><path d=\"M5 0 10 10H0Z\" fill=\"currentColor\"/></svg>';\n  card.prepend(pointer);\n  return pointer;\n}\n\nfunction pointerColor(card: HTMLElement, design: ExperienceDesign): string {\n  const widget = card.querySelector<HTMLElement>(\".movcues-widget\");\n  if (!widget) return design.theme.background;\n  const background = getComputedStyle(widget).backgroundColor.trim();\n  return isTransparent(background) ? design.theme.background : background;\n}\n\nfunction isTransparent(color: string): boolean {\n  return !color || color.toLowerCase() === \"transparent\" || /^rgba\\([^)]*,\\s*0(?:\\.0+)?\\s*\\)$/i.test(color);\n}\n\nfunction positionPointer(pointer: HTMLElement, targetRect: DOMRect, cardSize: Size, finalLeft: number, finalTop: number, placement: ResolvedPlacement, behavior: ExperienceBehavior): void {\n  const size = pointerSize(behavior);\n  const edgePadding = Math.max(size + 6, 14);\n  pointer.dataset.placement = placement;\n  if (placement === \"top\" || placement === \"bottom\") {\n    const center = clamp(targetRect.left + targetRect.width / 2 - finalLeft, edgePadding, cardSize.width - edgePadding);\n    pointer.style.left = `${center}px`;\n    pointer.style.top = \"\";\n  } else {\n    const center = clamp(targetRect.top + targetRect.height / 2 - finalTop, edgePadding, cardSize.height - edgePadding);\n    pointer.style.top = `${center}px`;\n    pointer.style.left = \"\";\n  }\n}\n\nfunction pointerSize(behavior: ExperienceBehavior): number {\n  const requested = behavior.pointer?.size ?? 10;\n  return Number.isFinite(requested) ? clamp(Math.round(requested), 4, 30) : 10;\n}\n\nfunction clamp(value: number, minimum: number, maximum: number): number {\n  if (maximum < minimum) return maximum / 2;\n  return Math.max(minimum, Math.min(value, maximum));\n}\n\ntype ResolvedPlacement = Exclude<NonNullable<ExperienceBehavior[\"placement\"]>, \"auto\">;\n\ninterface Size { width: number; height: number }\ninterface Coordinates { left: number; top: number }\n\nfunction isAutomaticPlacement(behavior: ExperienceBehavior): boolean {\n  return !behavior.placement || behavior.placement === \"auto\";\n}\n\nfunction resolvePlacement(rect: DOMRect, bounds: Size, behavior: ExperienceBehavior): ResolvedPlacement {\n  if (!isAutomaticPlacement(behavior)) return behavior.placement as ResolvedPlacement;\n  const gap = behavior.offset ?? 8;\n  const spaceBelow = innerHeight - rect.bottom - gap;\n  const spaceAbove = rect.top - gap;\n  if (spaceBelow >= bounds.height) return \"bottom\";\n  if (spaceAbove >= bounds.height) return \"top\";\n  return spaceBelow >= spaceAbove ? \"bottom\" : \"top\";\n}\n\nfunction coordinatesFor(rect: DOMRect, bounds: Size, behavior: ExperienceBehavior, placement: ResolvedPlacement): Coordinates {\n  const gap = behavior.offset ?? 8;\n  let left = rect.left + (rect.width - bounds.width) / 2; let top = rect.bottom + gap;\n  if (placement === \"top\") top = rect.top - bounds.height - gap;\n  if (placement === \"left\") { left = rect.left - bounds.width - gap; top = rect.top + (rect.height - bounds.height) / 2; }\n  if (placement === \"right\") { left = rect.right + gap; top = rect.top + (rect.height - bounds.height) / 2; }\n  if (behavior.alignment === \"start\" && (placement === \"top\" || placement === \"bottom\")) left = rect.left;\n  if (behavior.alignment === \"end\" && (placement === \"top\" || placement === \"bottom\")) left = rect.right - bounds.width;\n  return { left, top };\n}\n\nfunction clampHorizontally(left: number, width: number): number {\n  const margin = 8;\n  return Math.max(margin, Math.min(left, innerWidth - width - margin));\n}\n\nfunction rectAt(left: number, top: number, width: number, height: number): DOMRect {\n  return { x: left, y: top, left, top, width, height, right: left + width, bottom: top + height, toJSON: () => ({}) } as DOMRect;\n}\n\nfunction intersectsViewport(rect: DOMRect): boolean {\n  return rect.width > 0 && rect.height > 0 && rect.bottom > 0 && rect.right > 0 && rect.top < innerHeight && rect.left < innerWidth;\n}\n\nfunction escapeText(value: string): string { const span = document.createElement(\"span\"); span.textContent = value; return span.innerHTML; }\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { buildCard, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class ToastRenderer {\n  private timer: number | null = null;\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState): HTMLElement {\n    const card = buildCard(root, content, design, behavior, callbacks, builder, \"toast\"); card.classList.add(\"toast\"); card.dataset.position = behavior.toastPosition ?? \"bottom-right\";\n    if (behavior.autoDismissMs) this.timer = window.setTimeout(callbacks.onDismiss, behavior.autoDismissMs);\n    return card;\n  }\n  destroy(): void { if (this.timer !== null) clearTimeout(this.timer); }\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { buildCard, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class CursorFollowRenderer {\n  private cleanup: (() => void) | null = null;\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState): HTMLElement {\n    const card = buildCard(root, content, design, behavior, callbacks, builder, \"cursor_follow\"); card.classList.add(\"cursor\");\n    let frame = 0; let x = innerWidth / 2; let y = innerHeight / 2; const offset = behavior.cursorOffset ?? { x: 16, y: 16 };\n    const update = () => { frame = 0; const rect = card.getBoundingClientRect(); card.style.left = `${Math.max(8, Math.min(x + offset.x, innerWidth - rect.width - 8))}px`; card.style.top = `${Math.max(8, Math.min(y + offset.y, innerHeight - rect.height - 8))}px`; };\n    const move = (event: PointerEvent) => { x = event.clientX; y = event.clientY; if (!frame) frame = requestAnimationFrame(update); };\n    window.addEventListener(\"pointermove\", move, { passive: true }); this.cleanup = () => { window.removeEventListener(\"pointermove\", move); if (frame) cancelAnimationFrame(frame); }; update(); return card;\n  }\n  destroy(): void { this.cleanup?.(); this.cleanup = null; }\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { buildCard, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class ModalRenderer {\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState, widgetType: \"modal\" | \"survey\" = \"modal\"): HTMLElement {\n    if (behavior.backdrop !== false) {\n      const backdrop = document.createElement(\"div\");\n      backdrop.className = \"backdrop\";\n      backdrop.style.setProperty(\"--movcues-backdrop-opacity\", String(behavior.backdropOpacity ?? 0.45));\n      if (behavior.closeOnBackdrop && behavior.dismissible) backdrop.addEventListener(\"click\", callbacks.onDismiss);\n      root.appendChild(backdrop);\n    }\n    const card = buildCard(root, content, design, behavior, callbacks, builder, widgetType);\n    card.classList.add(\"modal\");\n    card.dataset.layout = behavior.modalLayout ?? \"center\";\n    return card;\n  }\n\n  destroy(): void {}\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { buildCard, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class SlideoutRenderer {\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState): HTMLElement {\n    if (behavior.backdrop) {\n      const backdrop = document.createElement(\"div\");\n      backdrop.className = \"backdrop\";\n      backdrop.style.setProperty(\"--movcues-backdrop-opacity\", String(behavior.backdropOpacity ?? 0.35));\n      if (behavior.closeOnBackdrop && behavior.dismissible) backdrop.addEventListener(\"click\", callbacks.onDismiss);\n      root.appendChild(backdrop);\n    }\n    const card = buildCard(root, content, design, behavior, callbacks, builder, \"slideout\");\n    card.classList.add(\"slideout\");\n    card.dataset.position = behavior.slideoutPosition ?? \"bottom-right\";\n    return card;\n  }\n\n  destroy(): void {}\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { AnchoredCardRenderer, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class HotspotRenderer {\n  private cleanup: Array<() => void> = [];\n  private cardRenderer: AnchoredCardRenderer | null = null;\n  private card: HTMLElement | null = null;\n\n  render(root: ShadowRoot, target: Element, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState): HTMLElement {\n    this.destroy();\n    const beacon = document.createElement(\"button\");\n    beacon.className = \"hotspot\";\n    beacon.dataset.style = behavior.hotspotStyle ?? \"pulse\";\n    beacon.style.setProperty(\"--movcues-hotspot\", behavior.hotspotColor ?? design.theme.primary);\n    beacon.type = \"button\";\n    beacon.setAttribute(\"aria-label\", `Open ${content.heading}`);\n    if (beacon.dataset.style === \"question\") beacon.textContent = \"?\";\n    root.appendChild(beacon);\n\n    let frameId: number | null = null;\n    let destroyed = false;\n    let lastLeft: number | null = null;\n    let lastTop: number | null = null;\n    const update = () => {\n      if (destroyed || !target.isConnected) return;\n      const rect = target.getBoundingClientRect();\n      const left = Math.max(4, Math.min(rect.right - 7, innerWidth - 18));\n      const top = Math.max(4, Math.min(rect.top - 7, innerHeight - 18));\n      if (left !== lastLeft) { lastLeft = left; beacon.style.left = `${left}px`; }\n      if (top !== lastTop) { lastTop = top; beacon.style.top = `${top}px`; }\n    };\n    const schedule = () => {\n      if (destroyed || frameId !== null) return;\n      frameId = requestAnimationFrame(() => { frameId = null; update(); });\n    };\n    const toggle = () => {\n      if (this.card) { this.card.remove(); this.card = null; this.cardRenderer?.destroy(); this.cardRenderer = null; return; }\n      this.cardRenderer = new AnchoredCardRenderer();\n      this.card = this.cardRenderer.render(root, target, content, design, behavior, callbacks, builder, \"hotspot\");\n    };\n    const onScroll = (event: Event) => {\n      const scrollContainer = event.target;\n      if (scrollContainer instanceof Element && !scrollContainer.contains(target)) return;\n      schedule();\n    };\n    beacon.addEventListener(\"click\", toggle);\n    window.addEventListener(\"scroll\", onScroll, { capture: true, passive: true });\n    window.addEventListener(\"resize\", schedule);\n    this.cleanup.push(\n      () => beacon.removeEventListener(\"click\", toggle),\n      () => window.removeEventListener(\"scroll\", onScroll, true),\n      () => window.removeEventListener(\"resize\", schedule),\n      () => { destroyed = true; if (frameId !== null) cancelAnimationFrame(frameId); frameId = null; },\n    );\n    if (typeof ResizeObserver !== \"undefined\") { const observer = new ResizeObserver(schedule); observer.observe(target); this.cleanup.push(() => observer.disconnect()); }\n    update();\n    return beacon;\n  }\n\n  destroy(): void { this.cardRenderer?.destroy(); this.cardRenderer = null; this.card = null; this.cleanup.splice(0).forEach((fn) => fn()); }\n}\n","import type { ExperienceBehavior, ExperienceContent, ExperienceDesign, WidgetBuilderState } from \"../types\";\nimport { buildCard, type RenderCallbacks } from \"./AnchoredCardRenderer\";\n\nexport class BannerRenderer {\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, callbacks: RenderCallbacks, builder?: WidgetBuilderState): HTMLElement {\n    const card = buildCard(root, content, design, behavior, callbacks, builder, \"banner\");\n    card.classList.add(\"banner\");\n    card.dataset.position = behavior.bannerPosition ?? \"top\";\n    return card;\n  }\n\n  destroy(): void {}\n}\n","import { answersOnSurveyPath, nextSurveyStep, surveyPath } from \"../survey/SurveyLogic\";\nimport type { ExperienceBehavior, ExperienceContent, ExperienceDesign, SurveyAnswers, SurveyConfig, SurveyQuestion } from \"../types\";\nimport { ModalRenderer } from \"./ModalRenderer\";\n\nexport interface SurveyResume { answers: SurveyAnswers; currentStepId?: string; closed?: boolean }\n\nexport interface SurveyCallbacks {\n  onLoad?: () => Promise<SurveyResume>;\n  onAnswersChange?: (answers: SurveyAnswers) => void;\n  onDismiss: () => Promise<void> | void;\n  onProgress: (answers: SurveyAnswers, currentStepId: string, direction: \"next\" | \"back\", destinationStepId?: string) => Promise<void> | void;\n  onSubmit: (answers: SurveyAnswers, currentStepId: string) => Promise<void> | void;\n  onStepChange?: (stepId: string) => void;\n}\n\nexport class SurveyRenderer {\n  private modal = new ModalRenderer();\n  private stepIndex = 0;\n  private answers: SurveyAnswers = {};\n  private root: ShadowRoot | null = null;\n  private content!: ExperienceContent;\n  private design!: ExperienceDesign;\n  private behavior!: ExperienceBehavior;\n  private survey!: SurveyConfig;\n  private callbacks!: SurveyCallbacks;\n  private busy = false;\n  private completed = false;\n  private generation = 0;\n  private retry: ((isCurrent: () => boolean) => Promise<void>) | null = null;\n\n  render(root: ShadowRoot, content: ExperienceContent, design: ExperienceDesign, behavior: ExperienceBehavior, survey: SurveyConfig, callbacks: SurveyCallbacks, requestedStepId?: string): HTMLElement | null {\n    if (!survey.steps.length) return null;\n    this.root = root; this.content = content; this.design = design; this.behavior = behavior; this.survey = survey; this.callbacks = callbacks;\n    const requested = requestedStepId ? survey.steps.findIndex(step => step.id === requestedStepId) : -1;\n    this.stepIndex = requested >= 0 ? requested : 0;\n    this.generation++; this.completed = false; this.answers = {}; this.busy = false; this.retry = null;\n    const card = this.renderStep();\n    if (callbacks.onLoad) void this.run(async isCurrent => {\n      const saved = await callbacks.onLoad!();\n      if (!isCurrent()) return;\n      this.answers = saved.answers;\n      const index = survey.steps.findIndex(step => step.id === saved.currentStepId);\n      if (index >= 0) this.stepIndex = index;\n      if (!saved.closed) this.renderStep();\n    });\n    return card;\n  }\n\n  private renderStep(): HTMLElement {\n    const root = this.root!; const step = this.survey.steps[this.stepIndex];\n    this.callbacks.onStepChange?.(step.id);\n    const baseStyle = root.firstElementChild;\n    Array.from(root.children).forEach(element => { if (element !== baseStyle) element.remove(); });\n    const content: ExperienceContent = { heading: step.content.heading || this.content.heading, body: step.content.body || this.content.body };\n    const stepDesign = step.size ? { ...this.design, size: step.size } : this.design;\n    const card = this.modal.render(root, content, stepDesign, this.behavior, { onDismiss: this.dismiss, onPrimary: this.dismiss, onSecondary: this.dismiss }, step.builder, \"survey\");\n    let surface = card.querySelector<HTMLElement>(\".movcues-widget\");\n    if (!surface) { card.querySelector(\".legacy-content\")?.remove(); surface = document.createElement(\"section\"); surface.className = \"movcues-widget movcues-widget--survey\"; card.appendChild(surface); }\n    surface.dataset.movcuesSurveyStepId = step.id;\n    this.syncQuestions(surface, step.questions);\n    if (!surface.querySelector('.movcues-survey-validation')) { const status = document.createElement('p'); status.className = 'movcues-survey-validation'; surface.append(status); }\n    surface.querySelector('.movcues-survey-validation')?.setAttribute('role', 'alert');\n    this.syncNavigation(surface);\n    return card;\n  }\n\n  private syncQuestions(surface: HTMLElement, questions: SurveyQuestion[]): void {\n    const ids = new Set(questions.map(question => question.id));\n    surface.querySelectorAll<HTMLElement>(\"[data-movcues-question-id]\").forEach(node => { if (!ids.has(node.dataset.movcuesQuestionId ?? \"\")) node.remove(); });\n    let navigation = surface.querySelector<HTMLElement>(\"[data-movcues-survey-action]\");\n    while (navigation && navigation.parentElement !== surface) navigation = navigation.parentElement;\n    for (const question of questions) {\n      const matches = Array.from(surface.querySelectorAll<HTMLElement>(`[data-movcues-question-id=\"${cssEscape(question.id)}\"]`));\n      matches.slice(1).forEach(node => node.remove());\n      const node = matches[0] ?? createQuestionNode(question);\n      if (!matches[0]) surface.insertBefore(node, navigation);\n      node.dataset.movcuesQuestionType = question.type;\n      node.classList.add(\"movcues-survey-question\", `movcues-survey-question--${question.type}`);\n      this.bindQuestion(node, question);\n      navigation = navigation ?? node.nextElementSibling as HTMLElement | null;\n    }\n  }\n\n  private bindQuestion(node: HTMLElement, question: SurveyQuestion): void {\n    node.classList.remove(\"has-error\");\n    if (question.type === \"single_choice\" || question.type === \"multiple_choice\" || question.type === \"rating\" || question.type === \"nps\") {\n      const allowed = question.type === \"rating\" ? range(question.min, question.max).map(String) : question.type === \"nps\" ? range(0, 10).map(String) : question.options.map(option => option.id);\n      let controls = Array.from(node.querySelectorAll<HTMLElement>(\"[data-movcues-option-id]\"));\n      if (!controls.length) { const holder = document.createElement(\"div\"); holder.className = \"movcues-survey-options\"; for (const value of allowed) { const button = document.createElement(\"button\"); button.type = \"button\"; button.className = \"movcues-survey-option\"; button.dataset.movcuesOptionId = value; button.textContent = question.type === \"single_choice\" || question.type === \"multiple_choice\" ? question.options.find(option => option.id === value)?.label ?? value : value; holder.appendChild(button); } node.appendChild(holder); controls = Array.from(holder.children) as HTMLElement[]; }\n      controls.forEach(control => {\n        const optionId = control.dataset.movcuesOptionId!; control.setAttribute(\"role\", \"button\");\n        const update = () => { const answer = this.answers[question.id]; const selected = Array.isArray(answer) ? answer.includes(optionId) : String(answer ?? \"\") === optionId; control.classList.toggle(\"is-selected\", selected); control.setAttribute(\"aria-pressed\", String(selected)); };\n        update(); control.onclick = () => { if (!allowed.includes(optionId)) return; if (question.type === \"multiple_choice\") { const current = Array.isArray(this.answers[question.id]) ? this.answers[question.id] as string[] : []; this.answers[question.id] = current.includes(optionId) ? current.filter(value => value !== optionId) : [...current, optionId]; } else this.answers[question.id] = question.type === \"rating\" || question.type === \"nps\" ? Number(optionId) : optionId; this.callbacks.onAnswersChange?.({ ...this.answers }); node.classList.remove(\"has-error\"); this.syncNavigation(this.root!.querySelector<HTMLElement>(\".movcues-widget\")!); controls.forEach(item => { const value = item.dataset.movcuesOptionId!; const answer = this.answers[question.id]; const selected = Array.isArray(answer) ? answer.includes(value) : String(answer) === value; item.classList.toggle(\"is-selected\", selected); item.setAttribute(\"aria-pressed\", String(selected)); }); };\n      });\n      return;\n    }\n    let input = node.querySelector<HTMLInputElement | HTMLTextAreaElement>(\"[data-movcues-question-input]\");\n    if (!input) { input = question.type === \"long_text\" ? document.createElement(\"textarea\") : document.createElement(\"input\"); input.dataset.movcuesQuestionInput = \"\"; input.className = \"movcues-survey-input\"; node.appendChild(input); }\n    input.value = typeof this.answers[question.id] === \"string\" ? this.answers[question.id] as string : \"\";\n    input.placeholder = question.placeholder ?? \"\"; if (question.maxLength) input.maxLength = question.maxLength;\n    input.oninput = () => { this.answers[question.id] = input!.value.slice(0, question.maxLength ?? 10_000); node.classList.remove(\"has-error\"); this.callbacks.onAnswersChange?.({ ...this.answers }); this.syncNavigation(this.root!.querySelector<HTMLElement>(\".movcues-widget\")!); };\n  }\n\n  private syncNavigation(surface: HTMLElement): void {\n    const nextIndex = nextSurveyStep(this.survey, this.stepIndex, this.answers);\n    const final = nextIndex === null;\n    const path = surveyPath(this.survey, this.answers), previousIndex = path[path.indexOf(this.stepIndex) - 1];\n    const step = this.survey.steps[this.stepIndex];\n    const buttons = Array.from(surface.querySelectorAll<HTMLButtonElement>(\"[data-movcues-survey-action]\"));\n    const back = buttons.filter(button => button.dataset.movcuesSurveyAction === \"back\");\n    const next = buttons.filter(button => button.dataset.movcuesSurveyAction === \"next\");\n    const submit = buttons.filter(button => button.dataset.movcuesSurveyAction === \"submit\");\n    const legacyControls = Boolean(surface.querySelector(\"[data-movcues-survey-controls]\"));\n    for (const button of back) {\n      button.hidden = !this.survey.allowBack || previousIndex === undefined;\n      button.onclick = () => {\n        if (this.busy || this.completed || !this.survey.allowBack || previousIndex === undefined) return;\n        void this.run(async isCurrent => {\n          await this.callbacks.onProgress({ ...this.answers }, step.id, \"back\", this.survey.steps[previousIndex].id);\n          if (!isCurrent()) return; this.stepIndex = previousIndex; this.renderStep();\n        });\n      };\n    }\n    for (const button of next) {\n      button.hidden = final;\n      button.onclick = () => {\n        if (this.busy || this.completed || nextIndex === null || !this.validateStep()) return;\n        void this.run(async isCurrent => {\n          this.answers = answersOnSurveyPath(this.survey, this.answers);\n          await this.callbacks.onProgress({ ...this.answers }, step.id, \"next\", this.survey.steps[nextIndex].id);\n          if (!isCurrent()) return; this.stepIndex = nextIndex; this.renderStep();\n        });\n      };\n    }\n    for (const button of submit) {\n      button.hidden = !final;\n      if (legacyControls) button.textContent = this.survey.submitLabel;\n      button.onclick = () => {\n        if (this.busy || this.completed || !this.validateAll()) return;\n        void this.run(async isCurrent => {\n          this.answers = answersOnSurveyPath(this.survey, this.answers);\n          await this.callbacks.onSubmit({ ...this.answers }, step.id);\n          if (isCurrent()) this.completed = true;\n        });\n      };\n    }\n    this.syncProgress(surface);\n  }\n\n  private dismiss = (): void => { if (!this.busy) void this.run(async () => { await this.callbacks.onDismiss(); }); };\n\n  private async run(operation: (isCurrent: () => boolean) => Promise<void>): Promise<void> {\n    if (this.busy || !this.root) return;\n    const generation = this.generation; this.busy = true; this.retry = operation;\n    this.setBusy(true);\n    this.root.querySelector('[data-movcues-survey-retry]')?.remove();\n    try { await operation(() => generation === this.generation && Boolean(this.root)); if (generation === this.generation) this.retry = null; }\n    catch {\n      if (generation !== this.generation || !this.root) return;\n      const status = this.root.querySelector<HTMLElement>('.movcues-survey-validation');\n      if (status) {\n        status.textContent = \"Couldn't save your answers. They are still here. Try again.\";\n        const retry = document.createElement('button'); retry.type = 'button'; retry.dataset.movcuesSurveyRetry = ''; retry.textContent = 'Retry';\n        retry.onclick = () => { if (this.retry) void this.run(this.retry); }; status.append(' ', retry);\n      }\n    } finally { if (generation === this.generation) { this.busy = false; this.setBusy(false); } }\n  }\n\n  private setBusy(value: boolean): void {\n    this.root?.querySelectorAll<HTMLButtonElement | HTMLInputElement | HTMLTextAreaElement>('[data-movcues-survey-action],[data-movcues-option-id],[data-movcues-question-input]').forEach(control => { control.disabled = value || this.completed; });\n  }\n\n  private syncProgress(surface: HTMLElement): void {\n    const progress = surface.querySelector<HTMLElement>(\"[data-movcues-survey-progress]\"); if (progress) progress.hidden = !this.survey.showProgress;\n    const progressLabel = progress?.querySelector<HTMLElement>(\"span:not([data-movcues-survey-progress-bar])\"); if (progressLabel && !progressLabel.querySelector(\"[data-movcues-survey-progress-bar]\")) progressLabel.textContent = `Step ${surveyPath(this.survey, this.answers).indexOf(this.stepIndex) + 1} of ${surveyPath(this.survey, this.answers).length}`;\n    const bar = surface.querySelector<HTMLElement>(\"[data-movcues-survey-progress-bar]\"); if (bar) bar.style.width = `${((surveyPath(this.survey, this.answers).indexOf(this.stepIndex) + 1) / surveyPath(this.survey, this.answers).length) * 100}%`;\n  }\n\n  private validateStep(): boolean { return this.validateQuestions(this.survey.steps[this.stepIndex].questions); }\n  private validateAll(): boolean { let valid = true; let currentValid = true; for (const index of surveyPath(this.survey, this.answers)) { const step = this.survey.steps[index]; const stepValid = this.validateQuestions(step.questions, step === this.survey.steps[this.stepIndex]); if (step === this.survey.steps[this.stepIndex]) currentValid = stepValid; if (!stepValid) valid = false; } if (!valid && currentValid && this.root) { const status = this.root.querySelector<HTMLElement>(\".movcues-survey-validation\"); if (status) status.textContent = \"Please go back and answer all required questions before submitting.\"; } return valid; }\n  private validateQuestions(questions: SurveyQuestion[], show = true): boolean {\n    const missing = questions.filter(question => question.required && isEmpty(this.answers[question.id]));\n    if (show && this.root) { missing.forEach(question => this.root!.querySelector<HTMLElement>(`[data-movcues-question-id=\"${cssEscape(question.id)}\"]`)?.classList.add(\"has-error\")); const status = this.root.querySelector<HTMLElement>(\".movcues-survey-validation\"); if (status) status.textContent = missing.length ? \"Please answer the required questions before continuing.\" : \"\"; }\n    return missing.length === 0;\n  }\n\n  destroy(): void { this.generation++; this.modal.destroy(); this.root = null; this.retry = null; }\n}\n\nfunction createQuestionNode(question: SurveyQuestion): HTMLElement { const node = document.createElement(\"div\"); node.dataset.movcuesQuestionId = question.id; const label = document.createElement(\"p\"); label.className = \"movcues-survey-question__label\"; label.textContent = `${question.label}${question.required ? \" *\" : \"\"}`; node.appendChild(label); return node; }\nfunction isEmpty(value: SurveyAnswers[string] | undefined): boolean { return value === undefined || value === \"\" || (Array.isArray(value) && value.length === 0); }\nfunction range(min: number, max: number): number[] { return Array.from({ length: max - min + 1 }, (_, index) => min + index); }\nfunction cssEscape(value: string): string { return typeof CSS !== \"undefined\" && CSS.escape ? CSS.escape(value) : value.replace(/[\"\\\\]/g, \"\\\\$&\"); }\n","import type { ExperienceTarget, GuideStep, PageRule } from \"../types\";\nimport { guideStepRequiresTarget } from \"../types\";\n\nexport function guideInteractionTarget(step: GuideStep): ExperienceTarget | undefined {\n  return step.advance?.type === \"element_click\" || step.advance?.type === \"element_hover\" ? step.advance.target ?? step.target : undefined;\n}\n\nexport function matchesGuideRoute(path: string, rules: PageRule[]): boolean {\n  const match = (rule: PageRule): boolean => {\n    if (rule.operator === \"equals\") return path === rule.value;\n    if (rule.operator === \"starts_with\") return path.startsWith(rule.value);\n    if (rule.operator === \"ends_with\") return path.endsWith(rule.value);\n    if (rule.operator === \"contains\") return path.includes(rule.value);\n    const escaped = rule.value.replace(/[.+?^${}()|[\\]\\\\]/g, \"\\\\$&\").replace(/\\*/g, \".*\");\n    try { return new RegExp(`^${escaped}$`).test(path); } catch { return false; }\n  };\n  return rules.some(rule => rule.kind === \"include\" && match(rule)) && !rules.some(rule => rule.kind === \"exclude\" && match(rule));\n}\n\n/** Draft validation deliberately allows unselected targets while authoring. */\nexport function guideStepConfigurationErrors(step: GuideStep, index: number): string[] {\n  const errors: string[] = []; const add = (message: string) => errors.push(`Step ${index + 1}: ${message}`);\n  const bounded = (value: number | undefined, min: number, max: number) => value === undefined || Number.isInteger(value) && value >= min && value <= max;\n  if (!bounded(step.presentation?.delayMs, 0, 30_000)) add(\"Presentation delay must