ailable?.();\n      };\n      const resolve = (spec: import(\"../types\").ExperienceTarget | undefined, found: (target: Element) => void) => {\n        if (!alive()) return; const target = findTarget(spec); if (target) { found(target); return; }\n        callbacks.onGuideStatus?.(\"waiting\");\n        this.cancelPendingTarget = waitForTarget(spec, element => { this.cancelPendingTarget = null; if (alive()) found(element); }, () => { this.cancelPendingTarget = null; unavailable(); }, Math.max(0, deadline - Date.now()));\n      };\n      resolve(step.target, target => {\n        const mount = (interaction?: Element) => {\n          if (!alive()) return; ensureGuideTargetInView(target);\n          const root = this.root(experience.id, { layer: step.behavior.layer ?? definition.behavior?.layer }, target); const renderer = new AnchoredCardRenderer(); this.renderer = renderer;\n          const behavior: ExperienceBehavior = { ...step.behavior, dismissible: step.behavior.dismissible ?? true };\n          const card = renderer.render(root, target, step.content, stepDesign, behavior, stepCallbacks, step.builder, \"anchored_card\"); addBack(card);\n          if (interaction) this.listenForAdvance(interaction, step.advance?.type ?? \"button\", step.advance?.type === \"element_hover\" ? step.advance.durationMs : undefined, advance);\n          visible();\n        };\n        const interaction = guideInteractionTarget(step);\n        if (interaction && interaction !== step.target) resolve(interaction, mount); else mount(interaction ? target : undefined);\n      });\n    };\n    const delay = Math.max(0, Math.min(30_000, step.presentation?.delayMs ?? 0));\n    if (delay) { callbacks.onGuideStatus?.(\"delay\"); this.guideTimer = window.setTimeout(run, delay); } else run();\n    return true;\n  }\n\n  private listenForAdvance(target: Element, type: string, durationMs: number | undefined, advance?: () => void): void {\n    if (!advance) return;\n    if (type === \"element_click\") {\n      let active = true;\n      const click = () => queueMicrotask(() => { if (active) advance(); });\n      target.addEventListener(\"click\", click);\n      this.cleanupAdvance = () => { active = false; target.removeEventListener(\"click\", click); };\n    } else if (type === \"element_hover\") {\n      let timer: number | null = null;\n      const leave = () => { if (timer !== null) window.clearTimeout(timer); timer = null; };\n      const enter = () => { leave(); timer = window.setTimeout(advance, durationMs ?? 500); };\n      target.addEventListener(\"mouseenter\", enter); target.addEventListener(\"mouseleave\", leave);\n      this.cleanupAdvance = () => { leave(); target.removeEventListener(\"mouseenter\", enter); target.removeEventListener(\"mouseleave\", leave); };\n    }\n  }\n\n  private callbacks(content: ExperienceContent, callbacks: ExperienceRendererCallbacks): BuilderRenderCallbacks {\n    return {\n      onDismiss: () => { callbacks.onDismiss(); this.destroy(); },\n      onSecondary: () => { callbacks.onDismiss(); this.destroy(); },\n      onPrimary: () => { if (content.primaryAction) callbacks.onAction(content.primaryAction); if (content.primaryAction?.type === \"dismiss\") { callbacks.onDismiss(); this.destroy(); } },\n      onActionId: (action, label) => this.dispatchBuilderAction(action, label, callbacks),\n    };\n  }\n\n  private dispatchBuilderAction(action: BuilderAction, label: string, callbacks: ExperienceRendererCallbacks): void {\n    const runtimeAction: ExperienceAction = { ...action, label };\n    if (action.type === \"next_step\") { callbacks.onAction(runtimeAction); callbacks.onGuideAdvance?.(); }\n    else if (action.type === \"previous_step\") { callbacks.onAction(runtimeAction); callbacks.onGuideBack?.(); }\n    else {\n      callbacks.onAction(runtimeAction);\n      if (action.type === \"dismiss\") { callbacks.onDismiss(); this.destroy(); }\n    }\n  }\n\n  private clearSurface(): void { this.renderGeneration++; clearTimeout(this.guideTimer); this.guideTimer = 0; cancelAnimationFrame(this.visibleFrame); this.visibleFrame = 0; this.cleanupAdvance?.(); this.cleanupAdvance = null; this.cancelPendingTarget?.(); this.cancelPendingTarget = null; this.renderer?.destroy(); this.renderer = null; this.appliedLayer?.destroy(); this.appliedLayer = null; this.host?.remove(); this.host = null; }\n  destroy(): void { this.clearSurface(); }\n}\n\nconst GUIDE_TARGET_VIEWPORT_MARGIN = 48;\n\nfunction ensureGuideTargetInView(target: Element): void {\n  const rect = target.getBoundingClientRect();\n  const comfortablyVisible = rect.width > 0 && rect.height > 0\n    && rect.top >= GUIDE_TARGET_VIEWPORT_MARGIN\n    && rect.left >= GUIDE_TARGET_VIEWPORT_MARGIN\n    && rect.bottom <= window.innerHeight - GUIDE_TARGET_VIEWPORT_MARGIN\n    && rect.right <= window.innerWidth - GUIDE_TARGET_VIEWPORT_MARGIN;\n  if (comfortablyVisible || typeof target.scrollIntoView !== \"function\") return;\n  const prefersReducedMotion = typeof matchMedia === \"function\" && matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  target.scrollIntoView({ behavior: prefersReducedMotion ? \"auto\" : \"smooth\", block: \"center\", inline: \"nearest\" });\n}\n\nconst STYLES = `\n  :host{all:initial}.card{pointer-events:auto;position:fixed;box-sizing:border-box;width:320px;max-width:calc(100vw - 16px);padding:18px;background:var(--movcues-bg);color:var(--movcues-fg);font:14px/1.45 ui-sans-serif,system-ui,sans-serif;box-shadow:0 12px 38px rgba(0,0,0,.22);border:1px solid rgba(0,0,0,.12)}\n  .card[data-width=sm]{width:260px}.card[data-width=lg]{width:400px}.card[data-radius=sm]{border-radius:6px}.card[data-radius=md]{border-radius:12px}.card[data-radius=lg]{border-radius:20px}\n  .builder-card{padding:0;background:transparent;border:0;box-shadow:none}.builder-content{box-sizing:border-box;width:100%;max-width:100%;overflow:visible}\n  .movcues-anchor-pointer{position:absolute;width:var(--movcues-pointer-size);height:var(--movcues-pointer-size);pointer-events:none;z-index:0}.movcues-anchor-pointer svg{display:block;width:100%;height:100%;overflow:visible}.movcues-anchor-pointer[data-placement=bottom]{top:calc(-1 * var(--movcues-pointer-size));transform:translateX(-50%)}.movcues-anchor-pointer[data-placement=top]{bottom:calc(-1 * var(--movcues-pointer-size));transform:translateX(-50%) rotate(180deg)}.movcues-anchor-pointer[data-placement=right]{left:calc(-1 * var(--movcues-pointer-size));transform:translateY(-50%) rotate(-90deg)}.movcues-anchor-pointer[data-placement=left]{right:calc(-1 * var(--movcues-pointer-size));transform:translateY(-50%) rotate(90deg)}.builder-content,.legacy-content{position:relative;z-index:1}\n  h2{font:600 17px/1.3 ui-sans-serif,system-ui,sans-serif;margin:0 24px 7px 0}p{margin:0;white-space:pre-wrap}footer{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}button{border:0;border-radius:7px;padding:8px 12px;font:600 13px ui-sans-serif,system-ui,sans-serif;cursor:pointer}.primary{background:var(--movcues-primary);color:#fff}.secondary{background:transparent;color:inherit}\n  .toast{position:fixed!important}.toast[data-position=top-left]{top:16px;left:16px}.toast[data-position=top-right]{top:16px;right:16px}.toast[data-position=bottom-left]{bottom:16px;left:16px}.toast[data-position=bottom-right]{bottom:16px;right:16px}.cursor{will-change:left,top}@media(prefers-reduced-motion:reduce){.card{transition:none!important}}\n  .backdrop{pointer-events:auto;position:fixed;inset:0;background:rgba(0,0,0,var(--movcues-backdrop-opacity,.45))}\n  .modal{left:50%;top:50%;transform:translate(-50%,-50%)}.modal[data-layout=fullscreen],.modal[data-size-width=full]{inset:12px;width:auto!important;max-width:none!important;transform:none;display:flex;flex-direction:column;justify-content:center}.modal[data-layout=fullscreen] footer,.modal[data-size-width=full] footer{justify-content:center}\n  .slideout[data-position=top-left]{top:16px;left:16px}.slideout[data-position=top-right]{top:16px;right:16px}.slideout[data-position=bottom-left]{bottom:16px;left:16px}.slideout[data-position=bottom-right]{bottom:16px;right:16px}.slideout[data-position=center-left]{left:16px;top:50%;transform:translateY(-50%)}.slideout[data-position=center-right]{right:16px;top:50%;transform:translateY(-50%)}\n  .banner{left:0;right:0;width:auto!important;max-width:none;border-radius:0!important;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:16px;align-items:center}.banner[data-position=top]{top:0}.banner[data-position=bottom]{bottom:0}.banner h2,.banner p{grid-column:1}.banner footer{grid-column:2;grid-row:1/span 2;margin:0;padding-right:24px}\n  .hotspot{pointer-events:auto;position:fixed;width:18px;height:18px;padding:0;border:3px solid #fff;border-radius:50%;background:var(--movcues-hotspot);box-shadow:0 1px 5px rgba(0,0,0,.35);color:#fff;font:700 12px/12px ui-sans-serif,system-ui,sans-serif}.hotspot[data-style=pulse]::after{content:\"\";position:absolute;inset:-7px;border:2px solid var(--movcues-hotspot);border-radius:50%;animation:movcues-pulse 1.8s ease-out infinite}.hotspot[data-style=dot]{width:14px;height:14px}.hotspot[data-style=question]{width:22px;height:22px}@keyframes movcues-pulse{0%{transform:scale(.65);opacity:.85}100%{transform:scale(1.45);opacity:0}}@media(prefers-reduced-motion:reduce){.hotspot::after{animation:none}}\n  .movcues-survey-question.has-error{outline:2px solid #fecaca;outline-offset:6px;border-radius:6px}.movcues-survey-validation{color:#b91c1c}:where(.movcues-survey-option.is-selected){border-color:var(--movcues-primary);background:color-mix(in srgb,var(--movcues-primary) 12%,white)}.movcues-survey-input{font:inherit}\n`;\n","import type { EditorDraft } from \"../types\";\nimport type { SiteThemeTokens } from \"../../themes/types\";\nimport type { EditorAiProposal } from \"./AiEditing\";\n\nexport interface EditorAiResponse { conversationId: string; revision: number; markdown: string; proposal: EditorAiProposal | null }\n\nexport class EditorBridge {\n  constructor(private apiBase: string, private sessionId: string, private accessToken: string) {}\n  private headers() { return { \"Content-Type\": \"application/json\", Authorization: `Bearer ${this.accessToken}` }; }\n  async load(): Promise<EditorDraft> {\n    const response = await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/draft`, { headers: this.headers(), credentials: \"omit\" });\n    if ([401, 403, 404, 410].includes(response.status)) throw new EditorSessionExpiredError();\n    if (!response.ok) throw new Error(\"Draft could not be loaded\"); return response.json() as Promise<EditorDraft>;\n  }\n  async save(definition: unknown, revision: number): Promise<EditorDraft[\"version\"]> {\n    const response = await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/draft`, { method: \"PATCH\", headers: this.headers(), credentials: \"omit\", body: JSON.stringify({ definition, revision }) });\n    if (!response.ok) {\n      const body = await response.json().catch(() => null) as { error?: string; currentRevision?: number } | null;\n      if (response.status === 409 && body?.error === \"draft_conflict\") throw new DraftConflictError(body.currentRevision);\n      if (response.status === 401 || response.status === 404 || response.status === 410 || (response.status === 403 && body?.error === \"invalid_editor_access\")) throw new EditorSessionExpiredError();\n      throw new Error(body?.error ? `Draft could not be saved: ${body.error}` : \"Draft could not be saved\");\n    }\n    const body = await response.json() as { version: EditorDraft[\"version\"] };\n    return body.version;\n  }\n  async chat(input: { conversationId?: string; prompt: string; revision: number; context: unknown }, signal?: AbortSignal): Promise<EditorAiResponse> {\n    const response = await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/ai/chat`, { method: \"POST\", headers: this.headers(), credentials: \"omit\", body: JSON.stringify(input), signal });\n    const body = await response.json().catch(() => null) as ({ error?: string; message?: string; currentRevision?: number } & Partial<EditorAiResponse>) | null;\n    if (response.status === 409 && body?.error === \"draft_conflict\") throw new DraftConflictError(body.currentRevision);\n    if ([401, 403, 404, 410].includes(response.status) && body?.error !== \"conversation_not_found\") throw new EditorSessionExpiredError();\n    if (!response.ok) throw new EditorAiRequestError(body?.message ?? \"Movcues AI could not complete this request.\", body?.conversationId);\n    return body as EditorAiResponse;\n  }\n  async saveStyle(name: string, tokens: SiteThemeTokens): Promise<{id:string;name:string;tokens:SiteThemeTokens}> {\n    const response=await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/style-presets`,{method:\"POST\",headers:this.headers(),credentials:\"omit\",body:JSON.stringify({name,tokens})});\n    if(!response.ok)throw new Error((await response.json().catch(()=>null) as {error?:string}|null)?.error??\"Style could not be saved\");return (await response.json() as {preset:{id:string;name:string;tokens:SiteThemeTokens}}).preset;\n  }\n  async renameStyle(id:string,name:string):Promise<{id:string;name:string;tokens:SiteThemeTokens}>{const response=await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/style-presets/${encodeURIComponent(id)}`,{method:\"PATCH\",headers:this.headers(),credentials:\"omit\",body:JSON.stringify({name})});if(!response.ok)throw new Error(\"Style could not be renamed\");return(await response.json() as {preset:{id:string;name:string;tokens:SiteThemeTokens}}).preset;}\n  async deleteStyle(id:string):Promise<void>{const response=await fetch(`${this.apiBase}/public/experience-editor/${encodeURIComponent(this.sessionId)}/style-presets/${encodeURIComponent(id)}`,{method:\"DELETE\",headers:this.headers(),credentials:\"omit\"});if(!response.ok)throw new Error(\"Style could not be deleted\");}\n}\n\nexport class DraftConflictError extends Error {\n  constructor(readonly currentRevision?: number) { super(\"Draft changed in another editor\"); }\n}\n\nexport class EditorSessionExpiredError extends Error {\n  constructor() { super(\"Editor session expired\"); }\n}\n\nexport class EditorAiRequestError extends Error {\n  constructor(message: string, readonly conversationId?: string) { super(message); }\n}\n\n","export class HighlightOverlay {\n  private element = document.createElement(\"div\");\n  constructor() {\n    this.element.dataset.movcuesPickerOverlay = \"\";\n    this.element.style.cssText = \"position:fixed;pointer-events:none;z-index:2147483646;border:2px solid #2563eb;background:rgba(37,99,235,.12);display:none;box-sizing:border-box\";\n    document.documentElement.appendChild(this.element);\n  }\n  show(target: Element): void { const rect = target.getBoundingClientRect(); Object.assign(this.element.style, { display: \"block\", left: `${rect.left}px`, top: `${rect.top}px`, width: `${rect.width}px`, height: `${rect.height}px` }); }\n  hide(): void { this.element.style.display = \"none\"; }\n  destroy(): void { this.element.remove(); }\n}\n","const SENSITIVE_INPUT_TYPES = new Set([\"password\", \"email\", \"tel\", \"credit-card\", \"cc-number\"]);\nconst SENSITIVE_TAGS = new Set([\"INPUT\", \"TEXTAREA\", \"SELECT\"]);\nconst PRIVATE_ATTRIBUTES = [\"data-private\", \"data-ignore\", \"data-analytics-ignore\"];\n\n/**\n * Pure DOM inspection helpers used by PrivacyFilter. No event knowledge here -\n * just \"is this node, or a value derived from it, sensitive\".\n */\nexport class SensitiveElementDetector {\n  isSensitiveFormElement(el: Element): boolean {\n    const tag = el.tagName;\n    if (!SENSITIVE_TAGS.has(tag)) return false;\n    if (tag === \"INPUT\") {\n      const type = (el.getAttribute(\"type\") || \"text\").toLowerCase();\n      if (SENSITIVE_INPUT_TYPES.has(type)) return true;\n      // Any free-text input is treated conservatively as potentially sensitive.\n      if (type === \"text\" || type === \"search\" || type === \"number\") return true;\n    }\n    return tag === \"TEXTAREA\" || tag === \"SELECT\" ? false : false || tag === \"INPUT\";\n  }\n\n  hasPrivacyMarker(el: Element): boolean {\n    return PRIVATE_ATTRIBUTES.some((attr) => el.hasAttribute(attr));\n  }\n\n  /** Walk up the tree - if any ancestor (or the element itself) is marked private, the whole subtree is private. */\n  isWithinPrivateSubtree(el: Element): boolean {\n    let node: Element | null = el;\n    while (node) {\n      if (this.hasPrivacyMarker(node)) return true;\n      node = node.parentElement;\n    }\n    return false;\n  }\n}\n","import { SensitiveElementDetector } from \"../privacy/SensitiveElementDetector\";\n\nconst MAX_LABEL_LENGTH = 60;\nconst OVERRIDE_ATTR = \"data-movcues-name\";\nconst detector = new SensitiveElementDetector();\n\nfunction clean(text: string | null | undefined): string | undefined {\n  if (!text) return undefined;\n  const trimmed = text.replace(/\\s+/g, \" \").trim();\n  if (!trimmed) return undefined;\n  return trimmed.length > MAX_LABEL_LENGTH ? `${trimmed.slice(0, MAX_LABEL_LENGTH - 1)}\\u2026` : trimmed;\n}\n\n/**\n * Computes a human-readable display label for an element. This is\n * purely for display in the dashboard - `SelectorGenerator` remains\n * the source of truth for element *identity* (grouping/matching stays\n * selector-based and stable); a label is just a friendlier name to\n * show next to that selector.\n *\n * Priority order mirrors how other behavioral analytics platforms name\n * autocaptured elements (explicit override > accessibility metadata >\n * visible text > semantic fallback):\n *\n *   1. data-movcues-name        - explicit developer override, always wins\n *   2. aria-label / aria-labelledby\n *   3. visible text content   - skipped entirely for elements within a\n *                                privacy-marked subtree (data-private\n *                                etc. - see SensitiveElementDetector)\n *   4. alt / title / placeholder\n *   5. tag + role fallback, e.g. \"Button\", \"Link\", \"Submit button\"\n *\n * Always returns *something* (falls through to the tag name itself in\n * the worst case) so callers never have to handle \"no label at all\".\n */\nexport function computeElementLabel(el: Element): string {\n  const override = clean(el.getAttribute(OVERRIDE_ATTR));\n  if (override) return override;\n\n  const ariaLabel = clean(el.getAttribute(\"aria-label\"));\n  if (ariaLabel) return ariaLabel;\n\n  const labelledBy = el.getAttribute(\"aria-labelledby\");\n  if (labelledBy) {\n    const labelText = labelledBy\n      .split(/\\s+/)\n      .map((id) => document.getElementById(id)?.textContent)\n      .filter(Boolean)\n      .join(\" \");\n    const cleaned = clean(labelText);\n    if (cleaned) return cleaned;\n  }\n\n  if (!detector.isWithinPrivateSubtree(el)) {\n    const text = clean(el.textContent);\n    if (text) return text;\n  }\n\n  const alt = clean(el.getAttribute(\"alt\"));\n  if (alt) return alt;\n  const title = clean(el.getAttribute(\"title\"));\n  if (title) return title;\n  const placeholder = clean(el.getAttribute(\"placeholder\"));\n  if (placeholder) return placeholder;\n\n  return semanticFallback(el);\n}\n\nfunction semanticFallback(el: Element): string {\n  const tag = el.tagName.toLowerCase();\n  const role = el.getAttribute(\"role\");\n\n  if (tag === \"button\" || role === \"button\") {\n    return el.getAttribute(\"type\") === \"submit\" ? \"Submit button\" : \"Button\";\n  }\n  if (tag === \"a\" || role === \"link\") return \"Link\";\n  if (tag === \"input\") {\n    const type = (el.getAttribute(\"type\") || \"text\").toLowerCase();\n    return `${type.charAt(0).toUpperCase()}${type.slice(1)} field`;\n  }\n  if (tag === \"select\") return \"Dropdown\";\n  if (tag === \"textarea\") return \"Text field\";\n\n  return tag.charAt(0).toUpperCase() + tag.slice(1);\n}\n\n/**\n * Computes a coarse semantic role for an element - explicit `role`\n * attribute when present, else a small tag-based mapping. Kept\n * intentionally simple (no full ARIA computed-role algorithm); good\n * enough to distinguish \"this is a button-like thing\" from \"this is a\n * text input\" for analysis purposes without pulling in a full\n * accessibility-tree implementation.\n */\nexport function computeElementRole(el: Element): string | undefined {\n  const explicit = el.getAttribute(\"role\");\n  if (explicit) return explicit;\n\n  const tag = el.tagName.toLowerCase();\n  if (tag === \"button\") return \"button\";\n  if (tag === \"a\") return \"link\";\n  if (tag === \"input\") return `input:${(el.getAttribute(\"type\") || \"text\").toLowerCase()}`;\n  if (tag === \"select\") return \"select\";\n  if (tag === \"textarea\") return \"textarea\";\n  return undefined;\n}\n","import { computeElementLabel, computeElementRole } from \"../../dom/ElementLabeler\";\nimport type { ExperienceTarget } from \"../types\";\n\nconst STABLE_DATA_ATTRS = [\"data-testid\", \"data-test\", \"data-qa\", \"data-cy\", \"data-analytics-id\"];\nconst SEMANTIC_ATTRS = [\"role\", \"aria-label\", \"name\", \"type\", \"href\"];\nconst DYNAMIC_CLASS_PATTERN = /^(css-|sc-|jsx-|_|[a-z0-9]{6,}$)/i;\nconst UTILITY_CLASS_PATTERN = /^(sm:|md:|lg:|xl:|2xl:|hover:|focus:|active:|disabled:|dark:|-?(m|p)[trblxy]?-|w-|h-|min-|max-|inset-|top-|right-|bottom-|left-|z-|gap-|space-|grid|flex|items-|justify-|text-|font-|leading-|tracking-|bg-|border|rounded|shadow|opacity-|transition|duration-|absolute$|relative$|fixed$|sticky$|hidden$|block$|inline)/;\n\ninterface SelectorCandidate {\n  selector: string;\n  reliability: ExperienceTarget[\"reliability\"];\n}\n\nexport interface TargetSelectorDescriptor extends ExperienceTarget {\n  primarySelector: string;\n}\n\n/** Generates selectors for experience anchoring only. Every emitted selector\n * is verified to resolve uniquely to the exact element that was selected. */\nexport class TargetSelectorGenerator {\n  generate(element: Element): Pick<ExperienceTarget, \"primarySelector\" | \"fallbackSelectors\" | \"reliability\"> {\n    const verified: SelectorCandidate[] = [];\n    const seen = new Set<string>();\n    const add = (selector: string, reliability: ExperienceTarget[\"reliability\"]) => {\n      if (!selector || seen.has(selector)) return;\n      seen.add(selector);\n      if (uniquelyMatches(selector, element)) verified.push({ selector, reliability });\n    };\n    const tag = element.tagName.toLowerCase();\n\n    const id = shortValue(element.getAttribute(\"id\"));\n    if (id) add(`${tag}#${cssIdentifier(id)}`, \"reliable\");\n\n    for (const selector of attributeSelectors(element, STABLE_DATA_ATTRS)) add(selector, \"reliable\");\n    const semantics = attributeSelectors(element, SEMANTIC_ATTRS);\n    for (const selector of semantics) add(selector, \"moderate\");\n    for (const selector of attributeCombinations(element, SEMANTIC_ATTRS)) add(selector, \"moderate\");\n    for (const selector of classSelectors(element)) add(selector, \"moderate\");\n\n    const childSelectors = [...semantics, ...attributeCombinations(element, SEMANTIC_ATTRS), ...classSelectors(element), tag];\n    let ancestor = element.parentElement;\n    let depth = 1;\n    while (ancestor && ancestor !== document.documentElement && depth <= 4) {\n      const relation = depth === 1 ? \" > \" : \" \";\n      for (const parentSelector of identitySelectors(ancestor)) {\n        for (const childSelector of childSelectors) add(`${parentSelector}${relation}${childSelector}`, \"moderate\");\n      }\n      ancestor = ancestor.parentElement;\n      depth++;\n    }\n\n    for (const selector of structuralSelectors(element)) add(selector, \"fragile\");\n    const primary = verified[0];\n    if (!primary) throw new Error(\"Could not generate a unique selector for the selected element\");\n    return { primarySelector: primary.selector, fallbackSelectors: verified.slice(1, 6).map(item => item.selector), reliability: primary.reliability };\n  }\n\n  describe(element: Element): TargetSelectorDescriptor {\n    return {\n      ...this.generate(element),\n      label: computeElementLabel(element),\n      role: computeElementRole(element),\n      tagName: element.tagName.toLowerCase(),\n    };\n  }\n}\n\nfunction attributeSelectors(element: Element, attributes: string[]): string[] {\n  const tag = element.tagName.toLowerCase();\n  return attributes.flatMap(attribute => {\n    const value = shortValue(element.getAttribute(attribute));\n    return value ? [`${tag}[${attribute}=\"${cssString(value)}\"]`] : [];\n  });\n}\n\nfunction attributeCombinations(element: Element, attributes: string[]): string[] {\n  const tag = element.tagName.toLowerCase();\n  const present = attributes.flatMap(attribute => {\n    const value = shortValue(element.getAttribute(attribute));\n    return value ? [{ attribute, value }] : [];\n  });\n  const selectors: string[] = [];\n  for (let first = 0; first < present.length; first++) {\n    for (let second = first + 1; second < present.length; second++) {\n      selectors.push(`${tag}[${present[first].attribute}=\"${cssString(present[first].value)}\"][${present[second].attribute}=\"${cssString(present[second].value)}\"]`);\n    }\n  }\n  return selectors;\n}\n\nfunction classSelectors(element: Element): string[] {\n  const tag = element.tagName.toLowerCase();\n  const classes = (element.getAttribute(\"class\") ?? \"\").split(/\\s+/).filter(isStableClass).slice(0, 4);\n  if (!classes.length) return [];\n  const selectors = [`${tag}.${classes.map(cssIdentifier).join(\".\")}`];\n  if (classes.length > 1) {\n    for (let first = 0; first < classes.length; first++) for (let second = first + 1; second < classes.length; second++) selectors.push(`${tag}.${cssIdentifier(classes[first])}.${cssI